WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[27982] = { title = "Twilight Collars", description = "Have ye seen the ridiculous necklaces those Twilight's Hammer cultists all wear?  The gems on those things are bigger than Hansel's fist!\n\nA few hamburger-sized jewels like that, and Burninate over there could really push his blacksmithing business to the next level.  Fetch those collars, and he'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[27983] = { title = "Lunk's Adventure: Cranky Little Dwarfs", description = "What you doing?  Why you kill?\n\nYou need to get things from dwarfs?  Ah, Lunk understand.  Lunk have a better way.\n\nListen: you go fight dwarf, but do not kill!  Just fight until dwarf get tired.  Then Lunk will help dwarf fall asleep.  Dwarfs probably just cranky because they don't get sleep.\n\nCome on!  Trust Lunk.", objectives = "" }
WordHunterWoW_QuestEN[27984] = { title = "Lunthistle's Tale", description = "Will you assist me, mortal? Hear my tale.", objectives = "" }
WordHunterWoW_QuestEN[27985] = { title = "Prayer to Elune", description = "Will you assist me, mortal?  Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet.  I believe they hold it within one of their vile chests, near the entrance to their cave at the bottom of the ridge.\n\nIf you do recover my prayer, don't bring it back to me.  Instead, take the time to read through it.\n\nAbsolution may be asking too much, based on the sins I've committed.  But that won't stop me from holding out hope.", objectives = "" }
WordHunterWoW_QuestEN[27986] = { title = "In the Hall of the Mountain-Lord", description = "The Thorium Brotherhood doesn't maintain a militia - just a few guards, and me, and that's it.  If we're to successfully strike against the Dark Irons of the gorge, we're gonna need help.\n\nMountain-Lord Rendan sits atop that tower across the gorge, to our south.  He doesn't consort with Twilight folks or fire elementals, but he hasn't joined the brotherhood either.  Maybe it's time we paid him a visit.  With his help, we might just stand a chance.", objectives = "" }
WordHunterWoW_QuestEN[27987] = { title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for horde too.", objectives = "" }
WordHunterWoW_QuestEN[27988] = { title = "Plague...Plague Everywhere!", description = "The best part about this plague is that even when it visually fades away, the remaining residue is still quite potent! However, we still have an enormous area to cover before we're done, with plenty of Godfrey's defenses in the way.\n\nIt appears that the spirits that served Baron Silverlaine and Commander Springvale in life now guard them in death, and Godfrey is using them to deter us. Show them all the iron will of the Forsaken!", objectives = "" }
WordHunterWoW_QuestEN[27989] = { title = "Ruumbo Demands Honey", description = "Ruumbo hungers!\n\nThe Deadwood jerks have stolen all their honey from the Timbermaw tribe! We saw...er, Ruumbo saw them do it! Now Ruumbo must have that honey!\n\nTake this... this stick! Yes, this stick. Take this stick and use it to steal the honey from their beehives in Deadwood Village.\n\nRuumbo must have as much honey as possible. This is vital.", objectives = "" }
WordHunterWoW_QuestEN[27990] = { title = "Battlezone", description = "It vould appear zhat anozher opportunity has arisen for you to redeem yourself, {race}.\n\nZhis little emergency has set me back a few tank gunnahs.\n\nYou zhink you have vhat it takes to fill in for vone of zhem?\n\nMy tanks are just vest of zhe camp. Get out zhere and put an end to zhis silliness!", objectives = "" }
WordHunterWoW_QuestEN[27991] = { title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", objectives = "" }
WordHunterWoW_QuestEN[27992] = { title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", objectives = "" }
WordHunterWoW_QuestEN[27993] = { title = "Take it to 'Em!", description = "We was lucky to escape, {class}. I'm not sure I'd feel right if we didn't take care of them ambushers.\n\nHows about you git back up to Khartut's tomb and give them little buggers what fer!\n\nIt's off to the northeast, just inside the entrance to Uldum if'n I recollect correctly.\n\nWhat're you looking at? I sure ain't in no condition to do it!", objectives = "" }
WordHunterWoW_QuestEN[27994] = { title = "Ruumbo Demands Justice", description = "You! Wanderer! Bow before the might of Ruumbo, great god of the Timbermaw tribe!\n\nHear my will! The evil Deadwood tribe lives in the village behind me! They are big jerks!\n\nI mean, they... they sully my name with their wicked misdeeds! They persecute my cherished Timbermaw tribe and hurt them!\n\nI demand you inflict my justice! Defeat the Deadwood and I will give you my... my favor! Yes! The favor of RUUMBO! ", objectives = "" }
WordHunterWoW_QuestEN[27995] = { title = "Dance for Ruumbo!", description = "You have done well, {race}! Ruumbo is pleased by your bravery, and the delicious honey you have given Ruumbo.\n\nNow, you must... you must dance! Yes!\n\nDance for Ruumbo! Dance!", objectives = "" }
WordHunterWoW_QuestEN[27996] = { title = "Orders Are For the Living", description = "Unsurprisingly, we aren't going to listen to Cromush about the plague. However, his brute strength will come in handy for muscling my men through the many foes ahead on the path to Godfrey, the most powerful being his right hand man, Lord Walden.\n\nI'll meet you in Walden's chamber after you finish him off. Then, at long last, we can completely take Shadowfang Keep for the Forsaken!", objectives = "" }
WordHunterWoW_QuestEN[27997] = { title = "The Corruption of the Jadefire", description = "The cleansing of this forest has been a grueling process. For every success we have achieved, a new challenge has arisen.\n\nThe Jadefire satyr have been a constant nuisance. They seek to corrupt the forest just as we seek to cleanse it. Now, we have taken steps to begin eradicating them from Felwood entirely.\n\nTravel to Jadefire Glen to the west and rid the forest of their presence. You'll find the entrance just north of the walls of Deadwood Village; look for their vile banners.", objectives = "" }
WordHunterWoW_QuestEN[27998] = { title = "Sweet, Merciless Revenge", description = "If all goes well you'll just be able to walk right into Godfrey's personal domain and take a reward fitting for such an eager young {class}.\n\nGodfrey is a cunning foe, though, so it may be wise to head up there quickly just in case you're needed. He will pay for what he did to the Dark Lady!", objectives = "" }
WordHunterWoW_QuestEN[27999] = { title = "The Fate of the Doyles", description = "It seems the Doyles already joined their last fight. Iain will want to know of their fate.", objectives = "" }
WordHunterWoW_QuestEN[28000] = { title = "Do the Imp-Possible", description = "The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it.\n\nInterrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well...\n\nIn the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...", objectives = "" }
WordHunterWoW_QuestEN[28001] = { title = "A Coward's Due", description = "We may be safe here, but there are a lot of Wildhammer who could still use support. Our wing can offer that, but we need to keep bolsterin' our forces if we're going to clear the Twilight completely.\n\nI'm going to have words with Colin Thundermar. Only a coward turns down the callin' of his people, especially in a time this dire.\n\nGo to Thundermar, find Colin and get a real explanation out of'm. I won't be putting up with cowardice in a Wildhammer leader.", objectives = "" }
WordHunterWoW_QuestEN[28002] = { title = "Crisis Management", description = "There is a delicate situation that calls for the... objective discretion of an outsider.\n\nYou see, an unfortunate incident has upset some of our guests. Rest assured, our top men are sorting out the details.\n\nIn the meantime, it would be wonderful if you could calm our more squeamish visitors.\n\nHandle this well, and the furrier is sure to hear of it!", objectives = "" }
WordHunterWoW_QuestEN[28003] = { title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28004] = { title = "Adventurers Wanted: The Deadmines", description = "The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[28005] = { title = "Adventurers Wanted: The Deadmines", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28006] = { title = "Adventurers Wanted: Wailing Caverns", description = "The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", objectives = "" }
WordHunterWoW_QuestEN[28007] = { title = "Adventurers Wanted: Wailing Caverns", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", objectives = "" }
WordHunterWoW_QuestEN[28008] = { title = "Adventurers Wanted: Shadowfang Keep", description = "The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.", objectives = "" }
WordHunterWoW_QuestEN[28009] = { title = "Adventurers Wanted: Shadowfang Keep", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to our new allies! If you so choose, head to Shadowfang Keep and speak with Packleader Ivar Bloodfang, leader of the war effort there, to help enact proper revenge.", objectives = "" }
WordHunterWoW_QuestEN[28010] = { title = "Adventurers Wanted: Blackfathom Deeps", description = "The Warchief has requested that any able-bodied adventurer head to Blackfathom Deeps, north of Zoram'gar Outpost, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Je'neu Sancrea, a member of the Earthen Ring, to help stop the Twilight threat.", objectives = "" }
WordHunterWoW_QuestEN[28011] = { title = "Adventurers Wanted: Blackfathom Deeps", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackfathom Deeps, west of Astranaar, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Sentinel Aluwyn, head of the night elf effort there, to help stop the Twilight threat.", objectives = "" }
WordHunterWoW_QuestEN[28012] = { title = "Adventurers Wanted: Stormwind Stockade", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Stormwind Stockade, inside his highness' own city, immediately!\n\nA mass riot has begun within! If you so choose, head to the Stockade and speak with Rifle Commander Coe, head rifleman of the Stockade guard, to help quell the uprising.", objectives = "" }
WordHunterWoW_QuestEN[28013] = { title = "Adventurers Wanted: Gnomeregan", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Gnomeregan,west of Ironforge, immediately!\n\nThe Gnomes need help reclaiming their city! If you so choose, head to Gnomeregan and speak with Murd Doc, recruiter for the G-Team, to help in the mission.", objectives = "" }
WordHunterWoW_QuestEN[28014] = { title = "Adventurers Wanted: Razorfen Kraul", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", objectives = "" }
WordHunterWoW_QuestEN[28015] = { title = "Adventurers Wanted: Razorfen Kraul", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", objectives = "" }
WordHunterWoW_QuestEN[28017] = { title = "Adventurers Wanted: Scarlet Halls", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Halls, northeast of the Undercity, immediately!\n\nCrusader activity has picked up throughout the plaguelands and elsewhere. The Warchief believes a revival is underway, and this will NOT be tolerated.\n\nEnter the Scarlet Halls to crush their armory and lay waste to their library before they can mobilize.", objectives = "" }
WordHunterWoW_QuestEN[28019] = { title = "Adventurers Wanted: Scarlet Monastery", description = "The Warchief demands that able-bodied adventurers assault the Scarlet Monastery, northeast of the Undercity, immediately!\n\nThe Scarlet Crusade has continually threatened Forsaken strongholds throughout the plaguelands. They MUST be destroyed.\n\nReport to the Scarlet Monastery to execute the Warchief's orders and crush the crusade once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28021] = { title = "Adventurers Wanted: Scarlet Halls", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Scarlet Halls, northeast of the Undercity, immediately!\n\nCrusader activity has picked up throughout the plaguelands and elsewhere. His majesty fears a revival is underway. Scarlet zealotry will not be tolerated near the King's lands!\n\nEnter the Scarlet Halls and assault the armory and library before they can mobilize.", objectives = "" }
WordHunterWoW_QuestEN[28023] = { title = "Adventurers Wanted: Scarlet Monastery", description = "King Anduin Wrynn has requested able-bodied adventurers to assault the Scarlet Monastery, northeast of the Undercity, immediately!\n\nRepeated efforts to negotiate with the Scarlet Crusade have failed. Their zealotry is wreaking havoc across the reclaimed plaguelands and elsewhere.\n\nReport to the Scarlet Monastery to dish out the King's justice. Use of deadly force is encouraged!", objectives = "" }
WordHunterWoW_QuestEN[28024] = { title = "Adventurers Wanted: Razorfen Downs", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", objectives = "" }
WordHunterWoW_QuestEN[28025] = { title = "Adventurers Wanted: Razorfen Downs", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", objectives = "" }
WordHunterWoW_QuestEN[28026] = { title = "Adventurers Wanted: Uldaman", description = "The Warchief has requested that any able-bodied adventurer head to Uldaman, near New Kargath, immediately!\n\nThe Reliquary and its leader, High Examine Tae'thelan Bloodwatcher, requires assistance in obtaining powerful relics within! If you so choose, head to Uldaman and speak with the High Examiner to aid their cause.", objectives = "" }
WordHunterWoW_QuestEN[28027] = { title = "Adventurers Wanted: Uldaman", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Uldaman, in the Badlands, immediately!\n\nThe Explorers' League, under Lead Prospector Durdin, requires assistance in braving great danger in pursuit of knowledge! If you so choose, head to Uldaman and speak with Lead Prospector Durdin to help them out.", objectives = "" }
WordHunterWoW_QuestEN[28028] = { title = "Siege!", description = "That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight.  My summit's already under siege!\n\nIt's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge.\n\nTell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer.  Ye'll find 'em slinkin' around the flats to the east.", objectives = "" }
WordHunterWoW_QuestEN[28029] = { title = "Set Them Ablaze!", description = "I'm not sure if ye've noticed, but my tower's much taller than any o' the other towers here around the Gorge.  Some dwarves pride themselves at how deep they can dig, but not me.  Sometimes I think I shoulda been born a Wildhammer.\n\nI still don't like the sight o' those other towers, though.  Reachin' up like that, ticklin' my tower's feet.  Here, take this torch, an' use it on the braziers atop those other towers.  They'll be sorry they ever built 'em to begin with.", objectives = "" }
WordHunterWoW_QuestEN[28030] = { title = "They Build a Better Bullet", description = "Those gorge-digging dwarves do at least one thing right: they make very high-quality bullets.  I've been unable to reproduce their results, so I've taken to stealing whatever bullets of theirs that I can find.\n\nYe want my help?  Get me a couple hundred bullets from those marksmen below.\n\nI'm sure they'll be happy to give ye their bullets one at a time, but you might find it faster just to look for the crates filled with them.", objectives = "" }
WordHunterWoW_QuestEN[28031] = { title = "Special Delivery for Brivelthwerp", description = "I have a new business partner, my best buddy, Brivelthwerp. Even as we speak, he's building up the infrastructure for our new ice cream empire!\n\nHe took our coolant tug, inventory, and employees southwest to the Sunken Dig Site. Unfortunately, I don't currently have a way to deliver something to him... something extremely important: our super-secret I-Scream Cryocannon!\n\nYou don't mind taking it to him, do you, {name}?", objectives = "" }
WordHunterWoW_QuestEN[28032] = { title = "The Mysteries of the Fire-Gizzard", description = "There's so much we don't know about the incendosaurs.  Where did they come from?  How do they survive out here on the flats?  And why do they taste so bad?\n\nThe key to understanding these prehistoric beasts, I believe, starts with the fire-gizzard.  Every incendosaur has one.  I'd like a few of them to study.\n\nYou'll find incendosaurs circling the foot of Iron Summit, mostly to the west.", objectives = "" }
WordHunterWoW_QuestEN[28033] = { title = "Deceit", description = "What?  Why're you still here?  Oh, did I promise that I'd help you and the Thorium Brotherhood in yer fight?\n\nI lied.\n\nI just can't spare the men right now.  I know I said I'd help, but there's absolutely no way you can convince me to leave Iron Summit right now.  Absolutely no way.", objectives = "" }
WordHunterWoW_QuestEN[28034] = { title = "Lunk's Adventure: Rendan's Weakness", description = "Lunk not smart, but Lunk notice things.  Today, Lunk notice that Mountain-Dwarf likes to watch people dance.\n\nLunk like to dance!  {name} like to dance!  Probably!\n\nMaybe we find some more dwarfs that like to dance.  Then we go talk to Mountain-Dwarf, and he will listen to {name}.", objectives = "" }
WordHunterWoW_QuestEN[28035] = { title = "The Mountain-Lord's Support", description = "Alright, alright!  If I knew ye could dance like that, I wouldn't'a asked ye to do all that stuff earlier.\n\nTell Overseer Oilfist that I'll be joinin' ye.  I'll meet ye in the slag pit, lad!  With the combined forces of Thorium Point and Iron Summit, those gorge-dwarves won't know what hit 'em!", objectives = "" }
WordHunterWoW_QuestEN[28036] = { title = "Adventurers Wanted: Zul'farrak", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", objectives = "" }
WordHunterWoW_QuestEN[28037] = { title = "Adventurers Wanted: Zul'farrak", description = "The Warchief has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", objectives = "" }
WordHunterWoW_QuestEN[28038] = { title = "Blood in the Highlands", description = "You've got some fight in you, {class}. You might do well in the crucible.\n\nWhat!? You haven't heard of the Crucible of Carnage? That smarmy goblin Gurgthock and his troll sidekick have been plastering us with leaflets ever since he set up shop here in the Highlands. Champions from all over Azeroth fight to the death in there. You should gather up some friends and see how you fare.\n\nThe Crucible is just to the southwest. Look for Wodin the Troll-Servant somewhere in the middle of a ring of bones.", objectives = "" }
WordHunterWoW_QuestEN[28039] = { title = "Adventurers Wanted: Maraudon", description = "The Warchief has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", objectives = "" }
WordHunterWoW_QuestEN[28040] = { title = "Adventurers Wanted: Maraudon", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", objectives = "" }
WordHunterWoW_QuestEN[28041] = { title = "Bait and Throttle", description = "You can hold your own on the ground, {name}. I'll give you that.\n\nBut we Dragonmaw dominate the skies as well as land. Until you can prove to me you can handle a drake as well as a Dragonmaw, your Horde is nothing to me.\n\nLet's see if you can wrangle one back to Bloodgulch.\n\nFirst you'll need bait. Go out and kill one of the gryphons that wander the woods west or northeast of here. Make sure it's untamed! Drakes hate the stink of dwarf on their food.\n\nGet the gryphon carcass and you'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[28042] = { title = "Special Delivery for Brivelthwerp", description = "I recently came into possession of something that needs to be delivered to a gnome that goes by the name, Brivelthwerp. It's more like Briveltwerp if you ask me.\n\nI want you to take it to him in the southwest, down at the Sunken Dig Site. He's up to something and there's moolah involved... I can smell it!\n\nKeep an eye on what he's doing, {name}, and see if you can't get a cut of his profits. A big cut!", objectives = "" }
WordHunterWoW_QuestEN[28043] = { title = "How to Maim Your Dragon", description = "<You sling the gore-spattered gryphon corpse over your shoulder, its wings dragging to the ground.>\n\n<Highland Black Drakes roost just southwest of the Crucible of Carnage, along a ring of low mountain peaks.>\n\n<If you drop the gryphon corpse there, a drake is sure to start feeding. With its guard down, you should be able to attack it until it is weak enough to mount and fly.>", objectives = "" }
WordHunterWoW_QuestEN[28044] = { title = "Touch the Untouchable", description = "I've added a drop of my very own essence to the ooze. Look for a glowing sigil to the west, at the edge of Shadowlurk Ridge. Stand on it, concentrate, and pour this stuff all over yourself. It should be enough to shift you into the nether and let you see what's REALLY there.\n\nYou won't be alone... the satyr's treasure is being guarded by the biggest voidstalker they could summon. Defeat him, and the treasure is yours.\n\nAnd come back in one piece, or this crazy broad's gonna fry me!", objectives = "" }
WordHunterWoW_QuestEN[28045] = { title = "The Greatest Flavor in the World!", description = "Below us is a cave. It's huge! The perfect location for our new refrigerated vault. It's big enough to hold all of our inventory with room to grow.\n\nUnfortunately, when we were almost done equipping all of the pipes, bugs burrowed up out of nowhere and killed all of my employees!\n\nHow was I supposed to know?\n\nBut it gave me a great idea: silithid-flavored ice cream. We'll make a killing!\n\nAll I need now are the ingredients.", objectives = "" }
WordHunterWoW_QuestEN[28046] = { title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless infantry in the area.  Can you head over there and clear them out?", objectives = "" }
WordHunterWoW_QuestEN[28047] = { title = "Freezing the Pipes", description = "It's time to break out the I-Scream Cryocannon!\n\nWe lifted the tech from the frost cannons on the river boats. If it's one thing that we gnomes are good at, it's miniaturization by way of making everything else that much bigger!\n\nI need you to take the cannon down there into the cave and freeze the pipes we setup in the walls. That'll jumpstart them.", objectives = "" }
WordHunterWoW_QuestEN[28048] = { title = "That Smart One's Gotta Go", description = "There's some kind of smart brain bug in the back of the cave. It's in charge of all of the silithid down there.\n\nMy ice cream is melting! How am I supposed to launch my ice cream empire, and save my inventory, if that thing's in there?!", objectives = "" }
WordHunterWoW_QuestEN[28049] = { title = "See the Invisible", description = "Yeah, yeah, your stuck-up mage friend there hit it on the nose. The imps over at Shadowlurk Ridge are hiding the key to the satyr's barrier in the nether. It's right there, but you can't see it or touch it unless you're shifted.\n\nI guess you're out of luck though, because only imps can phase shift! So you should just close your eyes, turn around, and let me go...\n\nIt was just a joke! Don't hurt me! I'll need slime from the cursed oozes around these ruins. Bring me enough to cover you from head to toe!", objectives = "" }
WordHunterWoW_QuestEN[28050] = { title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", objectives = "" }
WordHunterWoW_QuestEN[28051] = { title = "We All Scream for Ice Cream... and then Die!", description = "Don't get me wrong... I'm cheerful on the outside, but inside I'm just terribly torn to pieces. All of my friends and employees are dead.\n\nCould you do me a favor? Would you swim down there and attach the tug's tow hook to my dead employees? I'll reel them in.", objectives = "" }
WordHunterWoW_QuestEN[28052] = { title = "Operation: Stir the Cauldron", description = "I'm putting you on a flying machine, {name}.\n\nYou'll be responsible for softening our landing into the slag pit.  Speak with your flight master here in Thorium Point, then fly down to the gorge.\n\nOnce you near your landing point, there will undoubtedly be hordes of Dark Iron dwarves waiting for you.  Use our flying machine's guns to take out as many of them as you can, then land at the cavern's entrance.  Rendan should be waiting for you by the time you arrive.", objectives = "" }
WordHunterWoW_QuestEN[28053] = { title = "Lunk Like Your Style", description = "", objectives = "" }
WordHunterWoW_QuestEN[28054] = { title = "Slavery is Bad", description = "Much like Overseer Maltorius, I'm a rich dwarf.  However, I earned my riches through hard work and wise decisions, not through slavery.\n\nOK fine, very little slavery.  Hardly any.\n\nAnyhow, the first thing that I see inside these caverns are slavedrivers and taskmasters.  I won't stand for this!  As you progress through the cavern, kill as many as you can.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", objectives = "" }
WordHunterWoW_QuestEN[28055] = { title = "Sweet, Horrible Freedom", description = "Of course, we'll want to free as many slaves as we can while we're here.  Most of them will likely join forces with us, anxious to fight against their captors.\n\nHowever, sometimes you will find that slaves are resistant to being freed.  It's a strange phenomenon, often called \"Durnholde Syndrome\".\n\nEither way, you should try to free them.  If they resist, treat them as enemies.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", objectives = "" }
WordHunterWoW_QuestEN[28056] = { title = "Rise, Obsidion", description = "Overseer Maltorius is in charge here, but he's not the only dwarf of power within the Slag Pit.  Lathoric the Black and his horrifying golem, Obsidion, loom just down this corridor.\n\nInterfering with Lathoric's altar should summon both of them.  Find it, then summon Lathoric and kill him.  Report to Evonice Sootsmoker when you're finished.", objectives = "" }
WordHunterWoW_QuestEN[28057] = { title = "Kill 'em With Sleep Deprivation", description = "It's a little known fact that dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!\n\nNow I ask you; How can they sleep without pillows?  Exactly, {name}, they can't.  This is why you must steal their pillows.\n\nOnce you've finished your cushion-thievery, talk with Taskmaster Scrange.  He's a bit deeper in the cave, working on a covert project with Hansel.", objectives = "" }
WordHunterWoW_QuestEN[28058] = { title = "Look at the Size of It!", description = "Well, well, well... Isn't this a surprise. The Pillamaster had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.", objectives = "" }
WordHunterWoW_QuestEN[28059] = { title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", objectives = "" }
WordHunterWoW_QuestEN[28060] = { title = "Twisted Twilight Ties", description = "Hansel and I came here on a secret mission: kill Overseer Maltorius.  While our main goal still remains the same - defeating Archduke Calcinder - it can't hurt to take out the infamous overseer of the Slag Pit while we're here.\n\nProblem is, Hansel was only prepared to fight one dwarf, but it looks like Maltorius has a visitor... an emissary from the Twilight's Hammer!\n\nSpeak with Hansel and help him out.  Then proceed down this corridor and along the balcony outside to find Overseer Oilfist.", objectives = "" }
WordHunterWoW_QuestEN[28061] = { title = "Minions of Calcinder", description = "There is such a thing as digging too deep, {name}.  While you'll find the richest mineral veins deep below the surface, you'll also find the most evil creatures.\n\nLike fire elementals.\n\nCalcinder's minions roam the cavern ahead.  Every one of them holds a piece of Calcinder's evil within it.  Slay as many as you can, and show no remorse.", objectives = "" }
WordHunterWoW_QuestEN[28062] = { title = "From Whence He Came", description = "Archduke Calcinder squirms in the back of this very cavern.  We are close to killing him... but that is not what we are going to do.\n\nSlaying Calcinder here means nothing.  His acolytes can easily revive him.  Instead, we are going to banish him.\n\nI asked you to gather a precious stone from the Twilight's Hammer earlier.  You will now use it against Calcinder.  Engage him, weaken him, then use this device on him.  He will be banished from this realm.\n\nGood luck, brave {name}.", objectives = "" }
WordHunterWoW_QuestEN[28063] = { title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another horde attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", objectives = "" }
WordHunterWoW_QuestEN[28064] = { title = "Welcome to the Brotherhood", description = "You should return to Thorium Point.  Overseer Oilfist and the rest of the Thorium Brotherhood will be wondering how you fared in the fight against Calcinder.", objectives = "" }
WordHunterWoW_QuestEN[28065] = { title = "Walk A Mile In Their Shoes", description = "We have sent at least 3 different recon groups to investigate Farson Hold in the last few weeks.  Sadly, not one of them has returned back with any info.\n\nAt this point, all we can hope is that they are being held alive as prisoners.  I need you to infiltrate the keep and help get our soldiers back.  This won't be easy {name}, but if anyone can help us, it's you.", objectives = "" }
WordHunterWoW_QuestEN[28066] = { title = "Adventurers Wanted: The Sunken Temple", description = "The Warchief has requested that any able-bodied adventurer head to the Sunken Temple, not far from Stonard, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", objectives = "" }
WordHunterWoW_QuestEN[28067] = { title = "Adventurers Wanted: The Sunken Temple", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Sunken Temple, not far from Marshtide Watch, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", objectives = "" }
WordHunterWoW_QuestEN[28068] = { title = "Adventurers Wanted: Blackrock Depths", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackrock Depths, northwest of Morgan's Vigil, immediately!\n\nThe Dark Iron dwarves pose a serious threat to the citizens of Redridge! If you so choose, head to Blackrock Depths and speak with Morgan, who has returned from her extended absence and wishes to enact her vengeance on the Dark Iron nation.", objectives = "" }
WordHunterWoW_QuestEN[28069] = { title = "Adventurers Wanted: Blackrock Depths", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Depths, west of Flame Crest, immediately!\n\nThe Dark Iron dwarves have already attacked Alliance-held Redridge, and if left unchecked, may soon threaten our few Horde footholds in southern Azeroth.\n\nIf you so choose, head to Blackrock Depths and speak with High Executioner Nuzrak, who is reforming the Kargath Expeditionary Force to finish off the Dark Irons once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28070] = { title = "Adventurers Wanted: Blackrock Spire", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Spire, west of Flame Crest, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the very existence of the Horde! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", objectives = "" }
WordHunterWoW_QuestEN[28071] = { title = "Adventurers Wanted: Blackrock Spire", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Blackrock Spire, northwest of Morgan's Vigil, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the entirety of His Majesty's kingdom! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", objectives = "" }
WordHunterWoW_QuestEN[28072] = { title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, east of Feathermoon Stronghold, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", objectives = "" }
WordHunterWoW_QuestEN[28073] = { title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, west of Camp Mojache, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", objectives = "" }
WordHunterWoW_QuestEN[28074] = { title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, west of Camp Mojache, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", objectives = "" }
WordHunterWoW_QuestEN[28075] = { title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, east of Feathermoon Stronghold, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", objectives = "" }
WordHunterWoW_QuestEN[28076] = { title = "Adventurers Wanted: Northern Dire Maul", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Northern Dire Maul, east of Feathermoon Stronghold, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Druid of the Talon already sent there as a forward scout.", objectives = "" }
WordHunterWoW_QuestEN[28077] = { title = "Adventurers Wanted: Northern Dire Maul", description = "The Warchief has requested that any able-bodied adventurer head to Northern Dire Maul, west of Camp Mojache, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Stonemaul Ogre already sent there as a forward scout.", objectives = "" }
WordHunterWoW_QuestEN[28078] = { title = "Adventurers Wanted: Stratholme Main Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", objectives = "" }
WordHunterWoW_QuestEN[28079] = { title = "Adventurers Wanted: Stratholme Main Gate", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", objectives = "" }
WordHunterWoW_QuestEN[28080] = { title = "Adventurers Wanted: Stratholme Service Gate", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", objectives = "" }
WordHunterWoW_QuestEN[28081] = { title = "Adventurers Wanted: Stratholme Service Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", objectives = "" }
WordHunterWoW_QuestEN[28082] = { title = "Adventurers Wanted: Scholomance", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRecent necromantic activity in the area points to Darkmaster Gandling, and a renewed effort to train powerful sorcerers for the scourge. If you so choose, travel to Scholomance to cleanse this bastion of evil from the Plaguelands.", objectives = "" }
WordHunterWoW_QuestEN[28083] = { title = "Adventurers Wanted: Scholomance", description = "The Warchief has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRecent necromantic activity in the area points to Darkmaster Gandling, and a renewed effort to train powerful sorcerors for the scourge. If you so choose, travel to Scholomance to cleanse this bastion of evil from the Plaguelands.", objectives = "" }
WordHunterWoW_QuestEN[28084] = { title = "Might of the Krom'gar", description = "", objectives = "" }
WordHunterWoW_QuestEN[28085] = { title = "Trouble at Highperch", description = "Thank you for your help, {name}. You should speak with Pao'ka Swiftmountain at Highperch to the southwest.\n\nPerhaps he will know the whereabouts of the Elder Crone?", objectives = "" }
WordHunterWoW_QuestEN[28086] = { title = "Free the Pridelings", description = "The trappers are rounding up all of the young wind riders. {name}, will you go out there and free the pridelings?", objectives = "" }
WordHunterWoW_QuestEN[28087] = { title = "Death to all Trappers!", description = "There's only one answer for those filthy Twilight's Hammer trappers! Death!\n\nBring me their nets, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28088] = { title = "Release Heartrazor", description = "The Twilight's Hammer have the alpha male of Highperch pinned down. You must head east up the ramp and release Heartrazor before the pride loses its patriarch!", objectives = "" }
WordHunterWoW_QuestEN[28089] = { title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, brother! Destiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28090] = { title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed some kind of stone that they carry in chests in their caravans that they use to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", objectives = "" }
WordHunterWoW_QuestEN[28091] = { title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nYou can see them just to our west, in the canyon below. Get in there and clear them out so we can get this attack on the move.", objectives = "" }
WordHunterWoW_QuestEN[28092] = { title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending the Gob Squad with you. Get to the gate to the southeast and get it open. Patch should have any further instructions you'll need from there.", objectives = "" }
WordHunterWoW_QuestEN[28093] = { title = "Pressing Forward", description = "Good work so far. We should find the entrance to Grim Batol just past the next gate.\n\nI was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon. I'm thinking if we get there soon enough, maybe I can let Ticker have a little more fun.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", objectives = "" }
WordHunterWoW_QuestEN[28094] = { title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", objectives = "" }
WordHunterWoW_QuestEN[28096] = { title = "Welcome to the Machine", description = "Come in here dear boy, have a cigar. You're gonna go far and fly high as a ranking officer of the Forsaken. Yes, indeed, this is the good life and you are going to live it!\n\nI want you to take these orders and dispense them to the lowly scrubs that come along looking for work. Who you give what to is wholly at your discretion.\n\nWhen you're ready, mount up on my trusty skeletal steed - so they don't miss you - and start living the life! Which means just stand there and wait.", objectives = "" }
WordHunterWoW_QuestEN[28097] = { title = "The Gates of Grim Batol", description = "Kroggs started the assault to push up the canyon. He's just past the gate to our southeast.\n\nI'm going to get the squad together to join the attack. We'll meet you down there.", objectives = "" }
WordHunterWoW_QuestEN[28098] = { title = "The Twilight Skymaster", description = "Twilight Skymaster Richtofen is at the Twilight Aerie up above and to the southeast. No matter what we do down here, if he's not dealt with, all hope is lost for Highperch.\n\nWhile Heartrazor is too injured to help you with the fight, he can fly you up there. The rest is up to you, {name}.\n\nGood luck. ", objectives = "" }
WordHunterWoW_QuestEN[28099] = { title = "Rasha'krak", description = "Based on this information you've delivered, I believe that one of this \"Archduke's\" minions may already have turned its eyes toward Thorium Point.\n\nHis name is Rasha'krak, and he patrols the lava pools just to our south.  He looks like the latent fire elementals that rage nearby, except for one small difference: the bracers of binding that encircle his wrists.\n\nFind him and bring these bracers to me, {name}.  I need proof that we are in danger before we involve ourselves in elemental wars.", objectives = "" }
WordHunterWoW_QuestEN[28100] = { title = "A Talking Totem", description = "The furbolg village to the south is the home of the Deadwood tribe, sworn enemies of the Timbermaw. They are corrupted and foul like so many others, driven mad by the taint of these woods.\n\nSomething unusual has occured near the village though. Travelers coming here have said that the totem next to the road has spoken to them.\n\nI have heard nothing every time I approach it. Perhaps it will speak to you, {name}? Maybe you can find out what's going on for me.", objectives = "" }
WordHunterWoW_QuestEN[28101] = { title = "Mathias' Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks on Grim Batol isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Mathias Shaw in Dragonmaw Pass, in the canyon below us to the south.", objectives = "" }
WordHunterWoW_QuestEN[28102] = { title = "Fight the Power", description = "It's time for the final push against the Jadefire!\n\nIf you're prepared to break through their foul barrier and bring the fight to their leader, I'd also ask your help against the lesser satyr. Our druids fight ferociously, but your strength can help turn the battle.\n\nShow the Jadefire that their power will no longer hold sway over these lands!", objectives = "" }
WordHunterWoW_QuestEN[28103] = { title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nGet in there and clear them out so we can push forward into the canyons.", objectives = "" }
WordHunterWoW_QuestEN[28104] = { title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed a stone that they carried in chests in their caravans that they used to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", objectives = "" }
WordHunterWoW_QuestEN[28105] = { title = "Kavem the Callous", description = "Kavem was cruel enough before the Neferset signed up with Deathwing.  His pleasure in deriving pain now borders on the insane.\n\nIt is he who now holds the keys to our shackles.\n\nHe dwells in the building next to us, to my right.\n\nFind him and take the key from him.  Do not hesitate or show him mercy.  He will slit your throat and think nothing of it.", objectives = "" }
WordHunterWoW_QuestEN[28107] = { title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", objectives = "" }
WordHunterWoW_QuestEN[28108] = { title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending a squad from Highbank with you. Get to the gate to the southeast and get it open. Your lieutenant should have any further instructions you'll need from there.", objectives = "" }
WordHunterWoW_QuestEN[28109] = { title = "Pressing Forward", description = "Good work so far.\n\nWe should find the entrance to Grim Batol just past the next gate. I was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", objectives = "" }
WordHunterWoW_QuestEN[28111] = { title = "Trouble at Azurelode", description = "Productivity from our spider farm at the Azurelode Mine is at a standstill. Captain Keyton has requested that we send help immediately. Keyton claims that the mine spiders refuse command and are running rampant. Furthermore, a group of coastal murlocs are raiding our supplies. I want you to go down there and check things out. Help out Keyton and the spider-handler, {name}.\n\nYou'll find Azurelode Mine to the southeast, near the coast.", objectives = "" }
WordHunterWoW_QuestEN[28112] = { title = "Escape From the Lost City", description = "Everything is ready!  Undo my chains and set your friends free.\n\nWe must move quickly before the Neferset scum realize we're up to something!\n\nIf we make it, see my brother, King Phaoris for a reward.", objectives = "" }
WordHunterWoW_QuestEN[28113] = { title = "Break the Unbreakable", description = "With the claw, we are ready to break through the Jadefire's defenses.\n\nHead into the ruins to the northwest. Beyond the frontline of the satyr you'll find a narrow pass heading to their corrupted moonwell. An enormous wall of demonic flame bars the path, but the Claw of Tichondrius should be able to dispel it.\n\nBeyond the barrier you will find the leader of these forces, Xavathras, guarding the corrupted moonwell. Slay him once you are through!", objectives = "" }
WordHunterWoW_QuestEN[28114] = { title = "Glorious Harvest", description = "Directly southeast of Southpoint Gate you will find our spider domestication operations. Through the years we have grown a kinship with the spiders of Hillsbrad and have managed to domesticate and breed the adorable little critters. Spiders now serve us as regular household pets and beasts of battle! Such diverse creatures they are!\n\nI need you to head into the fields to the southeast and carefully harvest the eggs that we have incubating on the bears. Deliver the harvest to Sarus at the mine.", objectives = "" }
WordHunterWoW_QuestEN[28115] = { title = "Past Their Prime", description = "Bears are soulless beasts put upon this earth to torment us. Only through Forsaken ingenuity have we devised a way to make use of the bears so that they may serve some purpose! We use the bears at our spider farm as living egg feeders. Our spiders lay their eggs in the bear flesh and the eggs thrive off of the meat and blood of the beasts.\n\nAfter they have served their purpose the monsters must be put down. Travel southeast and kill the infested bears that have lived past their prime.", objectives = "" }
WordHunterWoW_QuestEN[28116] = { title = "Crying Violet", description = "We must prepare carefully before assaulting Jaedenar. The magic of the warlocks and demons within Jaedenar is strong, and we will need wards of our own before entering.\n\nWe need only one more ingredient: Crying Violet, which grows in the hills near the enemy's stronghold to the northwest. \n\nGather the crying violet, then meet my assistant in the field. He will know what to do next.", objectives = "" }
WordHunterWoW_QuestEN[28117] = { title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed Tol Barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28118] = { title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", objectives = "" }
WordHunterWoW_QuestEN[28119] = { title = "Purity From Corruption", description = "The flowers you brought me were the essential ingredient.\n\nProtective barriers surround Shadow Hold, projected from demonic braziers. If we are to drive the Shadow Council from Felwood, then those braziers must be extinguished.\n\nThis vial has been infused with crying violet and the magic of the wilds. Fill it at the corrupted moonwell in the center of Jaedenar and return to me.", objectives = "" }
WordHunterWoW_QuestEN[28120] = { title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to the Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", objectives = "" }
WordHunterWoW_QuestEN[28121] = { title = "Forces of Jaedenar", description = "The Shadow Council perpetuates the corruption of this land. At Jaedenar in the northwest, they worship the demons of the Burning Legion, and work to open the path for their masters to return to this world.\n\nThe grounds are patrolled by Jaedenar Hounds, Guardians, Adepts, and Cultists - thugs that act as lookout for the more vile forces beneath. They will be the first to die so that these forests may no longer suffer!", objectives = "" }
WordHunterWoW_QuestEN[28122] = { title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", objectives = "" }
WordHunterWoW_QuestEN[28123] = { title = "The Demon Chain", description = "Narkrall revealed to me the secret of his influence over the drakes in this area. I thought the Demon Chain was a myth, but he's had it all along.\n\nAnd now the fool is about to lose it!\n\nHis life is meaningless to me but the Dragonmaw can't afford to lose that artifact. Follow him north, up to Thundermar. The city will be in chaos, so you may be able to land undetected. Return to me with the Demon Chain, even if you have to remove it from Narkrall's corpse.\n\nFind that artifact, {name}!", objectives = "" }
WordHunterWoW_QuestEN[28124] = { title = "On to the Bulwark", description = "{name}, while you and the pridelings were taking care of the skymaster, Lakota Windsong came by. She told me to tell you to meet her east at the Twilight Bulwark.\n\nThat must be where they're holding Magatha Grimtotem.", objectives = "" }
WordHunterWoW_QuestEN[28125] = { title = "Something to Wear", description = "I've got an idea for how you can get close to their leaders without getting killed. But first, you're going to need to find something to wear.\n\nMy suggestion is that you head up there and get their armor from them.", objectives = "" }
WordHunterWoW_QuestEN[28126] = { title = "Dousing the Flames of Protection", description = "The braziers are spread throughout Shadow Hold.\n\nEnter the tunnel into Shadow Hold, and follow it through the underground passageways. Douse each of the brazier's flames and the protections the Council has set up will fall for at least a short period of time.", objectives = "" }
WordHunterWoW_QuestEN[28127] = { title = "Break Them Out", description = "Magatha's not the only one that the Twilight's Hammer have taken prisoner.\n\nWhile you're up there to the south, you should break as many of them out as you can.", objectives = "" }
WordHunterWoW_QuestEN[28128] = { title = "The Inner Circle", description = "With their outer sentries gone, the greater members of the Shadow Council are next.\n\nDeep within the corrupted barrow dens you'll find powerful Jaedenar Warlocks, Hunters, Enforcers, Darkweavers, and Legionnaires.\n\nThey must be defeated if these lands are to be saved!", objectives = "" }
WordHunterWoW_QuestEN[28129] = { title = "The Demon Prince", description = "The Jadefire satyr that have overrun so much of Felwood work directly with the Shadow Council.\n\nThese satyr answer directly to the ancient and powerful Prince Xavalis. Some say he is the son of Xavius, the first satyr, blessed by Sargeras himself.\n\nWhatever his nature, he must die if we are to scatter the Jadefire and reclaim our barrow dens. Journey deep into Shadow Hold and slay him. Show him no mercy; he will have none for you.", objectives = "" }
WordHunterWoW_QuestEN[28130] = { title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28131] = { title = "Twin Temptresses", description = "Moora and Salia are the personal servants of Shadow Lord Fel'dan. Do not be deceived by them!\n\nThese foul succubi use their wiles and foul magic to draw mortals deep into Shadow Hold. Those in their grasp undergo brainwashing, or are sacrificed by Fel'dan to his demonic masters.\n\nThe two fight as one and are never found apart, making them a considerable threat. Proceed further into Shadow Hold and slay them.", objectives = "" }
WordHunterWoW_QuestEN[28132] = { title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", objectives = "" }
WordHunterWoW_QuestEN[28133] = { title = "Fury Unbound", description = "Narkrall's drake Torth survived the failed attack on Thundermar, and now the creature is free from his former master.\n\nTorth seeks vengeance against the Dragonmaw, and has already strafed Bloodgulch once. He will keep returning until we skewer him for good. It is time to put the Demon Chain to work.\n\nTorth's old nest is a small cave in the hills west of here that we have turned into a small camp called \"The Gullet.\"\n\nMeet me at the Gullet and we will finish Torth off.", objectives = "" }
WordHunterWoW_QuestEN[28134] = { title = "Impending Retribution", description = "Now that you've been suitably rewarded, I hope I can speak with you frankly.\n\nYou've done my kingdom a great favor, but you've also unbalanced a fragile peace process.\n\nI was pursuing my brother's release strictly through diplomatic means in order to avoid bloodshed.\n\nNow, the enemy is sure to seek retaliation.\n\nSpeak to Nomarch Teneth at the Tahret Grounds to the east, Sun Priest Asaris at the Seal of the Sun King to the north and Asaq at Mar'at to the west.  Find out where the enemy will strike.", objectives = "" }
WordHunterWoW_QuestEN[28135] = { title = "Al'Akir's Vengeance", description = "Listen, {name}.  What struck Orsis was no natural sandstorm.  It was the minions of Al'Akir.\n\nThe elemental lord of air is firmly allied with Deathwing and it was only a matter of time before he set his subjects upon my people.\n\nOrsis has been attacked as a warning to us.  We must move quickly to offer our brethren what aid we can.\n\nMeet with Nadun at the Arsad Trade Post outside of Mar'at.  I will begin preparations to take care of the displaced and wounded.", objectives = "" }
WordHunterWoW_QuestEN[28136] = { title = "Behind You!", description = "The three leaders of the Bulwark are powerful and not to be underestimated, {name}. Fortunately for us, you now have a disguise to make you look like one of the Twilight cultists.\n\nYou should put the disguise on and speak with Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion each alone. Get them to turn their backs on you, and when they do, strike quickly!", objectives = "" }
WordHunterWoW_QuestEN[28137] = { title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", objectives = "" }
WordHunterWoW_QuestEN[28138] = { title = "Human Infestation", description = "This mine was once the heart of Alliance mining operations in Hillsbrad. It now serves as a breeding ground for our loyal spiders, though, the humans still occupy it - in a way.\n\n<Keyton grins.>\n\nBut onto business! Warden Stillwater has called for more workers at the Sludge Fields. I want you to enter the mine with these shackles and capture Hillsbrad humans for labor in the fields.\n\nBreak them out of their web paralysis and beat them into submission before you use the shackles.", objectives = "" }
WordHunterWoW_QuestEN[28139] = { title = "Codemaster's Code", description = "{name}, the bonds holding Magatha are specially encoded. She can only be released if we get those codes.\n\nThere's a device near Codemaster Deethuk in the Bulwark to the southeast. It contains the codes.\n\nPlease obtain them.", objectives = "" }
WordHunterWoW_QuestEN[28140] = { title = "The Elder Crone", description = "You have the code. Now all you have to do is head to the eastern section of the Bulwark and free the Elder Crone.\n\nGood luck, {name}. Thank you for all you've done.", objectives = "" }
WordHunterWoW_QuestEN[28141] = { title = "Relics of the Sun King", description = "The Seal of the Sun King serves as a defense mechanism for Ramkahen.\n\nWhen the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders.\n\nThey attacked this holy site on their way west and robbed it of the relics which once provided its power.\n\nRecover the relics for us.  Without them we are powerless to defend against attacks from the desert.", objectives = "" }
WordHunterWoW_QuestEN[28142] = { title = "To the Withering", description = "According to Magatha, she'll meet you just outside of the Twilight Withering to the east.", objectives = "" }
WordHunterWoW_QuestEN[28143] = { title = "To the Withering", description = "You should not keep the Elder Crone waiting, {name}.\n\nShe said that she'd be up top and just outside of the Twilight Withering to the east.", objectives = "" }
WordHunterWoW_QuestEN[28144] = { title = "Thieving Little Monsters!", description = "The long stretch of coastline directly south of our position that extends from west to east is known as the Western Strand. Along the Western Strand you will find two things: murlocs and our stolen \"supplies.\"\n\n<Keyton puts his hands in the air and makes quotation marks with his fingers.>\n\nThose damned thieving murlocs struck while our backs were turned and took our \"supplies.\"\n\nSarus and I cannot leave this post. We need you to head to the Western Strand and recover those \"supplies!\"", objectives = "" }
WordHunterWoW_QuestEN[28145] = { title = "Venomblood Antidote", description = "Iset attempted to defend this holy ground when the Wastewander bandits ransacked it.\n\nThey appear to have used the potent toxin present in the venomblood scorpids.\n\nTake this vial and collect venom from their corpses so that I may concoct an antidote.  I fear Iset might not have much time.", objectives = "" }
WordHunterWoW_QuestEN[28146] = { title = "Coastal Delicacies!", description = "My spiders are hungry and agitated! They haven't eaten for days and are starting to sample our human captives. We can't have that. We need those humans for use in the Sludge Fields.\n\nI want you to take one of my hungry mine spiders out and feed it murlocs from the Western Strand, south of here. Whatever you kill, it'll eat! The more the better!", objectives = "" }
WordHunterWoW_QuestEN[28147] = { title = "Purple is Your Color", description = "So far as I can tell, the Glopgut Ogres right outside the cave here have not yet joined up with the Twilight's Hammer. If we're clever, we can turn the two groups against each other.\n\nLet's roll with a little trick I learned in Silithus. First we'll need to put together a set of cultist robes for you.\n\nHead south of here and kill some Twilight Windwarpers in the Twilight Breach. Aside from disrupting whatever they're up to, it'll give you a chance to collect garment scraps.", objectives = "" }
WordHunterWoW_QuestEN[28148] = { title = "Culling the Corrupted", description = "The sickening corruption of demons pervades this entire forest. The soil, the trees, the animals... all grow thick with fel magics.\n\nWe of the Emerald Circle have sworn to cleanse this forest, and doing so requires a constant battle. While some life here can still be healed, the bears and wolves that wander nearby have been twisted too far.\n\nWe must end their suffering, and ensure their bodies do not spread the taint further. Hunt the bears and wolves, and return to me with their hides.", objectives = "" }
WordHunterWoW_QuestEN[28149] = { title = "Whispers in the Wind", description = "You hear dem, {class}? De voices from de cave. Dey want to talk, but dey ain't got no breath.\n\nLet's find a way to listen. De Twilight's Hammer, dey talk to de wind. Go to de Twilight Breach south of here, and grab de Windspeaker Charm from de camp. It'll be atop a stone pillar.\n\nWe'll need us de breath of the elementals, too! Slay de Storm Vortexes and take what joo need.", objectives = "" }
WordHunterWoW_QuestEN[28150] = { title = "An Arcane Ally", description = "The Emerald Circle is sworn to accept the help of any who wish to fight the demons of Felwood. Though my people have long shunned the arcane, we cannot afford to deny ourselves such advantage here.\n\nArcanist Delaris, a surviving Highborne mage, helps us battle the Jadefire satyr. Follow the road to the north, and you will find her at our encampment overlooking the Ruins of Constellas.\n\nIf you wish to help cleanse Felwood, follow her requests as you have mine.", objectives = "" }
WordHunterWoW_QuestEN[28151] = { title = "Dressed to Kill", description = "Your disguise is ready, {name}. Whenever you go north into Glopgut's Hollow now, your Twilight's Hammer regalia will fool the ogres.\n\nThe rest of the plan is simple: you kill a bunch of Glopgut ogres, and they blame the cult. Are you ready to create some havoc in the ogre camp? I thought so.", objectives = "" }
WordHunterWoW_QuestEN[28152] = { title = "Jaedenar Awaits", description = "The cultists you saw guarding the claw were members of the Shadow Council, foul warlocks behind nearly every attempt to bring demons into Azeroth.\n\nNorth of here is Jaedenar, named in worship of Kil'Jaeden himself. Deep beneath it stretches Shadow Hold, a former barrow den and the Shadow Council's own stronghold on Azeroth.\n\nTake these herbs north to Wildheart Point, on the east side of the road. Greta Mosshoof will need them for her plan to purify Shadow Hold for good.", objectives = "" }
WordHunterWoW_QuestEN[28153] = { title = "Shadow Lord Fel'dan", description = "Shadow Lord Fel'dan awaits further in the depths, {name}.\n\nHis wrath will be unmatched now that you have slain his beloved pets. Even without Moora and Salia at his side, he is a terrible force to be reckoned with.\n\nBeware his dark powers; he is nearly more demon than orc by now.", objectives = "" }
WordHunterWoW_QuestEN[28154] = { title = "Muckgill's Flipper or Something...", description = "This looks like Muckgill's flipper or something. Maybe there's somebody that cares that you killed this murloc back at the Azurelode Mine camp. Probably not, but it's worth a shot.\n\nTake Muckgill's fin or whatever it might be back to Captain Keyton at the Azurelode Mine in southwestern Hillsbrad.", objectives = "" }
WordHunterWoW_QuestEN[28155] = { title = "Lord Banehollow", description = "Only one final power remains lurking in the depths of Shadow Hold now: Lord Banehollow.\n\nThe Shadow Council here serves his whims, and even Fel'dan was a mere instrument for him to prepare this land for another invasion of the Burning Legion.\n\nProceed carefully, {name}. A dreadlord is a terrifying foe. Stand tall and triumph!", objectives = "" }
WordHunterWoW_QuestEN[28156] = { title = "Deep Mine Rescue", description = "<You can hear Dumass speaking through the webbing.>\n\nHI! SPIDERS EVERYWHERE! THE CAPTAIN SENT ME TO SAVE THE WORLD AND CAPTURE HUMANS! WHAT IS THIS PLACE ANYWAY? IT'S SO HOT! I...\n\n<Dumass goes on and on about his situation.>\n\nPerhaps you should cut him free and get him back to safety. Or you can just leave him here, though it's your fault that he's stuck in this mine.", objectives = "" }
WordHunterWoW_QuestEN[28157] = { title = "Four Twilight Elements", description = "The Twilight's Hammer have summoned a monstrosity. It's a combination of the four elements infused with the power of their special ore, Elementium.\n\nIf you want to save your precious Thousand Needles from total destruction, you're going to have to destroy it. But first, you'll need a few things to get through its protective shielding.\n\nGo east into the Withering and bring back the four Twilight elements.", objectives = "" }
WordHunterWoW_QuestEN[28158] = { title = "Unbound", description = "There are two very powerful elementals that the Twilight's Hammer have bound. They are using the bound Fury and Vortex to infuse Animus with a great deal of power.\n\nWhen Animus has absorbed enough of their power, he will explode. The rest of Thousand Needles and much of the surrounding lands, will be obliterated.", objectives = "" }
WordHunterWoW_QuestEN[28159] = { title = "The Doomstone", description = "At the core of Animus is an artifact known as the Doomstone. One of its properties is an ability to absorb a great deal of energy.\n\nThis is how the cultists are trying to set off the explosion... by overloading the stone and amplifying the power through the elemental.\n\nBring me the Doomstone. For safe keeping, of course.", objectives = "" }
WordHunterWoW_QuestEN[28160] = { title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if we ever cross paths again, you will die.", objectives = "" }
WordHunterWoW_QuestEN[28161] = { title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if ever we cross paths again, you will die.", objectives = "" }
WordHunterWoW_QuestEN[28162] = { title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[28163] = { title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the horde scum but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any horde that you find.\n\nYou know what they say, the only good horde is a dead horde!", objectives = "" }
WordHunterWoW_QuestEN[28164] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28165] = { title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Horde we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28166] = { title = "Thog's Nightlight", description = "To see de spirits, we need a special light. A light that lights up one's insides. De light of souls.\n\nTwilight's Hammer uses dem to root out traitors after what we did to dem in Hyjal. Dey just gave one to de Glopgut ogres as a gift.\n\nInside de Glopgut Hollow to de north, you'll find de great big brute Thog. He's got him a Light of Souls. At least, he will until you take it from him.", objectives = "" }
WordHunterWoW_QuestEN[28167] = { title = "Report to Carvo Blastbolt", description = "I'm going to start preparing my men to leave this place. We can't hold out here any longer. I want you to move to a forward position in the middle of the large room ahead.\n\nYou should find Carvo Blastbolt there. He'll give you further instructions. Good luck, {name}, and I'll see you on the surface.", objectives = "" }
WordHunterWoW_QuestEN[28168] = { title = "Trouble at the Sludge Fields", description = "Warden Stillwater, over at the Sludge Fields, north of here, has sent out a distress signal. The missive wasn't clear, but from what I could make of the letter there's a riot happening at the Sludge Fields and most of the guards have been killed. The warden has warned that any would-be-heroes approach from the back entry, located on the western side of the Sludge Fields.\n\nHe's also asked for discretion. He doesn't want news of this little *ahem* uprising to surface.", objectives = "" }
WordHunterWoW_QuestEN[28169] = { title = "Withdraw to the Loading Room!", description = "Excellent job gathering the other survivors! They - and you - are the reason S.A.F.E. teams keep coming down here. Nevin won't rest until we've found and rescued every possible survivor.\n\nI'm sending my men to the Loading Room to prepare for decontamination. Please follow them and meet up with Gaffer Coilspring when you arrive. She'll set you up for decontamination and have you on your way to the surface.", objectives = "" }
WordHunterWoW_QuestEN[28170] = { title = "Night Terrors", description = "Me friend Uchek is in de cave already. We set up three shrines inside. All you gotta do is flush out de bad juju from each one, mon.\n\nGo inside de cave here and talk to Uchek. He put you in a trance, put you in de spirit realm. Tread carefully! If you see a ghostly beast, you don't be panicking. Shine de Light of Souls on de beast for a moment or two, and de light will send 'em away for good. De light will keep you safe. Now go cleanse de three shrines!", objectives = "" }
WordHunterWoW_QuestEN[28171] = { title = "And the Sky Streaked Red", description = "With Deathwing otherwise occupied, we have a grim and daunting task ahead of us, under charge of the queen herself. The black dragonflight is to be wiped out.\n\nI would welcome your aid in this, if it is offered. As soon as you are ready, I will send you with the next flight joining the attack.", objectives = "" }
WordHunterWoW_QuestEN[28172] = { title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", objectives = "" }
WordHunterWoW_QuestEN[28173] = { title = "Blackout", description = "The Twilight Drakehunters used vicious implements to drag our circling drakes from the sky. Hooks that buried into their scales and held the Twilight secure while they brought our kin to the ground.\n\nWe are past the point of peace. Past hope for their redemption. The only mercy we have left to offer the black flight is the oblivion that they so passionately pursue.\n\nUse these hooks to slay the Obsidian Pyrewings to the south. They should allow you much maneuverability in the air if used right.", objectives = "" }
WordHunterWoW_QuestEN[28174] = { title = "Burning Vengeance", description = "The Blackrock orcs are ceaseless.  They swarm atop the battle-plains to the east, poised to strike at any moment.\n\nThey already attacked my homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you hold any love for mankind, you'll do the same.  So prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", objectives = "" }
WordHunterWoW_QuestEN[28175] = { title = "Shining Through the Dark", description = "The great petrified tree that lies before us to the south was once a beacon of great life. Our beacon. We lost this forest to the black flight, and it has since been corrupted and petrified. Nearly unredeemable.\n\nBut all is not without hope. I've brought a powerful tool to begin the healing process. The tree may still be saved, with much time and fortune, and with perhaps a little effort from you.\n\nBring this, Alexstrasza's Tear, and use it within the hollowed heart of the tree.", objectives = "" }
WordHunterWoW_QuestEN[28176] = { title = "Following the Young Home", description = "In the southwestern portion of the Obsidian Forest, you will find some of the black egg clutches. Many of the eggs can be hatched at any time with a bit of prodding from the right flame, and as the whelplings hatch, they will cry out and flock for their mother.\n\nDo not worry, if this purging is to be taken to the whelps, that is not a task that I will force on you. I simply want you to let them out and follow them home as they seek their mother. It is she who we must confront.", objectives = "" }
WordHunterWoW_QuestEN[28177] = { title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My colonel has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", objectives = "" }
WordHunterWoW_QuestEN[28178] = { title = "A Future Project", description = "We'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.\n", objectives = "" }
WordHunterWoW_QuestEN[28179] = { title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28180] = { title = "The Sand, the Cider, and the Orb", description = "Colonel Troteman is waiting for us to the east.  Before we head out though, we need to gather some more stuff.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", objectives = "" }
WordHunterWoW_QuestEN[28181] = { title = "Warlocks Have the Neatest Stuff", description = "Keeshan said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", objectives = "" }
WordHunterWoW_QuestEN[28182] = { title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", objectives = "" }
WordHunterWoW_QuestEN[28183] = { title = "Return to Keeshan", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", objectives = "" }
WordHunterWoW_QuestEN[28184] = { title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with Troteman.\n\nYou familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few orcs while we travel?  I'm getting a little restless here in this camp.", objectives = "" }
WordHunterWoW_QuestEN[28185] = { title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", objectives = "" }
WordHunterWoW_QuestEN[28186] = { title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", objectives = "" }
WordHunterWoW_QuestEN[28187] = { title = "Missed Me By Zhat Much!", description = "Okay, {race}! Zhis just got real!\n\nSomevone zhinks zhat zhey can get rid of me zhat easily, hmm?\n\nVe shall see about zhat! Nozhink can shtop zhis vork! Nozhink!\n\n<Schnottz looks around at the encroaching flames.>\n\nVe should probably get out of here.\n\nHuury up! Time is vastink!\n", objectives = "" }
WordHunterWoW_QuestEN[28188] = { title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28189] = { title = "Do the Right Thing", description = "You have come upon a horrific scene. Someone or something has buried all of the humans up to their necks in a manner consistent with planting. The ghouls, which are seemingly tending the field of human seedlings, periodically jump to the nearest human and devour its head!\n\nYou can end this right here and now. Take this shovel and \"save\" the humans.\n\nDo the right thing.", objectives = "" }
WordHunterWoW_QuestEN[28190] = { title = "The Tainted Ooze", description = "This all started with Winna Hazzard. She was a forsaken apothecary at Bloodvenom Post, researching ways to use the demonic ooze here against the Alliance.\n\nWe warned her she was going too far, but she didn't listen, and we did not act fast enough. Now her and everyone at Bloodvenom Post are nothing more than mindless slime creatures...\n\nThe disgusting oozes she used for this still roam near the pools to the east and south. I beg you, {class}, destroy them so that others cannot commit such evil.", objectives = "" }
WordHunterWoW_QuestEN[28191] = { title = "A Fitting End", description = "The Obsidian wyrmkin litter the landscape to our south. They're in no position to push back against us, but one can never tell what new threats the ebb of battle may bring.\n\nI want you to take the fight to the wyrmkin. Clear them out so that we may proceed with purging this land of the polluting presence of the black dragonflight.", objectives = "" }
WordHunterWoW_QuestEN[28192] = { title = "No One Here Gets Out Alive", description = "This farm is under lockdown! Nothing gets in and nothing gets out! We're still assessing the situation to try and figure out exactly what happened, but my theory is that the laborers ate the mushrooms and somehow mutated into hideous undead monsters. I mean, how else could this have happened? This is just a farm! We grow mushrooms here! And sludge! Yes, sludge!\n\nTake a look around, {class}, because now that you're here you can't leave until this issue is resolved.\n\nSee for yourself!", objectives = "" }
WordHunterWoW_QuestEN[28193] = { title = "Lockdown!", description = "Zhat buildink did not explode by itself!\n\nSomevone is tryink to do me in, and you von't rest until I find out who!\n\nShtaht vizh zhe guests. Visit vizh zhem, observe zheir demeanor, and zhen report back to me.\n\nIf zhey know anyzhink at all, I vill haff zhem interrogated!\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[28194] = { title = "The Great Escape", description = "Please, {class}! We need your help!\n\nWe're being kept in this building against our will. And with the commander on such a tirade, there's no telling what he might do to us!\n\nPerhaps if you were to secure some uniforms for us, we could sneak away.\n\nWe never should have come here. I see that now.\n\nIf you help us escape, I will write the TRUTH of what has happened here.\n\nThe men on those ships are all dressed in the garb we need.", objectives = "" }
WordHunterWoW_QuestEN[28195] = { title = "Sending a Message", description = "I haf eyes and ears in every corner of zhis region, {race}.\n\nI haf heard of zhe murmurings zhat go on amonkst my troops. I haf been most tolerant of zhis pathetic behavior - until now!\n\nI vill send zhe message to everyvone in my ranks, zhat dissension vill not be tolerated!\n\nYou are to exterminate zhe captains aboard my ships in dock. Zhey haf been amonk zhe most disgruntled.\n\nVhen zhis has been done, I vill monitor zhe communications and determine vhat to do next.\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[28196] = { title = "The Battle for Hillsbrad", description = "The journal documents the last 62 days of Clerk Horrace Whitesteed's life. In it is written damning allegations against Warden Stillwater and his activities at the Sludge Fields.\n\nYou should show this to the warden. He will undoubtedly have an explanation for what is written in this journal.", objectives = "" }
WordHunterWoW_QuestEN[28197] = { title = "Discretion is Key", description = "We must destroy all of the evidence, {name}! Did I say evidence? I meant crazed undead! Anyway, discretion is key. We must not let the rampaging undead make it out of the Sludge Fields and no one outside of this institution must know about what happened here!\n\nDirectly southeast of here in what used to be the old mushroom farm you'll find a reanimated fiend known as Citizen Wilkes and his cohort, Clerk Horrace Whitesteed. They have been causing huge problems for my guards. Find them and kill them!", objectives = "" }
WordHunterWoW_QuestEN[28198] = { title = "The Weakest Link", description = "They say a chain is only as strong as its weakest link.\n\nI subscribe to that theory and expand upon it.\n\nRather than removing that weak link, one must... strengthen it.\n\nThe other links will step up their performance out of fear of they themselves becoming the weakest link.\n\nIn my army's case, our weak link has a name.  Salhet.\n\nYou'll find him training near the bottom of those stairs.\n\nStart him off with something easy.  The hyenas on the hills to the west, perhaps.", objectives = "" }
WordHunterWoW_QuestEN[28199] = { title = "For Science!", description = "Samples... yes... must have samples! These, ah, experiments... I mean, these unfortunate laborers must be studied.\n\nTravel southeast to the first farm and kill the risen ghouls. From their decrepit corpses you must recover flesh samples. Bring them to me!\n\n<Arnauld wrings his hands together and laughs maniacally for no discernible reason.>\n\nMust test!", objectives = "" }
WordHunterWoW_QuestEN[28200] = { title = "The Element of Supplies", description = "You'll notice that we're slightly ill prepared for battle.\n\nThe tol'vir tribes had never seen any sort of major confrontation for thousands of years.\n\nAll the combat protocols that the titans programmed into our ancestors are still there, though.  Some are part of our instincts, some get passed on as tradition.\n\nBut none of this can compensate for lack of supplies.  We need weapons.  We need armor.\n\nThe best armor is lined with the skin of the riverbed crocolisks nearby.  Help us gather some.", objectives = "" }
WordHunterWoW_QuestEN[28201] = { title = "Ploughshares to Swords", description = "We have a sizeable army, but I'm afraid the coming showdown with the Neferset hordes will demand that all able-bodied tol'vir of Ramkahen and Orsis join in the fight.\n\nI want you to be at the forefront of our recruiting efforts.\n\nGo across the river, to the Akhenet Fields, and recruit the laborers that work there.", objectives = "" }
WordHunterWoW_QuestEN[28202] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28203] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28204] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28205] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28206] = { title = "A Lost Lad", description = "It was only yesterday that I sent him out to investigate the farm directly east of here, but it feels like an eternity has passed!\n\nTrue perfection. The way his blond locks framed his perfect blood elf face... Such strength. I didn't want to send him away, but he insisted! How could I refuse him?\n\nAlas, poor Johnny Awesome has not returned! I fear the worst, {name}. Find him!", objectives = "" }
WordHunterWoW_QuestEN[28207] = { title = "A Slimy Situation", description = "This poor fellow here barely escaped Bloodvenom Post with his life! If we're going to keep him from turning into a slime creature like all the others, we've got to treat the infection.\n\nMushrooms like to grow near the bright green waters around here, like the pond to the east beneath the falls. Most of them are no good... I need you to collect the bright green glowing ones!\n\nIf I have those, I'll be able to whip up something tasty to help this poor tauren. Don't take too long now!", objectives = "" }
WordHunterWoW_QuestEN[28208] = { title = "Winna's Kitten", description = "Mr. Tauren here's told me a lot about what happened at Bloodvenom Post. He says Winna Hazzard is still there!\n\nShe's pretty far gone, but what's left of her is making a bunch of new slime. We've got to stop it!\n\nLuckily, I have a plan. Mr. Tauren said Winna used to have a kitten. She fed it corrupted slime water and it ran off into the woods. I saw something lurking to the southeast just past the Bloodvenom Tower, but it sure was bigger than a kitten! Go see if the kitty has a tag...", objectives = "" }
WordHunterWoW_QuestEN[28209] = { title = "Freedom for Lydon", description = "This place is no farm! Stillwater has been experimenting on the humans of Hillsbrad. The monstrosities here are all his creations.\n\nThat's not the worst of it, {class}. The aberrations that have the key to my cage are former Forsaken. Stillwater's experiments have the side effect of turning Forsaken into mindless zombies. Why do you think he's so afraid of letting this get out? He knows that such a crime is punishable by true death.\n\nGet me out of here! The infected sludge guards outside have the key!", objectives = "" }
WordHunterWoW_QuestEN[28210] = { title = "Shaping Up", description = "High Commander Kamses has a special mission for me?\n\nWait... don't tell me.  It's hyenas again, right?\n\nVery well, I shall do my best.\n\nMeet with me at the Sunwatcher's Ridge.\n\nI won't disappoint you.", objectives = "" }
WordHunterWoW_QuestEN[28211] = { title = "Tempered in Elemental Flame", description = "First things first: We're going to need ammunition. Ammunition powerful enough to pierce the armored hide of a black drake. \n\nWest of Thundermar is a Wildhammer town that's been overrun with unbound fire elementals. Any weapons left behind in that conflagration will have been tempered in elemental flame. Tougher than anything I could whip up at this forge!\n\nFind me spears in the Humboldt Conflagration, {name}. The pointier the better.", objectives = "" }
WordHunterWoW_QuestEN[28212] = { title = "Hot Stuff", description = "I have a plan to quadruple the recommended torque for a standard speargun of this size, but according to my calculations the act of firing the weapon would shatter the casing. And possibly cleave the planet in two.\n\nI can weld together a chassis 100-times stronger if I had a good source of pure elemental flame for the smelting.\n\nUnbound Emberfiends are roiling around west of here, in the Humboldt Conflagration. Killing them should render them down to pellets of molten fury. Bring me some!", objectives = "" }
WordHunterWoW_QuestEN[28213] = { title = "Hazzard Disposal", description = "Winna's hooked tight into the source of the slime itself, at the very back of Bloodvenom Post to the west. She makes sure it keeps flowing, and it keeps her safe! But if you can get her attention...\n\nTake the eartag and show it to Winna. If there's even a little, tiny bit of her left, maybe it'll get through. Maybe her regret for her poor lost kitty will come to the surface and she'll feel sorry just one more time, and come out of the slime!\n\nAnd then maybe you can kill her and stop the slime. Yay!", objectives = "" }
WordHunterWoW_QuestEN[28214] = { title = "Cleanup at Bloodvenom Post", description = "Blurgh...\n\nCould you... ugh... could you please... URGH!\n\nExcuse me, I'm still a little... ugh, my stomach. If you're going to Bloodvenom Post to the west, could you please HUUURGH...\n\nJust... just put what's left of my friends out of their misery. Go RIGHT NOW. For your own good. Uuuuurghh...", objectives = "" }
WordHunterWoW_QuestEN[28215] = { title = "Potential Energy", description = "As you well know, the amount of energy stored in a conventional spring is equal to one half the spring's elasticity times the displacement squared. Unless you're using an elementium spring. Then the numbers get obscene! Mathematically grotesque!\n\nI need some elementium loops for my secret weapon, and it just so happens that Twilight's Hammer cultists use coils like that to bind earth elementals.\n\nFind them on the Obsidian Stoneslaves east of here, in the terrible region known as the Black Breach.", objectives = "" }
WordHunterWoW_QuestEN[28216] = { title = "Magmalord Falthazar", description = "I just heard the terrible news from the west - we've lost Humboldt's Stead. Wiped off the face of the planet in a wall of fire!\n\nThe Twilight's Hammer is to blame, and the survivors say it were the work of one Magmalord Falthazar. He's an ascendant - that's what they call the highest echelon of Twilight's Hammer cultists who become one with the elements. He's a creature of pure fire.\n\nAnd he'll soon be a creature of pure dead! Go kill Falthazar at the Humboldt Conflagration and bring me his head!", objectives = "" }
WordHunterWoW_QuestEN[28217] = { title = "WANTED: The Demon Hunter", description = "Since reclaiming Jadefire Run from the satyr, the Emerald Circle has sent many druids to begin the long task of cleansing the ruins. Last night, several of them were murdered... by a night elf.\n\nThe witnesses say it was a demon hunter, a crazed disciple of Illidan. A rare sight. No doubt he's gone mad with power just like his master.\n\nI'll pay top bounty for proof of this murderer's death. He's been spotted just off the road to the north, in a valley beneath Jadefire Run.", objectives = "" }
WordHunterWoW_QuestEN[28218] = { title = "A Destiny of Flame and Sorrow", description = "My kind has always been hated for what we do... despised outcasts, accused of corruption beyond redemption.\n\nYet if it was not for a demon hunter, these very woods would be the greatest stronghold of the Burning Legion on Azeroth. I speak of my master, Illidan Stormrage, the \"Betrayer\".\n\nSee for yourself. See what occured here when Illidan was first freed, and the demonic forces of the dreadlord Tichondrius ruled this forest completely unopposed...", objectives = "" }
WordHunterWoW_QuestEN[28219] = { title = "Buzzers for Baby", description = "<The tiny seedling opens its leaves wide, like a baby bird waiting to be fed. It speaks in a very faint voice:>\n\nHungry... want... bugs...<You can hear the buzzing of wasps to the south. Could they be what the little thing wants to feed on?>", objectives = "" }
WordHunterWoW_QuestEN[28220] = { title = "Seeking Soil", description = "<The tiny sproutling shuffles around, motioning you towards the south. You can barely hear a faint voice.>\n\nSoil...\n\n<It looks like it wants fresh soil. Maybe you should guide it to some of the richer-looking patches.>", objectives = "" }
WordHunterWoW_QuestEN[28221] = { title = "These Roots Were Made For Stompin'", description = "There's so many other spirits still trapped in rotting bodies here...\n\nDo you see? The irontree stompers, in the north. They're sick with demon-stuff and icky with mold. Poor spirits inside them can't get out.\n\nYou can help! Chop them down, and the spirits can get out. I'll put the spirits in me and we can all be happy together when I grow up. Will you help? Please?", objectives = "" }
WordHunterWoW_QuestEN[28222] = { title = "Singin' in the Sun", description = "We're growing so much bigger... It's time to shine! Time to spread our leaves to the sun!\n\nTake me to the sun! The sun is far away, but its light comes to us. Its light makes us big and strong again. The light comes down the big branches to the little ones like ours.\n\nOver there! The sun comes to us in the north! Take us with you, take us to dance!", objectives = "" }
WordHunterWoW_QuestEN[28223] = { title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in The Hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", objectives = "" }
WordHunterWoW_QuestEN[28224] = { title = "The Last Protector", description = "Ahhh... thank you, little {race}. I and others have tried so many times to grow in this forest, without success.\n\nThe Withered Protector that lurks in the north is the only ancient to have grown to maturity since the ruining of the forest, but his body is sick and his mind is mad. Just as we gathered the spirits of the treants, I would save those that dwell in him rather than leave them behind.\n\nDefeat him, and let his spirits join me before I set my roots.", objectives = "" }
WordHunterWoW_QuestEN[28225] = { title = "Prove Yer Allegiance", description = "Yer welcome to stay in Chiselgrip for a time, but I need to know that yer a friend.  So I've got a task for ye.\n\nWe of the Thorium Brotherhood're not the only dark irons here in the steppes.  Far from it.  We're pretty badly outnumbered by the dark irons of Blackrock Mountain.  We've got a safe enough foothold here in Chiselgrip, but even so, they still pester us from as close as the Ruins of Thaurissan, to the north.\n\nProve yerself, {race}.  Kill 'em for me.", objectives = "" }
WordHunterWoW_QuestEN[28226] = { title = "Scrapped Golems", description = "We keep golems here, as guards.  The dwarves to our north also keep golems, but I'm not sure why.\n\nMainly just for killin', I suppose.\n\nWe could use some spare parts for our own golems, so here's what yer gonna do: kill theirs, then look for any parts that might've fallen on the ground.  Salvage what ye can.  Ye probably won't be able to salvage everything, so choose carefully.", objectives = "" }
WordHunterWoW_QuestEN[28227] = { title = "Golem Training", description = "Yer provin' to be a pretty big help around here, {race}.  I was thinkin ye could help with just one more thing.\n\nOur guards are strong, but they're not as strong as you are.  I was thinkin', maybe if ye wouldn't mind, ye might help some of 'em with their training?  Just go up and talk to one and fight 'em a few times.  Hopefully they'll learn from yer moves and get better.", objectives = "" }
WordHunterWoW_QuestEN[28228] = { title = "Rejoining the Forest", description = "It is time to say goodbye now. You have raised me from a seedling, brief though it was, but now I must rejoin the forest.\n\nTake me back to the hill you found me on. There I will set my roots, and grow in the shadow of the ancients that came before me.", objectives = "" }
WordHunterWoW_QuestEN[28229] = { title = "Nature and Nurture", description = "The ancient protectors of Irontree Woods to the north have been dead for years, their bodies a grim symbol of the damage to these lands.\n\nEvery season, we take the water from this moonwell, and pour it on the ground before them, hoping it will nurture new life. If you'd like, you can deliver the water yourself.\n\nIt is an excellent opportunity for reflection. Take this vial and fill it at the moonwell, and pour it on the very top of the small hill between the three ancients.", objectives = "" }
WordHunterWoW_QuestEN[28230] = { title = "Protocol", description = "Before the warden receives his comeuppance we must deal with the outbreak. We cannot risk this contagion being released into the world.\n\nWithin the laborers' quarters, directly north of here, is a monstrosity Stillwater pieced together out of three farmers. This beast must be destroyed if we are to secure the Sludge Fields! Protocol demands it!", objectives = "" }
WordHunterWoW_QuestEN[28231] = { title = "Do it for Twinkles", description = "Warden Stillwater sent me out into the field to investigate the outbreak. When I arrived, Twinkles and I were charged by the lumbering monstrosity known as Verringtan. I was knocked off of Twinkles and immediately ran for my life. Twinkles, though, stayed behind and fought the beast off. Alas, she was defeated and then summarily planted in the soil as if she were some type of glorious star pony seedling.\n\nShe gave her life to defend me. Vengeance must be mine! If for nothing else, do it for Twinkles!", objectives = "" }
WordHunterWoW_QuestEN[28232] = { title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", objectives = "" }
WordHunterWoW_QuestEN[28233] = { title = "The Lost Brother", description = "Me brother Bahrum has gone missing!\n\nHe was one of the first scouts in the area.  All the others have returned safely, but there be no sign of him.  Da says he's just dawdlin' somewhere, but he's me only brother, and I promised me mum that I would keep him safe.  Will you please find him?", objectives = "" }
WordHunterWoW_QuestEN[28234] = { title = "They Took Me Pants!", description = "Why I be standing in the grain crate?  Long story short, there were hornets and some Dragonmaw that showed up at a bad time.  I got away safely, but the bastards took off with me legguards!\n\nMy sister made those for me from scratch, even engraved my name on...  I would die of shame if she found out I lost 'em.\n\nPlease find 'em for me - I saw the pant thief going into that fortress over there.  I'm going to stay here for *ahem* cover.\n\nAnd don't be asking what a Wildhammer wears under his kilt!", objectives = "" }
WordHunterWoW_QuestEN[28235] = { title = "Burnside Must Fall", description = "Magistrate Burnside was once the mayor of this region. In life he was a formidable adversary in the battle over Hillsbrad. In undeath he will surely test us.\n\nBurnside channels great arcane magic in the northwest section of the Sludge Fields. Lead us there and together we shall put an end to his rule, once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28237] = { title = "A Blight Upon the Land", description = "With the undead outbreak contained, the time has come for Stillwater and his followers to answer for their crimes. Though we averted a tragedy the likes of which has not been seen since the Scourge invaded, we must ensure that such a thing can never happen again. They will all face true death!\n\nCome, {name}! I will have Stillwater's head!", objectives = "" }
WordHunterWoW_QuestEN[28238] = { title = "Twilight Shores", description = "The time has come, {class}. With Stormwind secure, we will take this fight to the enemy. To the Highlands!\n\nThe bulk of our navy has already shipped out, thanks to your work earlier. But Fargo Flintlocke has prepared a seaplane that can make the journey in double-time.\n\nSpeak with Flintlocke down at the harbor and tell him that you are to accompany him to the Highlands. He will be by the water's edge. Safe journeys, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28239] = { title = "Into the Black Tooth Hovel", description = "This isn't really the most... convincing disguise I've seen, but it'll work.  Undercover work is all about swagger, anyhow.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.\n\nDo whatever Kaoshin asks you.  Colonel Troteman will be in touch via gnomecorder to give you any special instructions.\n\nGood luck out there, soldier.", objectives = "" }
WordHunterWoW_QuestEN[28240] = { title = "Tapped Out", description = "Listen, {name}.\n\nYou know I live to entertain you, and that I strive to keep you pleasantly occupied and whatnot.\n\nBut it just so happens that I've completely run out of ideas.\n\nThat was it!\n\nUsusally as I'm questing with you I can think of a few things to have you do next, which buys me time to cook up some grand objective, but no more.\n\nI'm tapped out. Completely uninspired. Couldn't muster up another idea to save my life.\n\nOh, wait!I know what we can do!\n\nTalk to me in a week or two...", objectives = "" }
WordHunterWoW_QuestEN[28241] = { title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through these funny magical balls: \"The Eyes of Twilight.\"\n\nIf I could get me hands on one of those, I bet we could use it to look in on Cho'gall and see what his creeps are up to. Get me one!\n\nSearch the Black Breach, east of here and just north of the river. Find me an Eye of Twilight, and do whatever you gotta do to bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[28242] = { title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", objectives = "" }
WordHunterWoW_QuestEN[28243] = { title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to the \"Low Shaman\" of Thundermar.\n\nOh yes, I already know where you're taking me. Blundy's meager, ale-soaked abilities are trivial. But you - you fascinate me, {race}. With my sight and your abilities, imagine the havoc we could unleash into this pathetic world together...", objectives = "" }
WordHunterWoW_QuestEN[28244] = { title = "Eye Spy", description = "I'll be honest, {name}. That thing gives me the willy-willies. But seein' as you went to all the trouble of bringin' it here, I s'pose we ought to put it to use.\n\nYou first.\n\nPeer into the eye and ask it to show you inside Cho'gall's Bastion of Twilight. We'll find out what that fat two-headed bugger is up to, and use it against him. ", objectives = "" }
WordHunterWoW_QuestEN[28245] = { title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping boy for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", objectives = "" }
WordHunterWoW_QuestEN[28246] = { title = "Strategic Cuts", description = "<Static> {name}... {name}, can you hear me?  It's Troteman.\n\nListen, we've just received the final bit of intel for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", objectives = "" }
WordHunterWoW_QuestEN[28247] = { title = "Last of Her Kind", description = "Obsidia is one of the last mature dragons that can continue the black dragonflight bloodline. She must be killed.\n\nIf you succeed in killing her, you should inform Lirastrasza immediately of your victory. She's been fighting a long time to see this done.\n\nThank you for being our fang in these battles. You've proven a powerful ally.", objectives = "" }
WordHunterWoW_QuestEN[28248] = { title = "Victors' Point", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them northwest, at Victors' Point. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", objectives = "" }
WordHunterWoW_QuestEN[28249] = { title = "Crushblow", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them west, at Crushblow. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", objectives = "" }
WordHunterWoW_QuestEN[28250] = { title = "Thieving Little Pluckers", description = "I don't have the most glamorous job in the world.\n\nI do not concern myself with matters of war or the deep mysteries of the halls of Uldum or what have you.\n\nI am in charge of these grounds... and these grounds grow dates.\n\nNow, these little date-plucking mongrels have gotten gutsy enough to stand on each other's shoulders to try and steal my precious fruit.\n\nI will not stand for this.\n\nTake this mallet, crafted by the titans, blessed by the sun-kings and who-knows-what-else and smash the runts!", objectives = "" }
WordHunterWoW_QuestEN[28251] = { title = "Trouble at Southshore", description = "Before my capture and imprisonment, I was stationed at Southshore. My primary job at the ruins was to take slime samples and make sure that the blight that we released was safely dissipating. Simple and easy if not for the worgen that would continuously harass us.\n\nI need you to head to Southshore and find my apprentice, Serge Hinott. Make sure that he's ok and inform him that I will return once my work here has concluded.\n\nYou'll find the Ruins of Southshore to the southeast, near the coast.", objectives = "" }
WordHunterWoW_QuestEN[28252] = { title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", objectives = "" }
WordHunterWoW_QuestEN[28253] = { title = "Taking the Horn For Ourselves", description = "{name}, it's Troteman.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew another attack was imminent, but our timetables were off by several days.\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", objectives = "" }
WordHunterWoW_QuestEN[28254] = { title = "A Needle in a Hellhole", description = "You and I can't take on an army, {name}.  They'll overwhelm us.  That's why we've got to stick to Troteman's plan.\n\nThe next part of the plan is going to require a bit of subtlety... something that I'm not terribly good at.  That's where you come in.\n\nSpeak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that we've collected.  He's going to need to size you.\n\nThat's right, {name}: you're going undercover.", objectives = "" }
WordHunterWoW_QuestEN[28255] = { title = "Vhat's Next?", description = "Vhich vay vill zhings turn out? Hmm?\n\nVill I turn on my dark master, whoever zhat might be?\n\nVill I learn to become a more sensitif and compassionate leader? Vill I go so far as to drop my adorable dialect?\n\nOr vill I embrace my aspirations and press forvard at all costs, never satisfied until all of Azerozh is mine?\n\nAnd vhat zhen, hmm?\n\nMaybe it vill all come togezher next veek...\n\n...or maybe zhe veek after zhat...", objectives = "" }
WordHunterWoW_QuestEN[28256] = { title = "The Skull of Gul'dan", description = "Illidan set out to find the Skull of Gul'dan. He fought through armies of demons to reach it, slaying them with the power that made him a hated outcast.\n\nSee him in battle, {class}. Witness the one that fought the fiercest against the corruptors of Felwood, and struck at its source.", objectives = "" }
WordHunterWoW_QuestEN[28257] = { title = "The Fall of Tichondrius", description = "Yes, Illidan took the power of the Skull of Gul'dan for himself.\n\nBut did he flee with it into the night? Did he use it for his own glory? No... his very first action was to use his new power to assault the dreadlord Tichondrius!\n\nWitness his triumph, {class}. Witness how Illidan reclaimed Felwood from the demons... and the thanks he was given.", objectives = "" }
WordHunterWoW_QuestEN[28258] = { title = "Meet with Signilda Hardforge", description = "Signilda Hardforge sent a message for you. She wants you to join her at her at the Training Hall in Stormwind's Old Town as quickly as you can. It sounded important, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28259] = { title = "Meet with Evelyn Thorn", description = "I just received a scroll from Evelyn Thorn in Stormwind. She wants you to pay a visit to the Training Hall in Stormwind. She doesn't mention specifics, but I got the impression that it was a matter of some importance.", objectives = "" }
WordHunterWoW_QuestEN[28260] = { title = "Meet with Dalgrun Steelpine", description = "Dalgrun Steelpine sends word from Stormwind -- he wants to meet with you right away. He'll be waiting for you in the Training Hall in Stormwind's Old Town district.", objectives = "" }
WordHunterWoW_QuestEN[28261] = { title = "Deceivers In Our Midst", description = "Now that you've had a lesson in keeping an open mind, perhaps you'd like to learn WHY I killed those druids.\n\nThe answer is simple: They are not druids at all.\n\nDemons still roam the ruins, now hiding in plain sight in the guise of friendly caretakers. See for yourself...this blindfold is soaked in demon blood. Take it north up the hills to Jadefire Run and place it on your eyes. It will show even the most oblivious fool the true nature of any demon.", objectives = "" }
WordHunterWoW_QuestEN[28262] = { title = "Meet with Veruca Darkstream", description = "Veruca Darkstream, one of the senior rogue trainers in Stormwind's SI:7, has sent word that he wants to speak with you. Head to Stormwind as soon as you can and look for her in the Training Hall south of Old Town.", objectives = "" }
WordHunterWoW_QuestEN[28263] = { title = "Meet with Frazzle Frostfingers", description = "I just received a message from Frazzle Frostfingers, the senior mage trainer in Stormwind. He's asking you to join him at the Training Hall in Stormwind as soon as you can travel there.", objectives = "" }
WordHunterWoW_QuestEN[28264] = { title = "Navarax's Gambit", description = "I have been preying on these demonic impostors for some time now, and I have finally gleaned the location of their leader. It is none other than Arch Druid Navarax, the leader of the Emerald Circle.\n\nThe demon shields himself with innocents. If I entered Whisperwind Grove to hunt him, I would be set upon by ignorant protectors... but you! You can catch him unaware.\n\nReturn to Whisperwind Grove. Climb the druid tower and you'll find Navarax at the top, in his room amidst the boughs.", objectives = "" }
WordHunterWoW_QuestEN[28265] = { title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"big three\" that run the ground forces here in Burning Steppes.  He does so from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  Troteman will be in touch, should we need anything further.", objectives = "" }
WordHunterWoW_QuestEN[28266] = { title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", objectives = "" }
WordHunterWoW_QuestEN[28267] = { title = "Firing Squad", description = "Come out back vizh me, {race}.\n\nZhere is somezhink I vould like you to see.", objectives = "" }
WordHunterWoW_QuestEN[28268] = { title = "Meet with Ezul'aan", description = "Ezul'aan from the Training Hall in Stormwind has sent a message for you. He wants to speak with you the next time you're in the city. The Training Hall is located in Stormwind's Old Town District.", objectives = "" }
WordHunterWoW_QuestEN[28269] = { title = "Meet Me In Vir'sar", description = "So, listen to this, {name}.\n\nI knew that these obelisks were linked to the Coffer of Promise, but there's more to it.\n\nThere appears to be something very important about the coffer - something pertaining to a place the Makers called the Halls of Origination.\n\nNow that we know this Schnottz fellow and his crew are in league with Deathwing, it's all the more urgent that we get to it first.\n\nI'll wait for you north of here, at the Oasis of Vir'sar\n\nHurry! They have a head start on us!\n", objectives = "" }
WordHunterWoW_QuestEN[28270] = { title = "Riding Shotgun!", description = "Alright, {name}, I'm very close to learning how to activate the final obelisk.\n\nOnly a few pieces of information are missing and with any luck, we should be able to find them at the site.\n\nThe supplies are all packed up. Let me know when you're ready to go.", objectives = "" }
WordHunterWoW_QuestEN[28271] = { title = "Reduced Productivity", description = "Alright, {name}, here's what I've learned.\n\nThere's a titan device deep in a place called the Halls of Origination. It's meant to be an emergency reset switch for all life on Azeroth. If activated, it will destroy every living thing in the world!\n\nNow, it's only meant to be used under certain extreme conditions, but if Deathwing is able to corrupt the titan watchers, he could use the contents of the coffer to trigger the device.\n\nGo to the Obelisk of the Moon, {name}. Slow them down!", objectives = "" }
WordHunterWoW_QuestEN[28272] = { title = "Missing Pieces", description = "There are just a few specific pieces of information that I'm missing.\n\nOnce those blanks are filled, we'll be ready to activate the final obelisk. Then, it'll be a race to discover the Coffer of Promise before Schnottz and his cronies can.\n\nThose fools are excavating this site as fast as they can. They're ruining more than they're looting!\n\nGo to the obelisk and rummage through their booty, {name}.\n\nSee if you can find our missing pieces.", objectives = "" }
WordHunterWoW_QuestEN[28273] = { title = "Friend of a Friend", description = "I need to unpack and look around the area a bit. In the meantime, I have an old friend I'd like you to meet.\n\nSullah and I go way back. He's a man who can be trusted, and that's pretty rare these days.\n\nWhy don't you go on over and introduce yourself.", objectives = "" }
WordHunterWoW_QuestEN[28274] = { title = "Two Tents", description = "Look at you, my friend. This grand adventure of yours has you in knots!\n\nYou need to relax and unwind. You're too tense, and that's just going to tire you out.\n\nTrust me, I know about relaxing!\n\nSpeaking of tents, I see Jonesy brought me the ones I asked for.\n\nCome, friend. Ride with me!", objectives = "" }
WordHunterWoW_QuestEN[28275] = { title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead over there and see what you can do.  Report back to me on your progress.", objectives = "" }
WordHunterWoW_QuestEN[28276] = { title = "Salhet's Secret", description = "Listen, {name}.  Before you give up on me, there's something I'd like to show you.\n\nYou see, I'm not much of a fighter.  I'm not very coordinated.\n\nI'm more of a tactical mind.\n\nMeet me at the southern end of the ridge and I'll show you.", objectives = "" }
WordHunterWoW_QuestEN[28277] = { title = "Salhet the Tactician", description = "Ever since I was a cub, I've always wanted to be a general.\n\nI was eager to join the army.  But as you've seen, my combat skills are not all quite there.\n\nThis is not the first time I've been sent to kill hyenas.  As a matter of fact, I get sent here so often, that I've befriended these lions and trained them to do my bidding.\n\nThey are my soldiers and at my command they will slay legions of hyenas.  Watch!", objectives = "" }
WordHunterWoW_QuestEN[28278] = { title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", objectives = "" }
WordHunterWoW_QuestEN[28279] = { title = "Abuse of Power", description = "{name}?  Troteman here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.\n\nTroteman out.", objectives = "" }
WordHunterWoW_QuestEN[28280] = { title = "Tear Them From the Sky!", description = "Egah! They're here, {name}. They're here!\n\nI had hoped to equip a whole army with my shoulder-mounted drake-droppers, but all I have is a single, extremely expensive and wholly untested prototype. Here, take it!\n\nShoot the Dragonmaw black drakes that are circling Thundermar, and drop them from the sky!", objectives = "" }
WordHunterWoW_QuestEN[28281] = { title = "Last Stand at Thundermar", description = "I'll hand it to you and your Alliance friends. You've really worked the Dragonmaw over!\n\nMany of their riders are dismounted but they're still coming at us, and my defenders will be overrun without help.\n\nKill Dragonmaw Skyclaws on foot and Thundermar will forever be in your debt!", objectives = "" }
WordHunterWoW_QuestEN[28282] = { title = "Narkrall, The Drake-Tamer", description = "There's one Dragonmaw among this lot, the one they call \"Narkrall: The Drake-Tamer.\" I don't know where he gets his power over those beasts, but the black terror he rides is as nasty a brute as ever took the skies over the Highlands.\n\n{name}, Narkrall is the fiend who took my father's life and left Thundermar in my hands.\n\nI can't take him on alone, but I've seen what you're capable of, {class}. Maybe together we can end this.\n\nLet me know when you're ready, and we'll fight Narkrall together!", objectives = "" }
WordHunterWoW_QuestEN[28283] = { title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", objectives = "" }
WordHunterWoW_QuestEN[28284] = { title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", objectives = "" }
WordHunterWoW_QuestEN[28285] = { title = "Meet with Patrice Lancaster", description = "I just received a scroll from the Training Hall, {name}. Patrice Lancaster sends word that she wishes to speak with you. You should meet with her as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[28286] = { title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to us here in Chiselgrip.", objectives = "" }
WordHunterWoW_QuestEN[28287] = { title = "Meet with Mulric Boldrock", description = "Mulric Boldrock's messenger just reached me, {name}. He has an important matter he wishes to discuss with you and sends word that you should meet him at the Training Hall in the Old Town district in Stormwind as soon as you can make it there.", objectives = "" }
WordHunterWoW_QuestEN[28288] = { title = "Open Their Eyes", description = "Before you go...\n\nI've taken advantage of my \"alone time\" with Impsy here to learn some interesting facts about imps. Specifically, he ended up telling me the one thing that all imps fear most. Something they're absolutely terrified of.\n\nI thought that sounded useful as well as interesting, so I've done some basic conjuring. This prism will project an image of... well, of what Impsy described.\n\nShadowlurk Ridge is still swarming with imps. Why don't you go test their reaction for me?", objectives = "" }
WordHunterWoW_QuestEN[28289] = { title = "Moonglade Calls", description = "I have received word that our brothers in Moonglade have requested your help, {name}. You should travel there and speak with Loganaar in Nighthaven. He will tell you all you need to know.", objectives = "" }
WordHunterWoW_QuestEN[28290] = { title = "Meet with Gormok Ogrefist", description = "Gormok Ogrefist sent an urgent message for you, {name}. He wants you to join him immediately at The Barracks in Orgrimmar's Valley of Honor. He must have a mission of importance for you.", objectives = "" }
WordHunterWoW_QuestEN[28291] = { title = "Return to Camp", description = "What do you think, {name}?  Maybe the High Commander will give me a few men to command.\n\nMaybe we can marshal a regiment together.  What do you think?", objectives = "" }
WordHunterWoW_QuestEN[28292] = { title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Harrison Jones in Stormwind. He'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[28293] = { title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Belloc Brightblade at Grommash Hold in Orgrimmar. He'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[28294] = { title = "The Kirthaven Summit", description = "After the licking we just gave 'em, the Dragonmaw assaults on Thundermar ought to stop. Maybe the Wildhammer do have a place in your Alliance - we Thundermars certainly owe you a debt.\n\nUp in Kirthaven, our Grand Shaman Lachlan MacGraff has been trying to arrange a summit between the surviving Wildhammer family leaders. It's a tall order to get us all to work together, but I'm at least willing to give it a go.\n\nFly up to Kirthaven in the North and talk to Lachlan MacGraff. I'll meet you there!", objectives = "" }
WordHunterWoW_QuestEN[28295] = { title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Harrison thinks a moment.>\n\nYou need to continue the research you've begun. Head to the southern end of Kalimdor, to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", objectives = "" }
WordHunterWoW_QuestEN[28296] = { title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Belloc thinks a moment.>\n\nYou must continue the good research that you've begun. Head south to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", objectives = "" }
WordHunterWoW_QuestEN[28297] = { title = "Meet with Tamanji", description = "I received a scroll for you from Tamanji in Orgrimmar. She wants you to make your way to The Barracks in the Valley of Honor and speak with her as soon as you can. It sounded urgent, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28298] = { title = "Meet with Thega Graveblade", description = "Thega Graveblade, the senior rogue trainer of the Shattered Hand in Orgrimmar, wishes to meet with you. Make your way to Orgrimmar quickly, {name} and seek her out at The Barracks in the Valley of Honor. She must have an important mission for you.", objectives = "" }
WordHunterWoW_QuestEN[28299] = { title = "Meet with Kazak Darkscream", description = "I have just received word from Kazak Darkscream, Orgrimmar's foremost warlock trainer. He wishes you to travel to Orgrimmar and speak with him at The Barracks in the Valley of Honor. It sounds like he has an important mission for you.", objectives = "" }
WordHunterWoW_QuestEN[28300] = { title = "Meet with Feenix Arcshine", description = "I just received a scroll for you from Orgrimmar, {name}. It's from Feenix Arcshine, one of the mage trainers there. He wants you to meet with him at The Barracks in the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28301] = { title = "Meet with Hretar Riverspeaker", description = "An urgent message just arrived for you, {name}.  It's from Hretar Riverspeaker, one of the shaman trainers in Orgrimmar.  He requests your presence as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[28302] = { title = "Meet with Avaros Dawnglaive", description = "You should make your way to Orgrimmar as soon as you can, {name}. Avaros Dawnglaive has sent word that he wishes to speak with you about a matter of importance to the Horde. Look for him at The Barracks in the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28303] = { title = "Meet With Avaros Dawnglaive", description = "Avaros Dawnglaive sent an urgent message for you, {name}. He asks you to join him at The Barracks in Orgrimmar's Valley of Honor the next time you're in the city. It sounds as though he must have an important assignment for you.", objectives = "" }
WordHunterWoW_QuestEN[28304] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28305] = { title = "The Fate of Bloodvenom Post", description = "While we dealt with Jaedenar, I sent a friend of mine north to Bloodvenom Post. We used to have infrequent visits from the tauren there, but they have stopped coming as of late.\n\nMy friend, Kelnir Leafsong, has yet to return. Would you travel north to check on her and the situation at Bloodvenom?\n\nShould you find her, do be aware... dryads like her tend to strike other races as a bit odd.", objectives = "" }
WordHunterWoW_QuestEN[28306] = { title = "Whisperwind Grove", description = "You've been such a big help here!\n\nI'm gonna stay here a while and look after poor Mr. Tauren until he stops throwing up so much. Why don't you head north to Whisperwind Grove? It's really pretty there, and all the druids are so friendly!\n\nYou should tell Miss Puregrove I'm okay, she'll worry if I'm gone too long. She might ask you to help with her flowers, too! So fun!", objectives = "" }
WordHunterWoW_QuestEN[28307] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28308] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28309] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28310] = { title = "Morgan's Vigil", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the east, to Morgan's Vigil.\n\nOur intel indicates that Morgan's Vigil has been vacated, as most of its inhabitants have moved into Blackrock Mountain to fight their own battle against the Blackrocks.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, Keeshan will be joining you on the road.  As will I.", objectives = "" }
WordHunterWoW_QuestEN[28311] = { title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the northwest.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", objectives = "" }
WordHunterWoW_QuestEN[28312] = { title = "Latent Demons of the Land", description = "The lava beds nearby - to the west - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", objectives = "" }
WordHunterWoW_QuestEN[28313] = { title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Troteman produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our northeast.", objectives = "" }
WordHunterWoW_QuestEN[28314] = { title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", objectives = "" }
WordHunterWoW_QuestEN[28315] = { title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[28316] = { title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  Troteman's been hanging onto them, and we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", objectives = "" }
WordHunterWoW_QuestEN[28317] = { title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", objectives = "" }
WordHunterWoW_QuestEN[28318] = { title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the big three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", objectives = "" }
WordHunterWoW_QuestEN[28319] = { title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Troteman hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", objectives = "" }
WordHunterWoW_QuestEN[28320] = { title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  This is where it hits the fan.  Where all the pieces come together.\n\nStrap in, and come with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", objectives = "" }
WordHunterWoW_QuestEN[28321] = { title = "Glory Amidst Chaos", description = "You and Keeshan are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Hunt down those sniveling Blackrocks, and teach them the might of Redridge!", objectives = "" }
WordHunterWoW_QuestEN[28322] = { title = "The Spoils of War", description = "We've toppled a giant today, {name}.  While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near Redridge anytime soon.  You and Keeshan saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", objectives = "" }
WordHunterWoW_QuestEN[28323] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[28324] = { title = "Studies in Lethality", description = "We used a fairly potent strain of blight against the humans of Southshore. As you can see, it worked. The trouble with blight use, though, is that blight tends to stick around after it's served its purpose.\n\nWhat I need from you is to take this testing kit and get out into the field to get a lethality count from the blight slimes that we've released into the area. Use the lethality analyzer on the blight slimes sweeping the slime pools. Come back to me when you have some solid data.", objectives = "" }
WordHunterWoW_QuestEN[28325] = { title = "Green Living", description = "Recycling! It's all the craze these days. The Banshee Queen has decreed that we must conserve if we are to prosper as a people. Everyone must do their part, right? With that said, you will be doing our part for us.\n\nThere are likely thousands of blight canister bits and pieces all over Southshore. We can reuse those canisters for more blight bombing goodness. Just head into the ruins here and pick up whatever you can find.\n", objectives = "" }
WordHunterWoW_QuestEN[28326] = { title = "Placing the Pawns", description = "{name}.  It sounds like you and Keeshan have finished with your tasks.  I've also finished mine.\n\nReturn to Morgan's Vigil.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before we kill them.", objectives = "" }
WordHunterWoW_QuestEN[28327] = { title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Morgan's Vigil, NOW.", objectives = "" }
WordHunterWoW_QuestEN[28328] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer reaches far and wide. They search ceaselessly for allies in their battle against us and they are recruiting the Dark Iron dwarves of Blackrock Depths to their cause.\n\nMoira's grip on the Dark Irons is tenuous at best and more of her people fall away from her rule with each day. We must sabotage their recruitment efforts.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28329] = { title = "Angry Scrubbing Bubbles", description = "These blight slimes seem to be really angry. They've even got a faint outline of an angry humanoid face in their ectoplasm. You don't think Hinott would be too happy about having non-compliant slimes working the slime pools.\n\nKill any angry blight slimes that you see and try to get a lock on a breeding pool.", objectives = "" }
WordHunterWoW_QuestEN[28330] = { title = "Trail of Filth", description = "The trail of filth and anger leads into the ruined town hall. Surely there is a slime breeding pool inside the structure. Fight your way inside and deal with whatever angry slime-breeder that you encounter!\n\nShould you succeed Serge Hinott at the Ruins of Southshore will surely want to hear about it.", objectives = "" }
WordHunterWoW_QuestEN[28331] = { title = "Helcular's Rod Giveth...", description = "To think, I, a master of necromancy, trained by Kel'Thuzad himself, was reduced to nothing more than a corpse in a grave. Thankfully, my astute apprentice, Thaivand, managed to find a group of heroes to recover this:\n\n<Helcular whips out his rod.>\n\nIt is through the power of the rod that I was reborn. The rod giveth and the rod taketh away!\n\nTake it now and use it to empower our dark rangers battling the worgen in the field north of us. Renew their vigor with my rod.", objectives = "" }
WordHunterWoW_QuestEN[28332] = { title = "Helcular's Command", description = "Our dark rangers search the fields for worgen terrorists. These worgen have been sent out by their dark masters to hunt and kill us. And though a dark ranger is a formidable combatant, the worgen often attack in packs, which can overwhelm even a dark ranger.\n\nSearch the fields around the ruins of Southshore for Bloodfang forsaken hunters. Kill any that you see! For the Forsaken and for Lordaeron!", objectives = "" }
WordHunterWoW_QuestEN[28333] = { title = "It's Time to Oil Up", description = "Three things come out of Irontree Clearing: lumber, oil, and exhausted workers. The first two are pretty much the cause of the third, but I like to be efficient about things where I can.\n\nI've got our shredders working triple unpaid overtime, and there's really nowhere in the schedule for them to get maintenance.\n\nUse this grappling hook to nab some of the extra oil cans floating around camp and use them to oil up the shredders, would you?", objectives = "" }
WordHunterWoW_QuestEN[28334] = { title = "A Flare Fight", description = "This operation's stayed pretty discreet so far, but the worgen over in Talonbranch Glade have it out for us. They've been trying everything they can to get us shut down.\n\nSome of the workers have told me they've seen glimpses of worgen lurking around the clearing. Take these oversized megaflares. They're bright enough to show anything that gets anywhere near them.\n\nUse the flares to look for prowling worgen, and make sure they don't leave here alive!", objectives = "" }
WordHunterWoW_QuestEN[28335] = { title = "Turn It Off! Turn It Off!", description = "It was those darn worgen! They blew right past me into the cavern.\n\nThey must've messed with the Master Control Pump! If that thing is left on too long, every pipe runnin' under our feet is gonna blow. You think the leaks now are bad? Just wait!\n\nListen, if you can reach the Master Control Pump all the way in the back of the cavern, you can shut it off and save us all!", objectives = "" }
WordHunterWoW_QuestEN[28336] = { title = "Slap and Cap", description = "Oh for... not again! If you heard the deputy yelling out there, that means we've got a fullblown oil leak on our hands! It's those filthy worgen again!\n\nListen, it's going to be total chaos out there. Sleep-deprived goblins running around screaming and not knowing what to do. I need you to snap the workers back to their senses.\n\nA good, swift backhand across the face should do it! Once they shake themselves off, they'll get to work capping those gushers!", objectives = "" }
WordHunterWoW_QuestEN[28337] = { title = "The Shredders of Irontree", description = "Disgusting, isn't it? Look at them. Pathetic little things that can't even toil with their own bodies.\n\nThey stomp around in their massive metal shredders, carving the forest to splinters. I bet they think they're safe in there, all warm and cozy.\n\nProve them wrong. Blaze north through the camp and destroy as many shredders as you can. Once you've spilled some blood, we're going to take this place apart for good.", objectives = "" }
WordHunterWoW_QuestEN[28338] = { title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, {name} - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", objectives = "" }
WordHunterWoW_QuestEN[28339] = { title = "Is Your Oil Running?", description = "Last time we had an oil leak this bad, the oil itself tried to get away!\n\nI don't know what does it, maybe all the demon goop floating around here, but when we get a big enough crude leak half of it globs together and tries to run away.\n\nThat's profit trying to escape! Go run after those oil sludges and bring back their sweet, precious oil!", objectives = "" }
WordHunterWoW_QuestEN[28340] = { title = "A Bomb Deal", description = "All my workers got driven straight out of the cavern here by those big swamp-lookin' things! Darla's sent me here to pick up the pieces, but have you seen it in there? I ain't goin' in!\n\nThere's a ton of explosives left behind that we can't just leave layin' around.\n\n I'll make you a deal: You run in there and get those explosives gathered up, and I will stay here and not get killed by swamp-things, and if you don't either, I'll pay ya! How's that sound?", objectives = "" }
WordHunterWoW_QuestEN[28341] = { title = "Collecting Corruption", description = "Though we druids shun the demonic powers infesting this land, it must still be confronted.\n\nShatter Scar Vale to the south seethes with corruption. The energies there are so chaotic that they manifest as violent entities, pure fel magic given form to lash out at all life.\n\nI have been keeping a close eye on these chaotic beasts, and studying their strength. I need to make sure they are still weakening with time. Bring me the essences they drop, so I may ensure they are diminishing.", objectives = "" }
WordHunterWoW_QuestEN[28342] = { title = "Fel To Pieces", description = "The infernals that lurk in Shatter Scar Vale are formidable, but not invincible. Much progress has been made in thinning their numbers.\n\nDestroying them is only part of the solution, however. I've found that the stone that infernals are made of still contains large amounts of fel magic even after the infernal's death.\n\nThe rubble of slain infernals now litters Shatter Scar Vale, leeching its corruption back into the ground. If you could collect it and bring it to me, I would be grateful.", objectives = "" }
WordHunterWoW_QuestEN[28343] = { title = "The Breath of Cenarius", description = "{name}, we have learned that a missing Cenarion artifact has surfaced in the hands of a Twilight's Hammer pyromancer. Pyromancer Loregrain has taken this artifact, the Breath of Cenarius, into Blackrock Depths and uses its power to open elemental gates.\n\nWe must act to keep Loregrain from summoning elementals to bolster the ranks of his Dark Iron allies. Recover the artifact from him and use its power to close the gates that Loregrain has been using.", objectives = "" }
WordHunterWoW_QuestEN[28344] = { title = "Can You Smell What the Lok'tar is Cooking?", description = "Shortly before you arrived an orc flew in upon a frost wyrm and demanded that I direct him to where the 'newbies were hanging out.' Uncertain as to the vernacular, I told him to fulfill his duty as a member of the Horde and deal with the worgen threat of the area. He grumbled something about 'what the lok'tar was cooking' and headed south to the docks.\n\nOrdinarily I wouldn't care about whether or not an orc went missing, but I am genuinely curious about what the lok'tar might be cooking. Find out.", objectives = "" }
WordHunterWoW_QuestEN[28345] = { title = "*Gurgle* HELP! *Gurgle*", description = "*GURGLE*\n\nHELP!*GASP*\n\nORKUS IS DROWNING! HELP ME, QUEST GIVER {name}!\n\n*GLUB*\n\nDwarf threw Orkus into the water! Must not die!\n\n*GURGLE*\n\nThe shame would be too great.", objectives = "" }
WordHunterWoW_QuestEN[28346] = { title = "The Bachelor", description = "We need to make this work, {name}. The answer is in the blood! Family bonds have kept these Wildhammer clans apart from one another. It'll take family bonds to glue 'em back together. It's a long shot, but we're going to have to play matchmaker!\n\nI'll track down Colin Thundermar and talk with him. You're a smooth one - you should talk to Keegan Firebeard inside. He's sharp enough to understand a political marriage. Go find out if he fancies anyone!", objectives = "" }
WordHunterWoW_QuestEN[28348] = { title = "Stormpike Rendezvous", description = "I tracked down the decrepit necromancer, Helcular, in hopes of getting a lead on Alliance movement within Hillsbrad.\n\nHelcular tasked me with finding and killing worgen. Ordinarily this would not be a problem for Orkus, but I had just eaten several helpings of Dirge's Kickin' Chimaerok chops, causing my bowels to cry out in anguish. That's when the trouble began and how I ended up in the water.\n\nHear Orkus out, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28349] = { title = "Megs in Marketing", description = "Boss, while you were down at the mines, Megs Dreadshredder in marketing was asking for you. Something about your \"new image\" or whatever.\n\nShe's right outside the building to the left.", objectives = "" }
WordHunterWoW_QuestEN[28350] = { title = "Master Trapper", description = "One thing about me that you might not know, {name}...\n\nI come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner.\n\nAs any master trapper will tell you, the most important ingredient in an effective trap is the bait.\n\nSo let's start there.\n\nFill this bucket with the meat scraps from almost any wild creature in Uldum.", objectives = "" }
WordHunterWoW_QuestEN[28351] = { title = "Unlimited Potential", description = "Some see the little sand pygmy as nothing more than a pest, a vermin, or worse yet, a vile little demon.\n\nI say they are simply misunderstood!\n\nWith the proper care and guidance, these little fellows may just turn out to be a glorious gift of nature.\n\nI would like you to take these cages and use them to capture a few of them for me to work with.\n\nYou will need to give them a sound beating before boxing them up, but in the end it will be for their own good.\n\nYou'll see!\n\nGo south for pygmies!", objectives = "" }
WordHunterWoW_QuestEN[28352] = { title = "Camelraderie", description = "Greetings, friend!\n\nYou are always most welcome in my humble tent.\n\nLooking for something to do? Sullah has just the thing!\n\nCamels are good to have in hand regardless, but when putting together a performance the likes of my sideshow, they are an absolute must!\n\nTake this harness and use it to subdue a wandering camel.\n\nYou may have to, uhh, humble it a bit first... if you know what I mean.\n\nYou'll find a desert full of wild camels to the south.", objectives = "" }
WordHunterWoW_QuestEN[28353] = { title = "Jonesy Sent For You", description = "Listen, {name}, you may want to make your way back to Jonesy when you get a moment.\n\nChances are, whatever he's got to talk to you about is more pressing than anything I have for you to do.", objectives = "" }
WordHunterWoW_QuestEN[28354] = { title = "Kasha Will Fly Again", description = "Kasha will fly again, {name}. She must if we are to claim vengeance! Sadly, Orkus must stay here with Kasha. You must help us. I beg of you!\n\nListen carefully, quest giver. When I first arrived here I flew around for days to learn the lay of the land. There is a farm east of here that has long since been abandoned and is now overrun by gnolls. On this farm grows a special type of mushroom known as the mudsnout. Go to the stead and gather mudsnout for Kasha. Return here when your pack is full.", objectives = "" }
WordHunterWoW_QuestEN[28355] = { title = "Terrible Little Creatures", description = "Gnolls! These terrible little creatures are a blight upon any land - which is saying a lot when you consider that Hillsbrad is Forsaken territory. Kill as many of the gnolls at the Nethander Stead as you can. For the good of the world!", objectives = "" }
WordHunterWoW_QuestEN[28356] = { title = "Preemptive Strike", description = "These plans document what appears to be an imminent attack on Southshore. The naga of the Eastern Strand are planning to take over the town now that the Alliance has been pushed out.\n\nNot if you can help it!\n\nKill all of the naga on the Eastern Strand and report to Helcular at the Ruins of Southshore with the Daggerspine attack plan.", objectives = "" }
WordHunterWoW_QuestEN[28357] = { title = "Take it to the Tree", description = "Those mangy curs think they can just snoop around my site and get away with it? I'll show them...\n\nAnd what I mean by that is, of course, that YOU will show them. You and the small army of axe-wielding goblin hires I've sent to Talonbranch Glade.\n\nThe place will be swarming with worgen by now. Just where we want them. Head to the southeast, join up with the rest of our forces, and let some fur fly.", objectives = "" }
WordHunterWoW_QuestEN[28358] = { title = "Hunting the Damned", description = "The first demons to set foot in this forest were infernals. Long ago, these powerful beings of stone and demonic fire fell from the sky to take this land for the Burning Legion.\n\nThe charred craters of Shatter Scar Vale to the south are where these infernals landed, and many still wander there. They are fierce foes, and killing them is both a worthy challenge and a noble cause.\n\nI offer reward for those who join the hunt. Return here afterwards.", objectives = "" }
WordHunterWoW_QuestEN[28359] = { title = "The Core of Kroshius", description = "The most fearsome demon in Shatter Scar Vale is known as Kroshius. Though many have hunted him over the years, destruction has only made him stronger.\n\nTime after time, warlocks have come to this forest and reanimated Kroshius. He now lurks in the southeast, surrounded by demonic fire, awaiting any who come to try and claim his power.\n\nI will not have this corrupt cycle continue! Kill Kroshius, and bring his infernal core to me.", objectives = "" }
WordHunterWoW_QuestEN[28360] = { title = "Running Their Course", description = "I'd love so much to save every creature in the forest, but as you probably have seen, some are just too far gone.\n\nWhen we first founded Whisperwind Grove, the woods just to the south were full of beautiful coursers, majestic and gentle creatures. The corruption here hasn't made them violent, but they've wasted away to nearly nothing.\n\nEven if they were cleansed, they would know only pain and suffering. Please, {class}, help put them down for me.", objectives = "" }
WordHunterWoW_QuestEN[28361] = { title = "Squirrely Clean", description = "The larger animals are often too far corrupted to save, but you'd be surprised how hardy the little ones are.\n\nTake the squirrels, for example. After washing in corrupted water, they can spread illness far from the original source, but it's slow to affect the squirrels themselves. In fact, a simple washing will result in a clean squirrel and a safer forest!\n\nHere, take this bottle of cleaning mixture. Grab and scrub any squirrel you see in the woods to the south... they'll be thankful for it!", objectives = "" }
WordHunterWoW_QuestEN[28362] = { title = "Stupid Drizle!", description = "Stupid, stupid Drizle! I told him not to go!\n\nDrizle wanted to steal more honey from Felpaw Village... you know, just west of here? You can see it from the cliff...\n\nAnyway... I told him it was a dumb idea but he went anyway, and then the Deadwood tribe got him, and... and...\n\nSniff...\n\nI don't know what they're gonna do! Please find him, Mr. {race}! Even if he is a dummy! I don't want Drizle to get eaten!", objectives = "" }
WordHunterWoW_QuestEN[28363] = { title = "Stirred the Hornet's Nest", description = "Wow!\n\nIt sounds like you really got their attention, {name}. We're never getting in there with them on alert like this.\n\nThere must be a way...\n\nIt's just a matter of time before Schnottz's men activate the obelisk and I need to research the scrolls you found. I need you to figure this one out without me.\n\nSullah has connections in these parts. Maybe he has a solution for getting us inside.", objectives = "" }
WordHunterWoW_QuestEN[28364] = { title = "The Chieftain's Key", description = "Sniff... I'm sorry! I didn't mean to get caught! They grabbed me and put this chain on me and left me here! I can't move and my leg fell asleep and I'm hungry!\n\nThe chief has the key... Chieftain Bloodmaw, the other ones said. He's in the north end of the camp.\n\nBut hurry! Please! Don't leave me alone here!", objectives = "" }
WordHunterWoW_QuestEN[28365] = { title = "<PH>Drizle Safe", description = "", objectives = "" }
WordHunterWoW_QuestEN[28366] = { title = "Disarming Bears", description = "I would prefer to do as much as we can to protect my people from the Deadwood tribe without slaughtering every last one of them. We've taken steps towards this before, and if you wish to prove yourself to the Timbermaw tribe, I would ask you do this as well.\n\nLook for the piles of weapons kept in Felpaw Village to the southwest. Take as many as you find. If we disarm the Deadwood tribe, we may be able to stop some bloodshed later.", objectives = "" }
WordHunterWoW_QuestEN[28367] = { title = "Shroud of the Makers", description = "It is good to have friends, {class}! While kindness is its own reward, there can be tangible benefits too!\n\nSome friends of mine recently intercepted a shipment of Schnottz's plunder and found something that should serve your needs nicely.\n\nIt's a piece of titan technology that renders the user nearly invisible. If you use it in the enemy camp, you might be able to rewire their explosives and make a mess of their operation.\n\nEach charge has a limited duration, so don't stray too far from safety!", objectives = "" }
WordHunterWoW_QuestEN[28368] = { title = "Fire in the Hole!", description = "Land's sakes, pardner! You done shut off those valves but good.\n\nUnfortunately we've had a critical blowout in our gosh-darned central burnoff regulator! Missus Darla's done sent as many workers as she can rustle to go shut it off, but those flames have a mind of their own!\n\nLiterally! They're hoppin' up and grabbin' anyone who comes near! So Darla says if you can muster up out of that cave you're in and beat that elemental, she's got a mighty fine prize in store for ya!", objectives = "" }
WordHunterWoW_QuestEN[28369] = { title = "My Sister, Fanny", description = "Before you go, be sure to stop by the inn behind me. My sister Fanny is inside.\n\nRefugees are pouring into Thundermar from all of the torched Wildhammer settlements around us, and I put Fanny in charge of 'em. She's tough as talons, that one. But she might need your help.", objectives = "" }
WordHunterWoW_QuestEN[28370] = { title = "Wisp-napping", description = "Can you believe these worgen here have wisps?  The night elves showed them all that druid junk and now they've got their precious little wisps too, giving them all the building material they want without having to harm any precious trees.\n\nIf we had those things, we could pull extra wood out of every tree in our site. Free resources, free profit! That's why I've been working on this containment device.\n\nHead to Talonbranch Glade and use it to steal some wisps. Just point and press the button.", objectives = "" }
WordHunterWoW_QuestEN[28372] = { title = "Back to Business", description = "All this happy friends stuff is great, isn't it? People working together, healing the forest. But what's gonna happen to the forest when it's healed? It's just gonna sit there?\n\nWe need this lumber. The Horde needs it. I've got orders here to send as many loyal Horde soldiers--and I'm sure you're loyal--up north to Irontree Clearing.\n\nI've already arranged for the hippogryph master to give you a free ride over there. Talk to Darla Drilldozer when you touch down.", objectives = "" }
WordHunterWoW_QuestEN[28373] = { title = "Timbermaw Hold", description = "Okay, I know this is a longshot, but I figure it never hurts to ask.\n\nWhile I deal with the fallout of all the ridiculous nonsense that just went on here, I need you to go speak to some bears. The Timbermaw furbolg control the forests to the northeast, and they're not too fond of us.\n\nI just need someone to give them the idea the Horde isn't all that bad. Head northeast up the road to Timbermaw Hold--don't go into Felpaw Village--and ask the furbolg outside if they have any favors they'd like done.", objectives = "" }
WordHunterWoW_QuestEN[28374] = { title = "Weeding the Lawn", description = "In a place like this, even something as simple as growing flowers and pulling weeds can require some heroic effort.\n\nThe orchid lashers that grow on all sides of the grove are a sign of healing. But they're not flawless; some of them do succumb to demonic corruption now and then.\n\nI've found the best way to check is to just pull them up. If they're normal, they'll wander around a bit and reroot themselves. If they aren't... well, you'd better be ready for a fight!", objectives = "" }
WordHunterWoW_QuestEN[28375] = { title = "The Road to Purgation", description = "The time of vengeance has come, {name}. Kasha can once more fly, thanks to you. She will take us to Purgation Isle so that we may confront the Stormpike dwarf general, Vanndar Stormpike, and his captain, Balinda Stonehearth. BOTH will pay for what they have done.\n\nAre you ready? Orkus cannot do this alone.", objectives = "" }
WordHunterWoW_QuestEN[28376] = { title = "Myzerian's Head", description = "The head of one of Deathwing's most formidable black dragons is now in your possession.\n\nWhile many in Azeroth would pay dearly for such an artifact, something tells you that it belongs in a museum for all to see and remember.\n\nHarrison Jones is likely to have the proper connections.\n\nSullah would certainly be happy to deliver it to him.", objectives = "" }
WordHunterWoW_QuestEN[28377] = { title = "Rescue at Glopgut's Hollow", description = "Well speak of the devil in a blue dress. Fanny's gone and gotten herself kidnapped by ogres!\n\nI don't trust the Thundermars to be able to mount a rescue on their own. I'll round up my gryphon riders and provide some air support.\n\nI'm sure they can use an extra {class} down there, {name}. Grab your gear and look for Colin Thundermar in the Glopgut ogre camp. It's southwest of here, below the cliffs. Hurry now!", objectives = "" }
WordHunterWoW_QuestEN[28378] = { title = "Find Fanny", description = "We've started tearing this camp apart, {name}, but there's no sign of Fanny. Maybe you can find her.\n\nWe haven't checked the cave just behind me, to the northwest. See if you can find Fanny in the cave!", objectives = "" }
WordHunterWoW_QuestEN[28379] = { title = "Ogre Bashin'", description = "Glopgut ogres! I'd say they was dumb as a sack of hammers, but I have more respect for me hammers than that.\n\nWe've fought off their raids for years, but if they're bold enough to steal one of our own, we're gonna have to learn them a lesson.\n\nHelp us smack around some Glopgut ogres! Kill their pounders, hurlers, or bashers either out here or - better - inside the cave. That'll show 'em. ", objectives = "" }
WordHunterWoW_QuestEN[28380] = { title = "Pikwik in Peril", description = "What the heck is going on here? Foreman Pikwik should've shut the valves off by now.\n\nWe can cap these leaks all day and if the central valve is off, we're just delaying an enormous explosion.\n\nListen, if you value money, your life, or either combination of the two, you'd better head south to Irontree Cavern and see if you can find Foreman Pikwik.", objectives = "" }
WordHunterWoW_QuestEN[28381] = { title = "The Denmother", description = "Barely a crow's flight to the north, goblins ravage this forest, clearcutting it to fuel the war machines of the Horde and line their own pockets. This one pays enough pleasant words and crafted lies to the druids here for them to turn a blind eye, afraid to disturb the tenuous neutrality here.\n\nThe worgen of Talonbranch Glade have had enough. Join us! The hippogryph master can take you directly to our home. Denmother Ulrica will welcome any {race} who wishes to fight.", objectives = "" }
WordHunterWoW_QuestEN[28382] = { title = "Enemy at our Roots", description = "The goblins are already upon us!\n\nWe have tried everything in our power to warn the goblins to leave Irontree Clearing before we resorted to violence. As they turned a blind ear to us, we struck, and now rather than spare the forest they would lay down their lives for greed.\n\nThey will soon know the full extent of our fury! The battle rages just beyond our northern gate. Join our pack in glory and slay any goblin who dares come before us!", objectives = "" }
WordHunterWoW_QuestEN[28383] = { title = "Wisps of the Woods", description = "I have toiled long here with the Denmother to spread the teachings of Cenarius and the ways of the wild. She has gained much of my trust, and in return, I have been allowed to introduce the spirits of the forest to her students. The company of wisps is a great honor, as well as a useful blessing.\n\nBut now the goblins descend on us, and seek to steal the wisps for nefarious use. Please, prevent this blasphemy!\n\nCall the wisps back here from the western woods with this blessed branch, and keep them safe.", objectives = "" }
WordHunterWoW_QuestEN[28384] = { title = "Into the Clearing", description = "Irontree Clearing must be razed. We can afford no mercy if we want to prevent the goblins from spreading their destruction through the entire forest.\n\nAlton Redding, my most trusted protector, has already led much of the pack around the enemy line to strike while they are distracted here. Seek him out to the west, overlooking Irontree Cavern.", objectives = "" }
WordHunterWoW_QuestEN[28385] = { title = "Oil and Irony", description = "I plan to use the goblin's greed and pollution against them. Any further despoiling of the land they have already carved here will be worth it to stop their further spread.\n\nDeep within Irontree Cavern, just below us, runs many pipes to pump oil through the ground across the entire clearing. These pipes are attached to a master control pump in the very back of the cavern.\n\nEnter the cavern and sabotage the pump. The ensuing havok will give us opportunity for our final strike.", objectives = "" }
WordHunterWoW_QuestEN[28386] = { title = "Borrowed Bombs", description = "The workers in Irontree Cavern below us have been driven out already. Something else has overtaken the cave.\n\nThis works in our favor. I spotted at least a few of them dropping explosives as they fled... explosives we'll need for the next part of our plan.\n\nEnter the cave and salvage any abandoned bombs you can find. When you're finished with that and the pump, we'll begin our final assault.", objectives = "" }
WordHunterWoW_QuestEN[28387] = { title = "Burnout", description = "Your pump sabotage has caused pipes to break all over camp. The goblins are in a panic over the geysers, and it's about to get worse.\n\nTake the gathered explosives and use them to set the geysers aflame. We're going to do as much damage to the camp as we can, and keep that oil from being used to fuel shredders... or worse, Horde warships.", objectives = "" }
WordHunterWoW_QuestEN[28388] = { title = "Bloody Wages", description = "Sad little cowards... look at them flee in panic!\n\nDon't let it fool you, {name}. The second they've regained their wits, those goblins are going to spend every waking moment chopping this forest to bits and sending the pieces to the Horde's war effort.\n\nDon't give them the chance. Kill the workers throughout Irontree Clearing without mercy... show them their greed has a price!", objectives = "" }
WordHunterWoW_QuestEN[28389] = { title = "Report to the Denmother", description = "With the goblins scattered and their equipment destroyed, they'll either get the message and leave, or be easy pickings if they choose to stay. We've won here.\n\nYou've fought as fiercely as any member of the pack, {name}. Return to the Denmother and let her know of our success. I'll be maintaining my watch.", objectives = "" }
WordHunterWoW_QuestEN[28390] = { title = "Glop, Son of Glop", description = "Glop had a son. In his grave hubris, he named it Glop. And so the line of fungalmancers continues.\n\nI require you to slay this new fungalmancer. Your shaman ally has already returned, and awaits you at his cave in the southwest of Verlok Stand.", objectives = "" }
WordHunterWoW_QuestEN[28391] = { title = "The Restless Brood", description = "Aeosera is restless and stubborn. She scoffs at our dominance, and she needs to be reminded of her place.\n\nI still have the mallet you retrieved for me. Return to the western edge of the Pale Roost and strike the resonating crystal.\n\nI will meet you there and lend what aid I can. Put her back in her place, {class}.", objectives = "" }
WordHunterWoW_QuestEN[28392] = { title = "The Timbermaw Tribe", description = "The Timbermaw furbolg are the last known tribe of uncorrupted furbolg. They huddle on the edge of these lands, ferociously defending their home of Timbermaw Hold.\n\nThough they are proud creatures, they are in need of much assistance. Should you wish to help, follow the road north from here, and seek them out at the entrance to Timbermaw Hold.", objectives = "" }
WordHunterWoW_QuestEN[28393] = { title = "A Dangerous Alliance", description = "SI:7's latest report about Twilight's Hammer and Dark Iron activity worries me, {name}. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We'll be hard-pressed to turn back such a combined force, but if we act before they're ready to strike, we might be able to blunt the attack.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Do not hesitate to take out the elementals supporting his forces.", objectives = "" }
WordHunterWoW_QuestEN[28394] = { title = "The Golem Lord's Creations", description = "The latest SI:7 intelligence on Blackrock Depths is troubling, {name}. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could prove to be a devastating weapon if used against us.\n\nYou must prevent that from happening, {name}. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", objectives = "" }
WordHunterWoW_QuestEN[28397] = { title = "They Will Never Expect This...", description = "They made a mistake by not killing me when they had the chance. Perhaps they thought Orkus would drown. HAH! Now they will pay the price for their carelessness.\n\nYou and I will tear this island apart, {name}. They will never expect this! Once all of their soldiers are dead we will confront the leaders. Be on the lookout for attack plans. If we can get our hands on their plans we will be able to put a stop to their whole invasion!\n\nLet's go, {name}!", objectives = "" }
WordHunterWoW_QuestEN[28398] = { title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain, a magus of renown, plays an important role in leading the Twilight's Hammer forces there. If we could get our hands on his grimoire, I might be able to devise counterspells and other ways of dampening their elemental magics.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", objectives = "" }
WordHunterWoW_QuestEN[28399] = { title = "Stones of Binding", description = "I have it on good authority that SI:7 is concerned about collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We can act on this information, prove our value to the Alliance, and gain something for ourselves at the same time.\n\nThe report mentions that the Twilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", objectives = "" }
WordHunterWoW_QuestEN[28400] = { title = "Heroes of the Horde!", description = "Now to find their battle plans and take out their leaders! Should we succeed there is an orc high warlord who served in the war in Silverpine that is now stationed at Tarren Mill - located in the heart of Hillsbrad. He will grant both of us commendations for this! We will be heroes of the Horde, {name}!\n\nOnward! Together we will defeat the Alliance filth!", objectives = "" }
WordHunterWoW_QuestEN[28401] = { title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", objectives = "" }
WordHunterWoW_QuestEN[28402] = { title = "Schnottz So Fast", description = "I'm nearly ready, {name}.\n\nYour scrolls contained enough information to discern their encryption method. Now all that's left is for me to translate the codes.\n\nI need you to scout out the chamber beneath the Obelisk of the Moon. There are likely to be a few of Schnottz's troops down there that escaped your blast.\n\nYou take care of them and I'll meet you there when I'm finished.", objectives = "" }
WordHunterWoW_QuestEN[28403] = { title = "Bad Datas", description = "There should be two titan communication devices in this chamber.\n\nIf my translations are correct, one is a death trap and the other will accept the codes and activate the obelisk.\n\nLet's hope I get this right.\n\nLet me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[28404] = { title = "I'll Do It By Hand", description = "Yes, this all looks familiar enough.\n\nThanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction.\n\nAs soon as I get started, you can count on that titan construct to try and stop me.\n\nThat's where you come in.\n\nI don't need to remind you of what's riding on this. Take down that guardian!", objectives = "" }
WordHunterWoW_QuestEN[28405] = { title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now SI:7 sends word that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the knowledge of the cult, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", objectives = "" }
WordHunterWoW_QuestEN[28406] = { title = "The Dark Iron Army", description = "Things are getting interesting in Blackrock Mountain, {name}. Our sources report that the Dark Iron dwarves have formed closer ties with Twilight's Hammer and both are preparing for a major offensive.\n\nI've made the contents of the report known to key leaders in Stormwind and I want you to help deal with this emerging Dark Iron threat.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths. Take this poison and apply it to their grain reserves.", objectives = "" }
WordHunterWoW_QuestEN[28407] = { title = "The Bachelorette", description = "Firebeard? Marry my sister!? I swear the world's gone mad, {name}!\n\nStill, maybe Kurdran is right. A nice normal wedding would ease everyone's mind... and maybe cool off Firebeard a little. It was great to actually work together here against the ogres.\n\nRight then! It's all up to Fanny. Something tells me she won't want to be tied down.\n\nFly back to Kirthaven and see if she's game. I'll finish up the nasty business with the ogres here.", objectives = "" }
WordHunterWoW_QuestEN[28408] = { title = "Something Bold", description = "By tradition, Wildhammer brides wear white to show their purity. In addition, they wear a crown of black feathers - to show their CHUTZPAH.\n\nOwl feathers make the boldest statement, and Fanny deserves nothing less. Tawny owls are native to the Highlands. Look for them circling near trees that grow along the cliffs, and take their feathers.\n\nYou'll probably want to kill 'em, first.", objectives = "" }
WordHunterWoW_QuestEN[28409] = { title = "Something Brewed", description = "It would be an insult to celebrate a Wildhammer wedding without drink. Kurdran himself called for a few kegs of rare Thunderbrew Lager to be sent ashore from Highbank, but the caravan can't get through the pass.\n\nFollow the road east of here, around the south side of Thunderstrike Mountain, and catch up with the caravan. Look for a fellow named Hammelhand, and help him get the booze through the pass!", objectives = "" }
WordHunterWoW_QuestEN[28410] = { title = "Something Stolen", description = "Everyone's going to want to dress their best for this, and finery is in short supply in the Highlands.\n\nI understand that those goblin wretches off the coast use the finest silk for repairing their zeppelin air envelopes. A waste!\n\nFind a zeppelin flying back and forth between Dragonmaw Port and the Krazzworks, and liberate some silk from the cargo hold in the lower decks.", objectives = "" }
WordHunterWoW_QuestEN[28411] = { title = "Something Stewed", description = "Finally, we're going to need a feast. And none of that \"finger food\" stuff! This crowd wants meat, and lots of it.\n\nGather up venison from Highland elk and does. Highland worg are good eatin' too - bring back some ribs. We'll show you a feast like you've never had in all the Eastern Kingdoms, friend.", objectives = "" }
WordHunterWoW_QuestEN[28413] = { title = "Words and Music By...", description = "I've written many an epic tune in my lifetime, {name}, but this upcoming wedding deserves a very special ballad. And fast!\n\nShould I write a love song? A lighthearted ditty? A bawdy drinking song?\n\nI could use some help with the lyrics, if you fancy a go at it.\n\nTalk to me and we'll write a song together!", objectives = "" }
WordHunterWoW_QuestEN[28414] = { title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\n<The coach leans in close and whispers in your ear.>\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nNow get out there and make me proud!", objectives = "" }
WordHunterWoW_QuestEN[28415] = { title = "SEVEN! YUP!", description = "We have to take action.  Winky and Gor'tesh were fighting, so I planned this friendship ceremony to help the two of them make up.  Everything was going well, until...\n\nWell, you know the rest.\n\nI even bought drinks!\n\nWinky loves flameflies.  He runs off to chase them most every night.  I'm thinking maybe that's where he went.\n\nYou'll find flameflies to the west and north, wherever you find lava.  Bring me seven of them, and hurry!\n\nGor'tesh might leave next!", objectives = "" }
WordHunterWoW_QuestEN[28416] = { title = "Burning Vengeance", description = "{name}... is that you?  I thought you were dead, with the rest of them!\n\nNo, you were always strong, even back then, even in Redridge.\n\nOur fight's not over, {name}.  They already attacked our homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you can still fight like you did back in the day, then join me.  You can start by heading south, to the Whelping Downs, and slaying their whelpers and their hatchling black dragons.\n\nIt'll be like old times.", objectives = "" }
WordHunterWoW_QuestEN[28417] = { title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", objectives = "" }
WordHunterWoW_QuestEN[28418] = { title = "Burning Vengeance", description = "I am a Blackrock orc by birth.  I spent a large part of my youth inside that mountain.\n\n<Ariok motions towards Blackrock Mountain, to the north.>\n\nBut while I share blood with them, I do not share their outlook.  And I am seeking an ally to assist me in stopping their upcoming attack.\n\nSo prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", objectives = "" }
WordHunterWoW_QuestEN[28419] = { title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My father has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", objectives = "" }
WordHunterWoW_QuestEN[28420] = { title = "A Future Project", description = "According to my father, we'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.", objectives = "" }
WordHunterWoW_QuestEN[28421] = { title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28422] = { title = "The Sand, the Cider, and the Orb", description = "My father is waiting for us to the east.  Before we head out though, we need to gather some more supplies.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", objectives = "" }
WordHunterWoW_QuestEN[28423] = { title = "Warlocks Have the Neatest Stuff", description = "Ariok said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", objectives = "" }
WordHunterWoW_QuestEN[28424] = { title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", objectives = "" }
WordHunterWoW_QuestEN[28425] = { title = "Return to Ariok", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", objectives = "" }
WordHunterWoW_QuestEN[28426] = { title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with my father.\n\nAre you familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few of the Blackrock while we travel?  I'm getting a little restless here in this camp.", objectives = "" }
WordHunterWoW_QuestEN[28427] = { title = "A Needle in a Hellhole", description = "Lok'tar, {class}.  My name is Eitrigg, of the Argent Crusade... formerly of the Warchief's Honor Guard.  Before that, of the Blackrock orcs.\n\nI trust my son has briefed you on our plan.  He hasn't?  That is probably for the better.\n\nThe next part of the plan is going to require a bit of subtlety.  Speak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that you've collected.  He's going to need to size you.\n\nThat's right, {race}: you're going undercover.", objectives = "" }
WordHunterWoW_QuestEN[28428] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28429] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28430] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28431] = { title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", objectives = "" }
WordHunterWoW_QuestEN[28432] = { title = "Into the Black Tooth Hovel", description = "Undercover work is all about swagger.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.  Do whatever he asks of you.\n\n<Eitrigg presses a small mechanical object into your palm.>\n\nPlace this device in your ear.  I will be in touch to give you any special instructions.\n\nGood luck out there, soldier.", objectives = "" }
WordHunterWoW_QuestEN[28433] = { title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping boy for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", objectives = "" }
WordHunterWoW_QuestEN[28434] = { title = "Strategic Cuts", description = "<You hear a buzzing in your ear.>\n\n{name}?  It's Eitrigg.\n\nWe've just received the final bit of information for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", objectives = "" }
WordHunterWoW_QuestEN[28435] = { title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", objectives = "" }
WordHunterWoW_QuestEN[28436] = { title = "Taking the Horn For Ourselves", description = "{name}, it's Eitrigg.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew an attack was imminent, but not this soon!\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", objectives = "" }
WordHunterWoW_QuestEN[28437] = { title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"Big Three\" that run the Blackrock forces here in Burning Steppes.  He leads from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  I will be in touch, should I need anything further.", objectives = "" }
WordHunterWoW_QuestEN[28438] = { title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", objectives = "" }
WordHunterWoW_QuestEN[28439] = { title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", objectives = "" }
WordHunterWoW_QuestEN[28440] = { title = "Abuse of Power", description = "{name}?  Eitrigg here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28441] = { title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to my son and me, here in Chiselgrip.", objectives = "" }
WordHunterWoW_QuestEN[28442] = { title = "Flame Crest", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the northeast, to Flame Crest.\n\nFlame Crest is in the cliffs, past the Ruins of Thaurissan.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, my son Ariok will be joining you on the road.  As will I.", objectives = "" }
WordHunterWoW_QuestEN[28443] = { title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the southeast.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", objectives = "" }
WordHunterWoW_QuestEN[28444] = { title = "Latent Demons of the Land", description = "The lava beds nearby - to the south - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", objectives = "" }
WordHunterWoW_QuestEN[28445] = { title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Eitrigg produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our southeast.", objectives = "" }
WordHunterWoW_QuestEN[28446] = { title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", objectives = "" }
WordHunterWoW_QuestEN[28447] = { title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[28448] = { title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  I've been watching over them, and now we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", objectives = "" }
WordHunterWoW_QuestEN[28449] = { title = "Placing the Pawns", description = "<You hear a buzzing in your ear.>\n\n{name}.  It sounds like you and Ariok have finished with your tasks.  I've also finished mine.\n\nReturn to Flame Crest.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before you kill them.", objectives = "" }
WordHunterWoW_QuestEN[28450] = { title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", objectives = "" }
WordHunterWoW_QuestEN[28451] = { title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the Big Three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", objectives = "" }
WordHunterWoW_QuestEN[28452] = { title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Eitrigg hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", objectives = "" }
WordHunterWoW_QuestEN[28453] = { title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Flame Crest, NOW.", objectives = "" }
WordHunterWoW_QuestEN[28454] = { title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  A sad day... but a day in which the Blackrock orcs will learn a powerful lesson.  Today, our plan comes to fruition.\n\nCome with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", objectives = "" }
WordHunterWoW_QuestEN[28455] = { title = "Glory Amidst Chaos", description = "You and my son are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Topple these corrupt Blackrock orcs once and for all.", objectives = "" }
WordHunterWoW_QuestEN[28456] = { title = "The Spoils of War", description = "While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near the innocent people of Redridge anytime soon.  You and Ariok saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", objectives = "" }
WordHunterWoW_QuestEN[28457] = { title = "A Dangerous Alliance", description = "The Shattered Hand believes that the Dark Iron dwarves and Twilight's Hammer are working together. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We can't allow such a force to depart Blackrock Mountain.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Eliminate the elementals Twilight's Hammer has provided to support his forces.", objectives = "" }
WordHunterWoW_QuestEN[28458] = { title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain is a powerful and influential magus in the Twilight's Hammer delegation. If we could get our hands on his grimoire, I could develop counters for Twilight's Hammer spells and curses.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", objectives = "" }
WordHunterWoW_QuestEN[28459] = { title = "Stones of Binding", description = "The Shattered Hand has discovered increased collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We have an opportunity to strike at our enemies and empower ourselves, {name}.\n\nTwilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", objectives = "" }
WordHunterWoW_QuestEN[28460] = { title = "Threat of the Winterfall", description = "I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have... strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.\n\nThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.\n\nI'd like to continue my studies, so won't you help me?", objectives = "" }
WordHunterWoW_QuestEN[28461] = { title = "The Golem Lord's Creations", description = "The Shattered Hand has discovered some disturbing information in Blackrock Depths. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could be a great advantage for our enemies.\n\nIt is your duty to prevent that from happening. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", objectives = "" }
WordHunterWoW_QuestEN[28463] = { title = "The Dark Iron Army", description = "As a member of the Shattered Hand, you know that it is our job to watch the Horde's enemies. We have discovered that the Dark Iron dwarves and their new allies, Twilight's Hammer, are preparing to attack.\n\nI'm sending you to help deal with this threat before the Dark Iron army marches. Take this poison and apply it to the soldiers' rations of grain in Blackrock Depths.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths.", objectives = "" }
WordHunterWoW_QuestEN[28464] = { title = "Falling to Corruption", description = "The aggression of the Winterfall furbolg has to have its source somewhere. I'd like to get to the bottom of it if I can!\n\nI've seen the furbolg in the camps to the north brewing something in a cauldron. They seemed very protective of it... if whatever they're cooking up is what's causing this, I must examine it myself.\n\nFind that cauldron if it's still there, and bring me back what's inside!", objectives = "" }
WordHunterWoW_QuestEN[28465] = { title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", objectives = "" }
WordHunterWoW_QuestEN[28466] = { title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", objectives = "" }
WordHunterWoW_QuestEN[28467] = { title = "Mystery Goo", description = "The greenish substance inside the cauldron is putrid and viscous.  No matter what it is, it doesn't seem to be good.\n\nIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.", objectives = "" }
WordHunterWoW_QuestEN[28469] = { title = "Winterfall Runners", description = "Very interesting, {name}...\n\nWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.\n\nWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.", objectives = "" }
WordHunterWoW_QuestEN[28470] = { title = "High Chief Winterfall", description = "The Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but if their leader is slain, they may not get any worse.\n\nHead east again, past where you found that cauldron. High Chief Winterfall is here, at the easternmost part of Timbermaw Post.", objectives = "" }
WordHunterWoW_QuestEN[28471] = { title = "The Final Piece", description = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.\n\nBut perhaps Donova will be able to tell you what it says... ", objectives = "" }
WordHunterWoW_QuestEN[28472] = { title = "Words of the High Chief", description = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.\n\nHe's a druid that once worked to help cleanse Felwood with the Emerald Circle, and has since come here to study the nearby ruins.\n\nYou might be able to find him to the east at Lake Kel'theril, where he spends his time recently.", objectives = "" }
WordHunterWoW_QuestEN[28473] = { title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", objectives = "" }
WordHunterWoW_QuestEN[28474] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28475] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28476] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28477] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28478] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "" }
WordHunterWoW_QuestEN[28479] = { title = "The Ruins of Kel'Theril", description = "At this lake, the Crystal of Zin-Malor was stolen by the Highborne. The crystal was a powerful artifact that bent arcane magic in wild and unpredictable ways... but it could only be held by the worthy, and brought doom upon all others.\n\nThe spirits that wander here span generations, each shackled here by Zin-Malor. Some will speak and tell their fates.\n\nShould you wish to learn the fate of Zin-Malor, seek the spirit at the center of the lake...", objectives = "" }
WordHunterWoW_QuestEN[28480] = { title = "Lieutenants of Darkness", description = "The armies of Ramkahen are getting obliterated by Neferset's immortal guardians.\n\nThe only way to defeat them is to slay the Dark Pharaoh of Neferset.\n\nBefore we make our move, however, we're going to need to take care of his lieutenants.\n\nGo behind the battle-lines and slay Scorpion-Lord Namkhare and High Priest Sekhemet.  Only then will we be ready to confront the Dark Pharaoh himself.", objectives = "" }
WordHunterWoW_QuestEN[28482] = { title = "Sullah's Gift", description = "Jonesy tells me you two need to make it up that mountain.\n\nWell, you're not going far with those troopers crawling all over it like ants on a carcass.\n\nSome of my friends were able to confiscate a bit of the enemy's hardware. It should make your journey a bit easier.\n\nMake your way up the ridgeline to the north, and you'll find it waiting for you.\n\nGood luck, you two!", objectives = "" }
WordHunterWoW_QuestEN[28483] = { title = "Bleeding the Enemy", description = "I will not lie to you, {name}.  We face a tremendous challenge ahead of us.\n\nAs you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat.\n\nIt will be a boon to our armies to know that you've dealt a crushing blow to the enemy.", objectives = "" }
WordHunterWoW_QuestEN[28484] = { title = "The Heart of the Matter", description = "The magus has been idle for far too long and an idle magus often leads to poorly thought out schemes. This time I am charged with collecting various beast organs in order to power some type of control rod. I am far too frail to go out hunting beasts - especially yetis!\n\nPerhaps if I were to offer you a reward of some kind you would do it? All I need is for you to head west to the yeti caves and kill yetis. Rip their still beating hearts from their chests and bring them back here.", objectives = "" }
WordHunterWoW_QuestEN[28485] = { title = "Yetimus the Yeti Lord", description = "For years the mountain yeti of this region have been allowed free reign. Our complacency in dealing with the yeti menace has resulted in an aberration! Yetimus, lord of all yetis, has grown to a size and strength that our guard simply cannot handle. We fear that should his appetite lead him near Tarren Mill he would devour us all.\n\nGather a party of suitable adventurers and dispatch the beast. He roams the countryside to the west.\n\nBring me one of his horns and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[28486] = { title = "Salhet's Gambit", description = "Neferset City is too well defended.  The mountain next to it, however, is not.\n\nI've spoken to the ranger captain and he's willing to take a handful of his men and secure the strategic mountaintop.\n\nThere is one catch, {name}.  He agreed, but only if you would spearhead the attack with them.\n\nIt must be a small group, else we'll draw the enemy's attention too soon, but trust me... the rangers of Ramkahen are as tough as they come.  With you by their side we'll surely succeed.", objectives = "" }
WordHunterWoW_QuestEN[28487] = { title = "Humbert's Personal Problems", description = "So this is pretty embarrassing. Where to begin?\n\nWell, you see, Melisara sent me to investigate the yeti menace in the nearby caves, west of here. It was getting late and my armor was weighing heavily on me. I took my gear off and decided to take a stroll. Yes, I, erm, went for a walk. Anyway, when I returned I discovered that my gear had been stolen! It was the yetis. I'm sure of it. They took my pants, sword and helm and ran off into their cave. Get them back for me and I will reward you.", objectives = "" }
WordHunterWoW_QuestEN[28488] = { title = "Beneath the Surface", description = "Among the other precious gemstones hidden deep out of our reach in the Crumbling Depths, there are enormous ruby crystal clusters. They are infused with terrible energy.\n\nIt will not be easy to obtain such a thing, for they are well guarded. But you, you are stubborn and brave. I think this is something you can do.\n\nWithin the Crumbling Depths, look to where the tunnels end abruptly in stone. The clusters are found in those passages when they are to be found at all. Should you find one, return to me.", objectives = "" }
WordHunterWoW_QuestEN[28489] = { title = "Stagwiches", description = "Ever had a stagwich? Me neither. Apparently they're delicious. Now I'm not one for eating, but I am a businessman. If my customers want stagwiches, who am I to argue?\n\nYou're probably asking yourself, \"What does this have to do with me?\" I'll tell you what, {class}, I need stag meat! You get me stag meat from the hill stags of Hillsbrad and I will pay you. Sounds like a pretty good deal, doesn't it?\n\nGet going! Stags are most plentiful to the west.", objectives = "" }
WordHunterWoW_QuestEN[28490] = { title = "Hero's Call: Darkshore!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Priestess Dentaria at Lor'danel in Darkshore.\n\nThe people of Lor'danel need your aid in caring for the survivors of Auberdine's destruction and securing their town against Twilight's Hammer. Speak to Vesprystus, the hippogryph master at Rut'theran Village outside of Darnassus and he'll arrange a flight to Darkshore.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28491] = { title = "Not Fireflies, Flameflies", description = "Most of my fellow residents here at Flame Crest seem to have left at some point.  I guess the Burning Steppes weren't INTERESTING enough for them.\n\nNot me, though.  I'm always finding new reasons to not leave, and the latest happens to be the flameflies that have been appearing lately.\n\nThey appear near lava during the day.  By night, you'll find them almost anywhere.\n\nIf you wouldn't mind collecting some, I might be able to make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[28492] = { title = "Hero's Call: Ashenvale!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Sentinel Shyela at Orendil's Retreat in northwestern Ashenvale.\n\nThe Horde's aggression in Ashenvale cannot be allowed to stand! Your help is needed to repel the invaders and restore the sacred forest. Head south through the Twilight Vale in Darkshore to reach the forest of Ashenvale.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28493] = { title = "Warchief's Command: Ashenvale!", description = "All able bodied members of the Horde are hereby ordered to report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale. Aid in driving the night elves from the forest, so that we may claim its resources for our people!\n\nTo reach the Mor'shan Rampart, you must take the Gold Road north from Crossroads in the Northern Barrens.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28494] = { title = "Warchief's Command: Northern Barrens!", description = "All able-bodied members of the Horde are hereby ordered to report to Kargal Battlescar at Far Watch Post in the Northern Barrens.\n\nYour help is needed to secure the Northern Barrens against the encroaching quilboars and centaurs.\n\nTo reach Far Watch Post, travel west across Durotar's Southfury Watershed and cross the bridge into the Northern Barrens.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28495] = { title = "A Fighting Chance", description = "Blessed be the Light! I need your help!\n\nOn my way into Hillsbrad I noticed several families of adorable little deer. As I went out to pet one of the little fawns a ravenous mountain cat leapt out and killed it. I fled to Tarren Mill and swore to solve the plight of the hill fawn. Now, after many days of tinkering, I have created the hill fawn's salvation!\n\nTake my wand into the fields to the west and use it to empower the wee hill fawns. Once empowered they will be able to fend for themselves!", objectives = "" }
WordHunterWoW_QuestEN[28496] = { title = "Warchief's Command: Azshara!", description = "All able-bodied members of the Horde are hereby ordered to report to Ag'tor Bloodfist at the Orgrimmar Rear Gate in Azshara.\n\nAid in driving back the encroaching Alliance forces and assist in securing Azshara for the glory of the Horde!\n\nDepart Orgrimmar through its northern gate to reach the Orgrimmar Rear Gate in Azshara.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28497] = { title = "Fire From the Sky", description = "Sullah wasn't kidding. That hill is crawling with troopers!\n\nJump on and paint our targets for me.\n\nMake every shot count, {name}! We need to be able to get up there.", objectives = "" }
WordHunterWoW_QuestEN[28498] = { title = "The Secret of Nahom", description = "There is an old story about Nahom.  It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple.\n\nMost believe the tale to be just a legend, but that power... would certainly be useful to us now.\n\nThe vile Neferset have ransacked Atulhet's tomb.  They've taken any artifacts of power and shattered the tablets that encode his memories.\n\nGo to the Tombs of the Precursors to the east and retrieve any fragments that you find.", objectives = "" }
WordHunterWoW_QuestEN[28499] = { title = "Punish the Trespassers", description = "We, priests of Nahom, are guardians of the Tombs of the Precursors.\n\nEver since the Neferset turned to their new masters, they've turned to great heresies.\n\nThey rob the sacred tombs of our forefathers, seeking powerful artifacts and destroying invaluable relics in the process.\n\nGo to the tombs, east of here and punish the tomb-robbers for their transgressions, lest they join their brethren when the Neferset attack on Nahom begins.", objectives = "" }
WordHunterWoW_QuestEN[28500] = { title = "The Cypher of Keset", description = "<Salhet spends some time going over the tablets with the priests around him.>\n\nIt's all right here, {name}.  Atulhet built a potent weapon into this temple and the only way to access it is with the correct cypher.\n\nIt is reportedly hidden in the Keset Pass.  We must hope the Neferset looters haven't gotten to it yet.  That's where Raider Lord Havat is operating and he's the most ruthless of the lot.\n\nBut without reinforcements, this might be our only hope for defending Nahom.", objectives = "" }
WordHunterWoW_QuestEN[28501] = { title = "The Defense of Nahom", description = "The enemy is coming... and in great numbers.\n\nWe will get no further reinforcements.  Let us hope we can stop the Neferset advance.\n\nIf Nahom falls, Ramkahen will follow.\n\nGo outside and speak to one of my sergeants when you're ready.  I will help you command the forces we have to the best of my ability.", objectives = "" }
WordHunterWoW_QuestEN[28502] = { title = "The Bandit Warlord", description = "Our law demands that those behind this attack face proper retribution.\n\nThe band of bandits' ringleader is a man known as Warlord Ihsenn.\n\nYou will find him in the far west of the desert.  Make sure his transgressions do not go unpunished.", objectives = "" }
WordHunterWoW_QuestEN[28503] = { title = "Hero's Call: Thousand Needles!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Caryssia Moonhunter at New Thalanaar at the border between Feralas and Thousand Needles.\n\nThe sentinels need your help to turn back the marauding Grimtotem raiders who dominate the area. To reach New Thalaanar, travel to eastern Feralas, near the border with Thousand Needles.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28504] = { title = "Warchief's Command: Thousand Needles!", description = "All able bodied members of the Horde are hereby ordered to report to Nyse at Mudsprocket. Join the Horde forces fighting against the renegade Grimtotems who dominate the area.\n\nNyse will provide you with transportation to the front lines. She will be waiting for you at Mudsprocket's inn, tucked away in southern Dustwallow Marsh.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28505] = { title = "The Battle for Andorhal", description = "I just got word, lad.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nI hate to see you go, but they've asked for you by name, {name}.  Speak with Guthrum Thunderfist outside.  He'll put you on the first gryphon out to Andorhal.", objectives = "" }
WordHunterWoW_QuestEN[28506] = { title = "March of the Stormpike", description = "These plans you recovered weave an interesting tale, {name}. The Stormpike have been moving their armies from Alterac Valley into the \"four fingers\" of Hillsbrad for over a month. Somehow they have managed to secretly get their installations set up without our forces knowing. Had we not received these plans they would have marched on us in a week's time, annihilating everything in their path.\n\nWith these plans, though, we can turn the tables.\n\nThis is what we must do...", objectives = "" }
WordHunterWoW_QuestEN[28507] = { title = "Hero's Call: Tanaris!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Kelsey Steelspark in Gadgetzan.\n\nThe Alliance needs your help to win concessions from the local baron and access to the area's priceless resources. You can reach Gadgetzan by traveling south from the Shimmering Deep in Thousand Needles.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28508] = { title = "The Battle for Andorhal", description = "I just received the most curious missive.  Curious indeed...\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey've asked for you by name, {name}.  Speak with Kellen Kuhn, the bat handler.  He'll put you on the first bat out to Andorhal.", objectives = "" }
WordHunterWoW_QuestEN[28509] = { title = "Warchief's Command: Tanaris!", description = "All able bodied members of the Horde are hereby ordered to report to Megs Dreadshredder in Gadgetzan. Help the Horde and the Bilgewater Cartel establish a presence in Tanaris before the Alliance does!\n\nYou can reach Gadgetzan in Tanaris by traveling south to the shore from Fizzle and Pozzik's Speedbarge in southeastern Thousand Needles. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28510] = { title = "Warchief's Command: Feralas!", description = "All able bodied members of the Horde are hereby ordered to report to Konu Runetotem at Camp Ataya in Feralas. Help the Horde secure the great forest against the Alliance and the Grimtotems.\n\nYou can reach Camp Ataya by traveling south from Desolace and into Feralas.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28511] = { title = "Hero's Call: Feralas!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Telaron Windflight at Dreamer's Rest in Feralas.\n\nThe Alliance needs your help to overcome our enemies, the Horde and the Grimtotems. You can reach Dreamer's Rest by traveling south from Desolace into Feralas.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28512] = { title = "To the Aid of the Thorium Brotherhood", description = "Dark Iron dwarves may be scheming and mischievous... but they're not all enemies.  I've spoken several times with the dwarves of the Thorium Brotherhood, and they've never been anything but helpful.\n\nAn acquaintance of mine, Jack Rockleg, came to town not long ago, asking if I could join him on an expedition of some sort.  It sounded important.\n\nI'm a little busy, but maybe you wouldn't mind going?  Just travel west, on the road to Searing Gorge.  You'll see him soon after leaving the Badlands.", objectives = "" }
WordHunterWoW_QuestEN[28513] = { title = "Pride of the Highborne", description = "Ten thousand years ago...\n\nThe Highborne lived here in prosperity. We considered ourselves above the common ranks of the other night elves. With our every need met by magic and wealth, we led lives of indulgence and amusement. And greed...\n\nThe spirits you see here are overwhelmed with remorse and regret. Their anguish chains them here. If you wish to learn more of Kel'theril and Zin'malor, free them from their agony.", objectives = "" }
WordHunterWoW_QuestEN[28514] = { title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", objectives = "" }
WordHunterWoW_QuestEN[28515] = { title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", objectives = "" }
WordHunterWoW_QuestEN[28516] = { title = "Centuries of Suffering", description = "I only agreed to even consider cooperating with night elves and the alliance on rumors that the Crystal of Zin-Malor was found here.\n\nThe crystal is a powerful and ancient artifact, whose destruction cursed this land, and whose reassembly has caused little relief.\n\nBut I cannot face the hauntings that dwell here. Mock me if you must, but if you do, try your own hand. Perhaps the placid spirits that sit at the center of the lake will speak with you...", objectives = "" }
WordHunterWoW_QuestEN[28517] = { title = "The Howling Oak", description = "So this is it... our new home. I'm not sure if I'll ever feel like I truly have a home again.\n\nWe mustn't be unappreciative of what the night elves have offered us though. Their race is not one to throw out idle welcomes to just anyone. It is a true testament to faith and generosity that they've taken us in.\n\nGwen and Greymane are in the city proper, at the Howling Oak. You should stop by. Take the portal beneath the tree north of us, then seek out the Howling Oak in the northern portion of the city.", objectives = "" }
WordHunterWoW_QuestEN[28518] = { title = "Legacy of the High Elves", description = "One hundred years ago...\n\nI and a small group of other High Elves traveled here from our homeland, Quel'thalas. We sought the ancient mysteries of Kel'thoril... to find why it was destroyed.\n\nWe found fragments in the ice, shards of the crystal. The Archmage we accompanied did not take long to fall under their sway. In our foolishness, we noticed too late.\n\nHis spirit wanders in the southeast, among those he drove to madness, still clutching the memory of the precious shard...", objectives = "" }
WordHunterWoW_QuestEN[28519] = { title = "Pain of the Blood Elves", description = "One year ago...\n\nThe legend of the Crystal of Zin-Malor reached Silvermoon, and I led a group of the finest warriors and scholars available to this land. We brought ample mana crystals, so none of us would be tempted to taste the crystal itself.\n\nThe crystal did not need our hunger to ruin us. Once in our possession, it warped all but me into wretched beasts.\n\nThe wretched souls still wander, seeking more lives to chain to this lake. Will you give them mercy... or flee to die on safer ground someday?", objectives = "" }
WordHunterWoW_QuestEN[28520] = { title = "The Fall of Neferset City", description = "We are ready to strike now, {name}.\n\nIf we take down Dark Pharaoh Tekahn, the immortal colossi will fall and our armies will be able to march into Neferset City.\n\nSeek him out and engage him without fear.  I will make sure you're not alone when it's time to bring him down.", objectives = "" }
WordHunterWoW_QuestEN[28521] = { title = "Speak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.", objectives = "" }
WordHunterWoW_QuestEN[28522] = { title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, {name}.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nThe Winterfall carry spirit beads, which have clearly failed to protect them against corruption. Bring me 10 of these beads to show you have thinned their ranks.", objectives = "" }
WordHunterWoW_QuestEN[28524] = { title = "Delivery for Donova", description = "Donova Snowden is a kind dwarf who frequents the nearby hot springs. She claims to be studying their magical properties.\n\nShe is a kind person and has good relations with our tribe. As the Winterfall have become more and more aggressive, she has begun researching the cause of their corruption.\n\nI must keep my post here, but I have made a basket of refreshments for her. Please take it to her for me and tell her we await her next visit.", objectives = "" }
WordHunterWoW_QuestEN[28525] = { title = "Hero's Call: Un'Goro Crater!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Williden Marshal at Marshal's Stand.\n\nThe Alliance needs you to provide support to the Marshal Expeditions as they uncover the secrets of Un'Goro Crater's ancient beasts, unique flora, and powerful crystals. You can reach the crater by departing western Tanaris and following the road all the way to Marshal's Stand.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28526] = { title = "Warchief's Command: Un'Goro Crater!", description = "All able bodied members of the Horde are hereby ordered to report Williden Marshal at Marshal's Stand. You are to provide aid to the Marshal Expeditions' personnel as they uncover the secrets of Un'Goro Crater. The Horde may be able to find a use for the unique beasts and crystals populating the crater.\n\nYou can reach Un'Goro Crater by taking the road from western Tanaris down into the crater and toward Marshal's Stand. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28527] = { title = "Warchief's Command: Silithus!", description = "All able-bodied members of the Horde are hereby ordered to report to Windcaller Proudhorn at Cenarion Hold. You are to aid our Cenarion allies in their battle to turn back Twilight's Hammer. Cho'Gall's minions must not be allowed to dominate Silithus!\n\nYou can reach Silithus by taking the northwestern road out of Un'Goro Crater. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28528] = { title = "Hero's Call: Silithus!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Windcaller Proudhorn at Cenarion Hold.\n\nOur Cenarion Circle allies require your assistance to fight back against the Twilight's Hammer onslaught. You can reach Silithus by taking the northwestern road out of the Un'Goro Crater.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28529] = { title = "Writings of the Void", description = "The scrolls are vague and appear to be a piece of a much larger puzzle, but if you are not mistaken, they seem to reveal some of the steps on the path to becoming a demon hunter.\n\nThe dark oaths and rituals necessary for becoming a demon hunter are frowned on by most of the night elves, so this is likely something they would be very interested in keeping quiet.\n\nRanger Glynda Nal'Shea will know what to do with these scrolls.", objectives = "" }
WordHunterWoW_QuestEN[28530] = { title = "Scalding Signs", description = "The cauldron looked like it contained concentrated material. If the Winterfall are diluting this stuff directly in the springs, contamination could build up over time... and then the dilution would be less and less effective.\n\nThe spring to the northeast has boiled over with elementals. I thought it was because of the cataclysm, but their appearance could be a reaction to this.\n\nCould you check them for corruption? Hunt a few and bring me any bits of green foreign material they leave behind.", objectives = "" }
WordHunterWoW_QuestEN[28531] = { title = "Hero's Call: Desolace!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Officer Jankie on the road into Desolace at Tethris Aran.\n\nThe brave soldiers of Nijel's Point are beset by demons and the armies of the Horde, and they need your help. To reach Desolace, travel south on the road from the Charred Vale in the Stonetalon Mountains.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28532] = { title = "Warchief's Command: Stonetalon Mountains!", description = "All able bodied members of the Horde are hereby ordered to report to Blood Guard Aldo Rockrain at Silverwind Refuge in Ashenvale. The Horde forces in Stonetalon need your help to drive back the Alliance invaders and protect our people. The blood guard will direct you to the border of Stonetalon.\n\nTo reach Silverwind Refuge, travel into the heart of Ashenvale and join our forces by the lake.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28533] = { title = "The High Council's Decision", description = "The High Council is ready to decide on the war with the Neferset tribe.", objectives = "" }
WordHunterWoW_QuestEN[28534] = { title = "Descendants of the Highborne", description = "Not long after my death, the greed of my people would lead to their exile. A continent away, they would become Quel'dorei, the High Elves. In Quel'thalas they would bathe in the power of their Sunwell, and forget their legacy of desire and greed.\n\nThese distant descendants returned here, drawn by the hand of fate, doomed to repeat history. Hear their tale now, as I have...", objectives = "" }
WordHunterWoW_QuestEN[28535] = { title = "Descendants of the High Elves", description = "Long after my death, my people would suffer an even greater mistake. The High Elves relied on the Sunwell and its glory. Never imagining a world without it, we would never make preparations to deal with such a fate.\n\nLater, when the Sunwell fell to the forces of the undead, what was left of my descendants would be lost and helpless... and the path they would take in response would change them forever.\n\nThe Sin'dorei, still striving for redemption, would return here as well...", objectives = "" }
WordHunterWoW_QuestEN[28536] = { title = "The Curse of Zin-Malor", description = "You have seen enough. Know that the Crystal of Zin-Malor brings only ruin to all around it.\n\nLeave this place, if you do not wish to join us.", objectives = "" }
WordHunterWoW_QuestEN[28537] = { title = "In Pursuit of Shades", description = "You say it spoke of a master? Of one who holds Zin-Malor?\n\nThis is grave news. You must act, {class}! I saw the shade fly off to the south. Take the path to the upper ruins, and you may be able to climb the frozen waterfall after it!\n\nAnd do not let your guard down... it may be waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[28538] = { title = "Cry of the Banshee", description = "So you are to be our savior? Very well then, I will bond myself with you. Through this bond I will be able to see through your eyes and communicate with you in the field.\n\nAccording to the plans you brought to us, the Stormpike have enlisted the aid of SI:7 at Sofera's Naze, to the north. SI:7 are comprised solely of humans - humans that we are able to use to our benefit.\n\nTake my mirror and travel north. Engage in combat with the SI:7 and bring them near death. Once they are injured, use the mirror.", objectives = "" }
WordHunterWoW_QuestEN[28539] = { title = "Hero's Call: Stonetalon Mountains!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Huntress Jalin at Stardust Spire in Ashenvale.\n\nThe Horde's forces are poised to push into Stonetalon and they must be opposed! You can reach Stardust Spire by traveling to the southern part of Ashenvale Forest, near the border with Stonetalon.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28540] = { title = "Doin' De E'ko Magic", description = "Mau'ari been makin' charms from da spirits of de wilds here for years now. Mau'ari just PLUCK de E'ko right outta de animals, and make charms for de kids, and de adventurers.\n\nOvah to de east, dere be a tall hill surrounded by de shardtooth bears. Up on de hill be Rimepelt, de oldest bear in de woods.\n\nMau'ari need dat bear for her magic. You bring me de bear's big ol' heart.", objectives = "" }
WordHunterWoW_QuestEN[28542] = { title = "Warchief's Command: Felwood!", description = "All able bodied members of the Horde are hereby ordered to report to Tenell Leafrunner at the Emerald Sanctuary in Felwood. The Cenarion Circle requires your help to wrest Felwood from the control of demons and other corrupt creatures!\n\nTo reach the Emerald Sanctuary, travel north from Ashenvale and follow the road until you reach the sanctuary.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28543] = { title = "Hero's Call: Felwood!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Tenell Leafrunner at the Emerald Sanctuary.\n\nHis order requires your help to redeem Felwood from the demonic influences that rule the forest. Head north from Ashenvale and follow the road into Felwood until you reach the Emerald Sanctuary.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28544] = { title = "Hero's Call: Winterspring!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Donova Snowden at Frostfire Hotsprings.\n\nShe requires your help to overcome the threat of the Winterfall furbolg. To reach Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28545] = { title = "Warchief's Command: Winterspring!", description = "All able-bodied members of the Horde are hereby ordered to report to Donova Snowden at Frostfire Hot Springs. Her discoveries about the Winterfall furbolg may be the key to dealing with this threat once and for all.\n\nTo reach the Frostfire Hot Springs in Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28548] = { title = "Warchief's Command: Desolace!", description = "All able bodied members of the Horde are hereby ordered to report to Furien at Tethris Aran in Desolace. The brave Horde warriors of Desolace need your help to beat back the armies of the Alliance and ancient demons.\n\nTo reach Tethris Aran, travel south from the Charred Vale in the Stonetalon Mountains.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28549] = { title = "Warchief's Command: Southern Barrens!", description = "All able bodied members of the Horde are hereby ordered to report to Nura Pathfinder at the High Road in the Southern Barrens. With the recent Alliance victories in the Barrens, our enemies are threatening to cut our supply lines and leave our warriors stranded. We must act!\n\nTo reach the High Road, travel east from Stonetalon Mountains. If necessary, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28550] = { title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Walpole at Stonetalon Pass in the Southern Barrens.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the Southern Barrens from the Stonetalon Mountains by traveling southeast through Greatwood Vale.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28551] = { title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Dockmaster Lewis near Northwatch Hold.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28552] = { title = "Hero's Call: Dustwallow Marsh!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Calia Hastings at Theramore Isle.\n\nYou must aid SI:7's Calia Hastings in uncovering the threats to Theramore, both within the city and beyond its walls. You can reach Theramore Isle by taking the boat from Menethil or traveling across the marsh from the Southern Barrens.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28553] = { title = "Okrilla and the Blasted Lands", description = "I have one final dispatch to deliver to you, {name}.  It comes from Dreadmaul Hold, to the south, in the Blasted Lands.\n\nWarmatron Okrilla is waging battle against the Alliance forces of Nethergarde Keep, and she needs the assistance of a stout {class}.  You immediately sprung to mind.\n\nTravel south into the Blasted Lands, then head west.  Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28554] = { title = "Warchief's Command: Dustwallow Marsh!", description = "All able bodied members of the Horde are hereby ordered to report to Krog at Brackenwall Village. The marsh is overrun with enemies of many kinds and the Alliance forces there are dangerously strong.\n\nYou can travel to Dustwallow Marsh by following the path from the eastern part of the Southern Barrens toward Brackenwall Village. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28555] = { title = "Expel the Envoys", description = "<Not yet implemented.>", objectives = "" }
WordHunterWoW_QuestEN[28556] = { title = "Breaking the Hand", description = "We must break the fingers of the Stormpike if we are to stop their incursion.\n\n<Cromush hands you a small package.>\n\nWithin this package are four high-yield goblin explosives. You are to infiltrate each of the four fingers - Sofera's Naze, Corrahn's Dagger, the Headland and Gavin's Naze - and plant a goblin pocket-nuke at each.\n\nOnce you have done that - as well as all that Melisara asks of you - return to me.", objectives = "" }
WordHunterWoW_QuestEN[28557] = { title = "Warchief's Command: Uldum!", description = "All able-bodied members of the Horde are hereby ordered to report to Adarrah at the Thistleshrub Valley in Tanaris.\n\nAncient texts tell us that Uldum is home to untold riches and treasures beyond compare. Go forth and claim these in the name of the Horde!\n\nYou can reach Adarrah's caravan by traveling to the southwestern part of Tanaris and looking for her in Thistleshrub Valley.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28558] = { title = "Hero's Call: Uldum!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Adarrah at Thistleshrub Valley in Tanaris.\n\nBe one of the first to enter glorious Uldum and claim its treasures in honor of the Alliance!\n\nYou can reach Adarrah's caravan by traveling to the western reaches of Tanaris.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28559] = { title = "Hero's Call: Bloodmyst Isle!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Vorkhan the Elekk Herder at Kessel's Crossing.\n\nThe people of Bloodmyst need your help to deal with treacherous blood elves and dangerous creatures loose on the island. You can reach Kessel's Crossing on Bloodmyst Isle by taking the bridge north from Azuremyst Isle.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28560] = { title = "Warchief's Command: Ghostlands!", description = "All able bodied members of the Horde are hereby ordered to report to Arcanist Vandril at Tranquillien in the Ghostlands.\n\nYour help is needed to turn back the numberless Scourge invaders and secure the help of the Forsaken in fighting our common enemy.\n\nTo reach Tranquillien, follow the road south from Fairbreeze Square and into the Ghostlands.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28561] = { title = "Nahom Must Hold", description = "As soon as we make our move west in order to attack Neferset City, the enemy will strike us from the east, where we'll be weak.\n\nNahom will be the first to fall, and if it does, Ramkahen will soon follow.\n\nA small detachment is there already.\n\nGet a briefing from them.  I want you to make sure that they hold Nahom until I can send more troops there.", objectives = "" }
WordHunterWoW_QuestEN[28562] = { title = "Hero's Call: Westfall!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Horatio Laine at the Jansen Stead.\n\nWestfall has been overrun by beggars and transients, leading to a massive increase in criminal activity. Your help is needed to restore order to the populace. You can reach the Jansen Stead in Westfall by traveling west from Elwynn Forest.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28563] = { title = "Hero's Call: Redridge Mountains!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report Watch Captain Parker at Tower Watch in the Redridge Mountains.\n\nCaptain Parker's forces have come under attack from marauding gnolls and orcs. The people of Lakewood are in peril and your aid is needed to safeguard them. Travel east from the border of Elwynn Forest and into the Three Corners area of Redridge to reach Tower Watch.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28564] = { title = "Hero's Call: Duskwood!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Althea Ebonlocke in Darkshire.\n\nThe commander's watchmen are stretched thin defending against marauding wolves and bands of wild worgen. They cannot hold out for long without your help. You can reach Darkshire in Duskwood by following the road south at the border between Elwynn Forest and the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28565] = { title = "Hero's Call: Wetlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Mountaineer Rharen at Dun Algaz.\n\nIn the wake of the cataclysm's destruction, Wetlands has become overrun with wild beasts, orcish raiders, and savage gnolls! To reach the Wetlands, you must travel north from Loch Modan through the dwarven hold of Dun Algaz.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28566] = { title = "Decimation", description = "<Melisara's image appears before you.>\n\nThe Stormpike forward camp sits atop Corrahn's Dagger, west of Sofera's Naze. You must enter the camp and slaughter every dwarf that you see. They must be taught what it means to fear and there is no finer lesson than absolute decimation.\n\nNo survivors, {name}. Even their captain - especially their captain - must die.\n\nI will be in contact.", objectives = "" }
WordHunterWoW_QuestEN[28567] = { title = "Hero's Call: Loch Modan!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Pilot Hammerfoot at South Gate Outpost.\n\nThe destruction of the Stonewrought Dam and the resurgence of the kobolds and troggs has the mountaineers stretched thin. Reinforcements are desperately needed! Travel east through South Gate Pass from eastern Dun Morogh to reach South Gate Outpost.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28568] = { title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\n Destiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28569] = { title = "The Bogpaddle Bullet", description = "I've heard stories about a road to the Swamp of Sorrows.  Mysterious tales of a meandering mountain pathway that completely bypasses Redridge and poops you right out into Bogpaddle!\n\nIf you run out of things to do, I suppose you'll have to leave.  And we'll all be sad.  When you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride.\n\n<Oralius tilts his head, as if listening to something.>\n\nWinky?  WINKY!  NO!", objectives = "" }
WordHunterWoW_QuestEN[28570] = { title = "The Bogpaddle Bullet", description = "You're quite the {race}, aren't you?  Look at you... you're all grown up already.  And we only just met!\n\nI know how it'll go... soon you'll run out of things to do here at Flame Crest.  You'll promise to come back.  But you never will.\n\nKibler's seen it all before.\n\nWhen you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride on the bullet.\n\nWhat?  Oh, it's just a rocket.  Perfectly safe.", objectives = "" }
WordHunterWoW_QuestEN[28571] = { title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, brother! Destiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28572] = { title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28573] = { title = "Hero's Call: Arathi Highlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Captain Nials at Refuge Pointe.\n\nAncient Stromgarde's honor must be redeemed! Too long have ogres and criminals sullied its streets. Travel north from the Wetlands and cross the Thandol Span to reach Arathi. Follow the road to Refuge Pointe and present yourself to the captain.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28574] = { title = "Warchief's Command: The Hinterlands!", description = "All able bodied members of the Horde are hereby ordered to report to Elder Torntusk at Revantusk Village.\n\nNow that the Wildhammer dwarves have officially thrown in their lot with the Alliance, they have made themselves our enemies. They must be defeated!\n\nTo reach Revanktusk Village, cross into the Hinterlands from the mountain pass in eastern Hillsbrad Foothills and make your way to the eastern coast.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28575] = { title = "Warchief's Command: Western Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Koltira Deathweaver at Andorhal.\n\nThe Alliance forces are advancing into the ruined city of Andorhal, seeking to claim it for themselves. We must counter them before they can gain a foothold there!\n\nCross the Bulwark at the eastern end of Tirisfal Glades and follow the roads southeast to Andorhal and meet up with our forces there.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28576] = { title = "Hero's Call: Western Plaguelands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Thassarian at Andorhal.\n\nOn the heels of our early victories in Andorhal, the Forsaken have decided to launch a counterattack. Your help is needed to beat back the Scourge and Horde and reclaim lost Andorhal.\n\nTo reach Andorhal, travel north through the Hillsbrad Foothills and follow the road beyond Chillwind Camp.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28577] = { title = "Warchief's Command: Eastern Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nCross the Thondroril River at the eastern border of the Western Plaguelands and look for Fiona on the far bank.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28578] = { title = "Hero's Call: Eastern Plaguelands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade needs your help to win back the Eastern Plaguelands from the grasp of the Scourge.\n\nTo reach the Eastern Plaguelands, cross the Thondroril River from the Western Plaguelands and look for Fiona on the eastern bank.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28579] = { title = "Hero's Call: Badlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nYour help is needed to survey the damage done by Deathwing, and the disposition of Horde forces in the Badlands.\n\nGek has agreed to provide transportation to the Badlands via rocket, in exchange for your help. Look for him at Light's Hope Chapel in the Eastern Plaguelands.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28580] = { title = "Warchief's Command: Badlands!", description = "All able bodied members of the Horde are hereby ordered to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nThe Alliance is desperate to gain a foothold in the Badlands. Your duty will be to keep them at bay and learn about the destruction wrought by Deathwing.\n\nGek has agreed to provide transportation to the Badlands by rocket. Meet with him at Light's Hope Chapel.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28581] = { title = "Warchief's Command: Searing Gorge!", description = "All able bodied members of the Horde are hereby ordered to report to Jack Rockleg at Thorium Advance.\n\nThe Shattered Hand reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing for something. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28582] = { title = "Hero's Call: Searing Gorge!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Jack Rockleg at Thorium Advance.\n\nSI:7 reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing to attack. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28583] = { title = "Krazzworks", description = "This new shredder design is tops, {name}. Tops! Next step is to protect my intellectual property. There are patents to file, traders to mark, ceases to desist. Oh, and the bribes!\n\nHere, take this patent application to Captain Krazz at the Krazzworks. He survived the destruction of his zeppelin, so he's probably hungry for new business opportunities.\n\nThe Krazzworks is due north of here, atop a perfectly safe mountain peak. Go ahead, kid. Chop chop!", objectives = "" }
WordHunterWoW_QuestEN[28584] = { title = "Quality Construction", description = "Look here, chief, if it weren't for this bumbly idiot across from me, the Krazzworks would be holding up just fine.\n\nUnfortunately for everyone involved, \"Fancypants\" Rothman here decided to deploy the place on top of a mountain! I mean really, who does that?\n\nSo, we got leaks all over the place due to faulty valves. Think you could take this blast tape and seal 'em up for me?", objectives = "" }
WordHunterWoW_QuestEN[28586] = { title = "Pool Pony Rescue", description = "This jerk across from me is getting all of our people killed!\n\nBrett \"the Bummer\" unpacked the Krazzworks in the wrong place and now it's highly unstable. The explosions from the instability are throwing our laborers off of the platforms and into the water below.\n\nYou don't mind flying down there and rescuing them with some pool ponies, {name}?", objectives = "" }
WordHunterWoW_QuestEN[28587] = { title = "Aid of the Frostwolf", description = "I will study the Stormpike battle plans and prepare for an assault. I need you to go to Alterac Valley and enlist the aid of the Frostwolf Clan: the very clan of our former warchief, Thrall. They will help us battle the Stormpike dwarves! Together, we will crush the invaders and see them driven out of Lordaeron for good!\n\nGo now, {name}. Alterac Valley is northeast of Tarren Mill. Find Voggah Deathgrip and tell him that the Horde requires the aid of the Frostwolf!\n\nLOK'TAR!", objectives = "" }
WordHunterWoW_QuestEN[28588] = { title = "Wildhammer Infestation", description = "While these two idiots argue about who royally messed up here, we've got a full-scale invasion of the Krazzworks taking place!\n\nThose no-good Wildhammer are all over the place. Get out there and clear the Krazzworks of those smelly ale-guzzling pests.", objectives = "" }
WordHunterWoW_QuestEN[28589] = { title = "Everything But the Kitchen Sink", description = "You gotta do something about them Wildhammer Stormtalons. They're tearing us up!\n\nProblem is, we're out of ammo, so we had to improvise. We loaded up my Krazz Cannons with all kinds of stuff: pool ponies, Kaja'Cola cans, food containers, fuelcells, tires... you get the picture.\n\nBasically, everything but the kitchen sink.\n\nThink you're in the mood for some target practice?", objectives = "" }
WordHunterWoW_QuestEN[28590] = { title = "Reprisal", description = "I happen to know some Alliance scum that have somethin' coming to them. And they have something that belongs to us. I've authorized an all out assault on Highbank.\n\nBoard the Skyshredder and join the assault. Patch will fill you in on the details as you arrive.", objectives = "" }
WordHunterWoW_QuestEN[28591] = { title = "Off The Wall", description = "You look like a man who likes some action. Get on one of those turrets and lay waste to their defenses on the wall.\n\nBe quick about it, will you? Before we go up in a big ball of fire preferably.", objectives = "" }
WordHunterWoW_QuestEN[28592] = { title = "Parting Packages", description = "I'm sure Patch has some grand scheme in mind, but this wouldn't be an assault if we didn't leave some explosive presents behind.\n\nGet down there and plant some of these explosives on the boat, in the keep entrance, and in one of those northern towers. That should be enough to leave them reeling.\n\nWe're heading down to the ground as well. Meet us at the eastern tower when you're through.", objectives = "" }
WordHunterWoW_QuestEN[28593] = { title = "Of Utmost Importance", description = "When Garrosh's zeppelin went down, so did the induction samophlange that you recovered for us in Azshara. The Alliance have it somewhere in that keep, and Krazz wants it back.\n\nThe basement of the keep would be my best guess, so start there. When you get your hands on it, bring it back to me near the eastern tower.", objectives = "" }
WordHunterWoW_QuestEN[28594] = { title = "Highbank, Crybank", description = "Get down there and make a mess of those Alliance rabble. Any of'm will do. I just want'm scattered while you're in there after the real target.\n\nFind us near the eastern tower when you're done.", objectives = "" }
WordHunterWoW_QuestEN[28595] = { title = "Krazz Works!", description = "That's it. We're all wrapped up. Let's ship out.\n\nNewt's got some gyrocopters tethered at the top of the tower. Go meet up with her for a quick trip back to Krazzworks. We'll mop up here.", objectives = "" }
WordHunterWoW_QuestEN[28596] = { title = "Welcome to Highbank!", description = "Welcome to the highlands, soldier. You're here just in time.\n\nHorde troops just launched an assault from the air. Step up and do something about it. Clear them out!", objectives = "" }
WordHunterWoW_QuestEN[28597] = { title = "Burnin' at Both Ends", description = "Har! We get to jump right inta the action, {name}. Looks like Highbank has whatcha call a zeppelin problem: that airship is poundin' the crap outta the walls.\n\nListen, I've got me an idear so stupid it's genius. I just need some cannon powder.\n\nCollect as much as you can find around Highbank an' meet me by the trade area!", objectives = "" }
WordHunterWoW_QuestEN[28598] = { title = "Aiming High", description = "Lookie here, {name}. I found the biggest gun in Highbank! We're gonna try a technique handed down ta me by my pappy, from his pappy, from his pappy, shortly before he got blowed up.\n\nIt's called the \"{class}-shot.\"\n\nYou take a {race} {class}, and load him inta a gigantic cannon, and then ya - oh relax. This usually works.\n\nTake these explosives, then wait here next ta me. As soon as that blimpy comes around I'll blast you onto tha deck. Plant the explosives in 'er belly and, oh I dunno, make it up as you go.", objectives = "" }
WordHunterWoW_QuestEN[28599] = { title = "Kurdran's Waitin'", description = "It looks like the attack stopped, {name}. Which is a shame, 'cuz we never got to use the {class}-rocket.\n\nAnyways, Kurdran Wildhammer is up in the top of the keep an' I'm sure he'll be wantin' to gives ya a hero's welcome. Yeh earned it! Go talk to 'im!\n\nI'll move on ahead and scout out the beach.", objectives = "" }
WordHunterWoW_QuestEN[28600] = { title = "Matters of Loyalty", description = "I have no authority over such matters. You must speak to our leader, Drek'Thar. I have already sent word of your arrival to Frostwolf Keep. Drek'Thar will be out to speak with you personally.", objectives = "" }
WordHunterWoW_QuestEN[28601] = { title = "Old Puttery", description = "", objectives = "" }
WordHunterWoW_QuestEN[28602] = { title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nWell, mine was in that wagon full of explosives that you set off.\n\nHow about searching around here and seeing if you can't find some.", objectives = "" }
WordHunterWoW_QuestEN[28603] = { title = "Infiltration", description = "For your next mission I want you to travel west to the Headland and infiltrate the Stormpike training grounds. Though there are hundreds of Stormpike trainees there, one of my banshees will disguise you to look like one of the humans captured earlier, allowing you to walk freely among the enemy.\n\nEnter the Headland and find the Stormpike instructors. Once found, coerce them into attacking you! When they attack, kill them. With their instructors dead, they will be unable to train more soldiers!", objectives = "" }
WordHunterWoW_QuestEN[28604] = { title = "Deception and Trickery", description = "As long as I am by your side the enemy will think of you as one of their own. Your newfound humanity, however, will not allow you to be reckless. If you draw attention to yourself the dwarves will grow suspicious and likely attack!\n\nWith that said, I have a plan. Take this barrel of poisoned water and use it to sate the thirst of the tired Stormpike trainees. Once they drink from it they will become deathly ill, eventually succumbing to the poison.", objectives = "" }
WordHunterWoW_QuestEN[28605] = { title = "Domination", description = "<Melisara's thoughts intermingle with your thoughts.>\n\nThe last task will be an assault against the siege technicians of Gavin's Naze, located west of the Headland. Venture to the final finger and lay waste to the dwarf and gnome engineers that build and fortify the Stormpike machines of war. Be sure to plant Cromush's final pocket-nuke as well.", objectives = "" }
WordHunterWoW_QuestEN[28608] = { title = "The Shadow Grave", description = "I'm pleased to see that you're up and walking around, {name}.  You've held up nicely, especially after being dead for so long!\n\nOthers weren't as lucky.  If you wouldn't mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies.  You'll find both in the Shadow Grave, the building just behind me.\n\nHere, Darnell will join you.  He knows the way.", objectives = "" }
WordHunterWoW_QuestEN[28609] = { title = "Hammer Time", description = "The three of us have been arguing for weeks over whose weapons are superior.\n\nI won't let anyone tell me my maces are second best. Kilram's axes and Seril's swords could never match the pure strength of my craft.\n\nI'm tired of arguing. It's time to show those two I'm right with a demonstration. If you would, dear, head outside and tell Deez Rocksnitch that I need the biggest boulder he can find!", objectives = "" }
WordHunterWoW_QuestEN[28610] = { title = "Rubble Trouble", description = "If you want to get a boulder in there, you can use my own patented Boulder-in-a-Box! Normally I'd just sell you one up front, but I'm fresh out of materials.\n\nEarth elementals have been popping up on the peak directly south of town. They're a good source of rubble. If you bring me back a good amount, I'll pay you for the restock, and I'll throw in a Boulder-in-a-Box absolutely free!", objectives = "" }
WordHunterWoW_QuestEN[28611] = { title = "The Defilers' Ritual", description = "Ah, I can already see more clearly, {name}.\n\nWe are right to be wary of the evil Neferset.  I can already sense that they're behind the forces that corrupt the river.\n\nGo underwater once more and find the Murkdeep Cavern.  You will find the Neferset are performing a foul ritual of corruption.\n\nStop them so the river is cleansed once again.", objectives = "" }
WordHunterWoW_QuestEN[28612] = { title = "Harrison Jones and the Temple of Uldum", description = "After all we've been through, it looks like everything's actually coming together!\n\nWe're just steps away from the coffer... I've researched the codes to reveal it... Schnottz thinks we're dead....\n\nYou know, we might just pull this off after all!", objectives = "" }
WordHunterWoW_QuestEN[28613] = { title = "See You on the Other Side!", description = "Alright, {name}. We've bought ourselves a little breathing room, but there's no time to lose.\n\nFollow me!", objectives = "" }
WordHunterWoW_QuestEN[28614] = { title = "Bearzerker", description = "High Chieftain Winterfall's absence has done little to quell the rage of the Winterfall. In his absence, their greatest warrior has rose to a position of terrible power.\n\nGrolnar the Berserk lurks in the cave at the top of Winterfall Village, gorged on enough corrupt firewater to kill ten lesser furbolgs.\n\nHe has become a bloated and horrible beast! Our warriors have been unable to face him... do you have the strength to defeat him, {class}?", objectives = "" }
WordHunterWoW_QuestEN[28615] = { title = "Turning the Earth", description = "Despite their corruption and madness, the Winterfall barely cling to their shamanic powers. It disturbs me to see the power of the elements used by them to harm my tribe and other innocents.\n\nWe will turn their totems against them! Take my own totem with you into Winterfall Village. Use its powers on the Winterfall's totems from afar, and the fury of the earth will be unleashed on all nearby!\n\nNeedless to say... keep a safe distance!", objectives = "" }
WordHunterWoW_QuestEN[28616] = { title = "Stormpike Apocalypse", description = "Before we continue, let us have a moment of silence for our fallen brother, Orkus, for without him, we would have been destroyed by the Stormpike onslaught. This is for you, brother!\n\n<Cromush takes a knee.>\n\nNow, {name}, do not think that I forgot your part in all of this! That is why you get the honors of detonating the goblin pocket-nukes.\n\nAre you ready? FOR THE HORDE!", objectives = "" }
WordHunterWoW_QuestEN[28617] = { title = "Flower Power", description = "You know how to use the spitters, but did you know that if you use a sunflower you can grow things faster? We'll grow some sunflowers and then we'll plant some spitters to push back Warden Stillwater's crazed monstrosities.\n\nLet's go!", objectives = "" }
WordHunterWoW_QuestEN[28618] = { title = "Boulder Delivery", description = "Here you go, as promised! One Boulder-in-a-Box.\n\nLilith was asking for this, wasn't she? She's my only customer!", objectives = "" }
WordHunterWoW_QuestEN[28619] = { title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28620] = { title = "Eastpoint Tower", description = "Our outpost in the southeast is having some problems. I don't have any details other than... well, let me just read from the latest letter:\n\n\"The orcs have grown petulant. Send help or I will have them beaten with reeds.\"\n\nThat's it. It was sent from our chief psylosopher, Nils Beerot. Yea, I have no idea what that means either. Could you please head to Eastpoint Tower and find out what he needs? I can't take any more of these cryptic letters!\n\nJust head south and then follow the road east.", objectives = "" }
WordHunterWoW_QuestEN[28621] = { title = "Put That Baby in the Cradle!", description = "Och!\n\nYou an' junior took yer sweet time gettin'  'ere, din't ya!?\n\nDrinkin' ale, takin' in the sights, I'll wager.\n\nDon't go breakin' yer arm pattin' yerself on the back now, the real work's just beginnin'!\n\nThere be more ta this ancient artifact than ye know, but in order ta reveal its secrets, we need ta get it to the Cradle of the Ancients!\n\nNow howdya spose we do that?\n\nMaybe junior over there has some bright ideas, eh?", objectives = "" }
WordHunterWoW_QuestEN[28622] = { title = "Three if by Air", description = "I had planned on bringing the coffer back to my lab for study, but it seems Brann here has different ideas.\n\nHe thinks he knows how to put a stop to Deathwing's plans here in Uldum.\n\nMy buddy, Jock, is standing by with the transport, just waiting for our signal.\n\nTake these flares and plant them around the perimeter to let him know that we're ready.", objectives = "" }
WordHunterWoW_QuestEN[28623] = { title = "The Push Westward", description = "Our work is done here, {name}.  Against all odds, we stopped the Neferset advance on Nahom.\n\nLet us join the forces pushing west, lest they take all the glory for themselves.\n\nThey must've reached the outskirts of Neferset City by now.", objectives = "" }
WordHunterWoW_QuestEN[28624] = { title = "Kilram's Boast", description = "Pah! Crude and clumsy is all I see!\n\nYou need more than just strength. My axes are just as strong as Lilith's maces, but so sharp, I can cut through a tree in one chop!\n\nYou heard me, one chop! I'll prove it, too, here in front of everyone. Go ask Deez if he can get a tree in here!", objectives = "" }
WordHunterWoW_QuestEN[28625] = { title = "Chop Chop", description = "I deal in small timber plenty, but full trees? That's a novelty item. Kinda like those boulders.\n\nMaybe you can do me another favor. Just west of town there's a grove of trees overlooking Lake Kel'theril. I don't know if it's the spooks there, or all that elf magic junk strewn around the place, but we've been getting treants and lashers wandering around there recently.\n\nThey're making it a real pain to chop wood over there, so why don't you chop some of them? Bring the wood from the treants back here.", objectives = "" }
WordHunterWoW_QuestEN[28626] = { title = "Tree Delivery", description = "Here you go, one instant Super-Gro Insta-Tree made with 80% natural ingredients!\n\nNo roots, no muss, no fuss. Just give it to Kilram and make sure he stands the heck back when he uses it.", objectives = "" }
WordHunterWoW_QuestEN[28627] = { title = "Seril's Boast", description = "Brutes and amateurs.\n\nIt doesn't matter how sharp or heavy your weapon is if all it's good for is hacking like an ogre. I could go on and on about finesse and speed and balance and control... but it's easier to one-up these fools.\n\nTell Deez we've got one more order for him. I need a block of ice.", objectives = "" }
WordHunterWoW_QuestEN[28628] = { title = "Ice Delivery", description = "Alright, one high-quality, pure grade Instant Ice Block!\n\nI tried selling these to people for protection for a while. Y'know, like that trick you see mages pull? Couldn't figure out the whole \"breathing\" thing, though.", objectives = "" }
WordHunterWoW_QuestEN[28629] = { title = "Are We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the Ice Thistle yeti. There's plenty of them in the Ice Thistle Hills to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[28630] = { title = "Echo Three", description = "A lot of goblins have been going missing out there in Ice Thistle Hills. I was almost one of them!\n\nI had the idea to set up a sensor to tell us when the yeti were getting close to Everlook. Of course, it's not working either. There's yeti all over the hills and I haven't heard a peep from it.\n\nWould you mind checking on it for me? It might still be fixable. Echo Three's set up to the southeast on the edge of Ice Thistle Hills. Don't ask what happened to Echo One and Two.", objectives = "" }
WordHunterWoW_QuestEN[28631] = { title = "The Perfect Horns", description = "I can't make a yeti without horns!\n\nI've been looking for what seems like forever for the perfect set of horns... and no horn I find is good enough! But just the other day I saw the biggest yeti in Winterspring.\n\nI named him Icewhomp. His horns are the ones I've been looking for! He lurks all the way in the back of the cave along the eastern ridge of Ice Thistle Hills.\n\nBring me his horns... but be sure to check on Echo Three along the way!", objectives = "" }
WordHunterWoW_QuestEN[28632] = { title = "Fresh From The Hills", description = "Ice this time? Hoo boy, sure. I've got good news and bad news for you.\n\nThe good news is there's a bunch of pure solid ice over in the Ice Thistle Hills cavern, straight east from Everlook. The bad news is there's also a bunch of vicious yetis in there.\n\nBut if you can handle the yeti, hey, piece of cake! Just walk right up to the bigger chunks and crack 'em open with your weapon. Bring it all back to me and I'll do my thing.", objectives = "" }
WordHunterWoW_QuestEN[28633] = { title = "The Coffer of Promise", description = "I'm not quite certain what ta expect 'ere, so stay on yer toes, eh?\n\nThese codes should reveal the coffer's true purpose, and present us with the tools to thwart Deathwing's efforts in Uldum fer good!\n\nStand back!", objectives = "" }
WordHunterWoW_QuestEN[28634] = { title = "Extinction", description = "Owlbeasts... Soulless, feathered monstrosities sent from the darkest depths of the Twisting Nether to prey upon the weak.\n\n<Nils points to the woods surrounding Eastpoint Tower.>\n\nThey surround us on all sides and they are planning an attack - I can sense it. You must stop them before they can organize.\n\nI want you to head into the forest and kill every owlbeast that you see. NONE SHOULD SURVIVE!", objectives = "" }
WordHunterWoW_QuestEN[28635] = { title = "A Haunting in Hillsbrad", description = "The battle over Dun Garok was the bloodiest of all the Hillsbrad battles. The dwarves, outnumbered ten-to-one, fought until the bitter end. Every last one of 'em died in defense of that piece of land.\n\nNow I hear claims that the place is haunted. Nobody wants to go near it! Unfortunately I have orders to prepare Dun Garok for habitation.\n\nCould you do me a favor and go to Dun Garok and search for evidence of a haunting? It's far to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[28636] = { title = "Silence of the Dwarves", description = "The spirits of my soldiers haunt this fort now, lad. Their souls are now bound to this place. Even in death they continue to fight for it. 'Tis sad.\n\nPut 'em out o' their misery and perhaps ye shall have the spoils of yer people's victory.", objectives = "" }
WordHunterWoW_QuestEN[28637] = { title = "A Taste for Bear", description = "Have you ever had the luxury of trying bear meat? I never had the chance to try it in Gilneas, but the bears here are simply exquisite.\n\nThe shardtooth bears that roam just to the south are well-marbled with fat from the cold here. I've been hunting them myself, and it's quite a lark, but I much prefer eating them!\n\nI recommend you try your hand at the hunt. Stick to the white-pelted Shardtooth bears, and the Captain will go to field to bring back any you kill.", objectives = "" }
WordHunterWoW_QuestEN[28638] = { title = "The Owls Have It", description = "I've been eatin' owls my whole life. Owls is good eatin', and my friend Jez agrees. I was the first one that told him to sell owl!\n\nMister fancy-pants worgen here says bears taste better, but don't pay him no mind. You should go hunt yourself some owl. There's plenty of 'em wandering just south of here. Stick to the gray ones for now, an' buzz me on the little talky-thing Jez gave you when you've racked up a few.", objectives = "" }
WordHunterWoW_QuestEN[28639] = { title = "Ursius", description = "I've heard it said that you are what you eat. I don't know if I believe that, but if it's true... I'd prefer to eat the strongest creature that I can find.\n\nUrsius is the largest bear in Winterspring. He eats first when his pack of shardtooth brings down a chimaera or an owlbear. He claims the most comfortable cave in the shardtooth-held lands. And he has... considerable influence with the shardtooth females.\n\nHe is my kind of bear.\n\nI want to eat him.\n\nHis cave is near the maulers. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[28640] = { title = "Fresh Frostsabers", description = "Doesn't that smell great? My smoked meats get top dollar, and nobody else provides the exotic flavors I've got out here in the hills. And it's efficient; you just do the hunting for a small fee, and my other fine friends drag the beasts back here for skinnin' and smokin'!\n\nI've got the market cornered on Frostsaber meat right now. Absolutely delicious stuff, makes great sausages. Head out and hunt those cats just west of here, and we'll call that a start!", objectives = "" }
WordHunterWoW_QuestEN[28641] = { title = "Pride of the Dinner Table", description = "Alright kid, time to head out further into the field!\n\nThis haul's nice and good, but further to the west you'll find much bigger kitties. The pride watchers and huntresses have a lot more muscle on them, and it makes AMAZING burger patties. They sell like crazy!\n\nGimme a ping when you've cleared house and we'll see about you going after the main course.", objectives = "" }
WordHunterWoW_QuestEN[28643] = { title = "The Durnholde Challenge: Zephyrus", description = "Durnholde Keep has always been a place of strife. For years the humans used it as an internment camp and prison for the orcs. After that it was taken over by the Syndicate. Now? The Dark Lady captured and placed powerful elementals within its walls. She charged me with administering \"The Durnholde Challenge.\" Any that can defeat all of the elementals will earn a grand prize! Take this guide and face your first challenge: Zephyrus!\n\nDurnholde is located just northeast of us.", objectives = "" }
WordHunterWoW_QuestEN[28644] = { title = "The Durnholde Challenge: Teracula", description = "According to the guide, Teracula is your next challenge. It roams the path just outside of Zephyrus' lair.", objectives = "" }
WordHunterWoW_QuestEN[28645] = { title = "The Durnholde Challenge: Bloodvenom", description = "According to the guide, Bloodvenom is your next challenge. The fearsome elemental can be found on the lower level of Durnholde Keep, near the western prisons.", objectives = "" }
WordHunterWoW_QuestEN[28646] = { title = "The Durnholde Challenge: Infernus", description = "According to the guide, Infernus is your next challenge. This being, made of molten lava and raging fire, can be found on the lower level of Durnholde Keep, near the eastern prisons.", objectives = "" }
WordHunterWoW_QuestEN[28647] = { title = "The Durnholde Challenge: D-1000", description = "Imprisoned in the old Durnholde Keep arena is a being comprised of pure mercury. The Forsaken have dubbed it the D-1000. Kill the D-1000 and claim your prize!", objectives = "" }
WordHunterWoW_QuestEN[28649] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty worgen in there that I think you'll take great pleasure in executing.", objectives = "" }
WordHunterWoW_QuestEN[28650] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty goblin in there that I think you'll take great pleasure in executing.", objectives = "" }
WordHunterWoW_QuestEN[28651] = { title = "Novice Elreth", description = "Why don't you go speak with my novice, Elreth?  She serves me, and will have some tasks to which you can apply your new abilities.", objectives = "" }
WordHunterWoW_QuestEN[28652] = { title = "Caretaker Caice", description = "I am done with you.  There are, however, others who can use your aid.\n\nCaretaker Caice, standing on that stump behind me, can probably give you another assignment.  You should speak with him now.", objectives = "" }
WordHunterWoW_QuestEN[28653] = { title = "Shadow Priest Sarvis", description = "Are you still here, {name}?  You know, I'm only a deathguard.  I don't have many tasks I can hand out to passers-by like you.\n\nI'd recommend that you talk to Shadow Priest Sarvis.  I remember, he helped me get on my feet after I was plucked out of that tomb.  I'm sure he'll do the same for you.\n\nYou'll find him just inside the chapel, here on the west side of town.", objectives = "" }
WordHunterWoW_QuestEN[28654] = { title = "The Heart of the Matter", description = "Well, laddie, half of me wishes I could stick around a while and take in the sights with ye.\n\nI've seen some mighty amazin' things in my day, but this here takes the cake.\n\nSadly, I have a fair bit o' research ta do on these discs before I make my way into the Halls of Origination.\n\nYou seem ta be worth your salt, perhaps ye'd like ta tag along and see how a REAL archaeologist works, eh?", objectives = "" }
WordHunterWoW_QuestEN[28655] = { title = "Wild, Wild, Wildhammer Wedding", description = "We are ready to begin, {name}!\n\nBut I have it on good authority that the Twilight's Hammer may try to disrupt the ceremony, so as to demoralize and destroy the Wildhammer. Things could get dangerous!\n\nFor this reason, I will be performing the ceremony myself, so that I can keep the bride and groom close to me. Sound like a plan? Good!\n\nSince her father is dead and her brother the best man, Fanny has asked that you walk her down the aisle. What an honor! Talk to me when you're ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[28656] = { title = "Strange Life Forces", description = "When this creature died, some sort of energy was released from its body. The energy was passed on to you, and now you feel somewhat stronger.\n\nAccording to Winterspring locals, Witch Doctor Mau'ari at the Snowden Chalet is an expert in the wildlife of the area. She might know something about this mysterious energy.", objectives = "" }
WordHunterWoW_QuestEN[28657] = { title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", objectives = "" }
WordHunterWoW_QuestEN[28658] = { title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[28659] = { title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the Alliance filth but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any Alliance that you find.\n\nYou know what they say, the only good Alliance is a dead Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28660] = { title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed tol barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28661] = { title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", objectives = "" }
WordHunterWoW_QuestEN[28662] = { title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", objectives = "" }
WordHunterWoW_QuestEN[28663] = { title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Alliance we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28664] = { title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", objectives = "" }
WordHunterWoW_QuestEN[28665] = { title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", objectives = "" }
WordHunterWoW_QuestEN[28666] = { title = "Hero's Call: Burning Steppes!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to John J. Keeshan at Flamestar Post.\n\nYour aid is urgently needed to put an end to the Blackrock orc menace!\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Look for Flamestar Post on the far side of the mountain.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28667] = { title = "Warchief's Command: Burning Steppes!", description = "All able bodied members of the Horde are hereby ordered to report to Ariok at Flamestar Post.\n\nHonored Eitrigg's son, Ariok, needs your assistance to halt the blind aggression of the Blackrock orcs before they invade the neighboring lands.\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Flamestar Post will be south of the mountain.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28668] = { title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28669] = { title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", objectives = "" }
WordHunterWoW_QuestEN[28670] = { title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", objectives = "" }
WordHunterWoW_QuestEN[28671] = { title = "Warchief's Command: Blasted Lands!", description = "All able bodied members of the Horde are hereby ordered to report to Okrilla at Dreadmaul Hold.\n\nOkrilla, commander of the Horde forces at Dreadmaul Hold, requires your help to secure the outpost against rebellious ogres and the forces of the Alliance.\n\nTravel to Dreadmaul Hold by taking the road south from the Swamp of Sorrows.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28672] = { title = "The Executor In the Field", description = "I can keep you busy here in town all week... but you seem to be more the fighting type.\n\n<Elreth looks you over and nods.>\n\nYes, you'll do just fine.  I'd like you to go talk to Executor Arren.  Follow the path north, out of Deathknell.  You'll find him not far past the barricades.", objectives = "" }
WordHunterWoW_QuestEN[28673] = { title = "Hero's Call: Blasted Lands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Quartermaster Lungertz at Nethergarde Keep.\n\nNethergarde's garrison urgently needs your help to stem the Horde advance into the Blasted Lands! Travel south from the Swamp of Sorrows and follow the road east to reach Nethergarde Keep.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28674] = { title = "Starfall Village", description = "You've been pretty busy around here. If you're still eager to do good deeds, or just get paid, I've got something you might be interested in.\n\nStarfall Village is just northwest of Everlook. The night elves there recently suffered a pretty nasty bug infestation, and they're asking for any help they can get.\n\nA few goblins from here already went there to start exterminating, but I'm sure there's room for more. Talk to Wynd Nightchaser, he'll fill you in.", objectives = "" }
WordHunterWoW_QuestEN[28675] = { title = "Hero's Call: Swamp of Sorrows!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Trade Baron Silversnap at Bogpaddle.\n\nThe Alliance forces urgently needs the munitions provided by the baron! You must do whatever is necessary to convince the baron to keep selling our forces supplies at reasonable prices.\n\nTo get to the swamp, follow the road from the southeastern Burning Steppes through the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28676] = { title = "Exterminators at Work", description = "The infestation of our barrow den occured nearly overnight. Vicious creatures never before seen in these lands swarmed the tunnels, hatching from unseen eggs.\n\nWith the few of us here, it was all we could do to keep them from spreading outside the den. We were forced to hire goblins from Everlook that claimed expertise in extermination, but they have not yet been successful.\n\nIf you wish to assist them, enter the barrow den to the west of this lodge and speak with Rinno Curtainfire.", objectives = "" }
WordHunterWoW_QuestEN[28677] = { title = "Warchief's Command: Swamp of Sorrows!", description = "All able bodied members of the Horde are hereby ordered to report to Trade Baron Silversnap at Bogpaddle.\n\nPersuade the trade baron to continue supplying our warriors with the weapons and munitions they require, no matter what it takes!\n\nTravel to the Swamp of Sorrows by following the road from the southeastern Burning Steppes through the Redridge Mountains and meet the trade baron at his seaside resort.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28678] = { title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", objectives = "" }
WordHunterWoW_QuestEN[28679] = { title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for alliance, we have been getting reports of them ambushing the beach lately.", objectives = "" }
WordHunterWoW_QuestEN[28680] = { title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", objectives = "" }
WordHunterWoW_QuestEN[28681] = { title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", objectives = "" }
WordHunterWoW_QuestEN[28682] = { title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", objectives = "" }
WordHunterWoW_QuestEN[28683] = { title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Alliance troops nearby earlier in the week.", objectives = "" }
WordHunterWoW_QuestEN[28684] = { title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just north of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", objectives = "" }
WordHunterWoW_QuestEN[28685] = { title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another Alliance attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", objectives = "" }
WordHunterWoW_QuestEN[28686] = { title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", objectives = "" }
WordHunterWoW_QuestEN[28687] = { title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", objectives = "" }
WordHunterWoW_QuestEN[28688] = { title = "Warchief's Command: Northern Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Commander Aggro'gosh at Grom'gol Base Camp. The commander requires your aid to keep the supply routes open and free of interference from the local inhabitants and the troublesome Alliance.\n\nTo reach Grom'gol, you can take the zeppelin from Orgrimmar's eastern zeppelin tower or the one near Undercity.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28689] = { title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", objectives = "" }
WordHunterWoW_QuestEN[28690] = { title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", objectives = "" }
WordHunterWoW_QuestEN[28691] = { title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in Ragefire Chasm.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", objectives = "" }
WordHunterWoW_QuestEN[28692] = { title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", objectives = "" }
WordHunterWoW_QuestEN[28693] = { title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless soldiers in the area.  Can you head over there and clear them out?", objectives = "" }
WordHunterWoW_QuestEN[28694] = { title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", objectives = "" }
WordHunterWoW_QuestEN[28695] = { title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of dirty Alliance all around the area.", objectives = "" }
WordHunterWoW_QuestEN[28696] = { title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead down there and see what you can do.  Report back to me on your progress.", objectives = "" }
WordHunterWoW_QuestEN[28697] = { title = "Ghostbuster", description = "See that hill with the towers to the northeast?  That's Largo's Overlook and it's not a fun place to set up camp next to.  We have been dealing with those spirits and spectres ever since we setup camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28698] = { title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for Alliance too.", objectives = "" }
WordHunterWoW_QuestEN[28699] = { title = "Hero's Call: Northern Stranglethorn!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Doren at the Rebel Camp.\n\nYears after Colonel Kurzen's treachery against Stormwind, the truth of what happened remains a mystery. Aid the survivors in learning what became of the colonel. Travel south from Duskwood and follow the road west after crossing into the jungle to reach the Rebel Camp.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28700] = { title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", objectives = "" }
WordHunterWoW_QuestEN[28701] = { title = "Out of Harm's Way", description = "Luckily, when the infestation occured, no druids were slumbering in the western barrow den. It is still a sacred site to us, however, and its depths hold blessed relics kept there undisturbed for ages.\n\nWhile I am somewhat trusting of the goblin exterminators, I am also... familiar with the habits of their race. Please retrieve any relics you can find in the barrow den and bring them back to me so they are not damaged. They are within urns, nestled in the small alcoves throughout the den.", objectives = "" }
WordHunterWoW_QuestEN[28702] = { title = "Hero's Call: The Cape of Stranglethorn!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Bronwyn Hewstrike at the Explorers' League Digsite.\n\nThe Explorers' League expedition needs your help to safeguard its site and findings from marauding ogres. Travel south from Northern Stranglethorn Vale and follow the road to the Explorers' League Digsite.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28703] = { title = "Step Into My Barrow", description = "I've still got no clue where all these bugs came from. My best guess is the cataclysm stirred up some underground nests we never knew about.\n\nNo use getting distracted with that when they need killing, though!", objectives = "" }
WordHunterWoW_QuestEN[28704] = { title = "Warchief's Command: The Cape of Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Sassy Hardwrench at Hardwrench Hideaway. She requires your help to deal with the pirates and naga who have overrun the jungle.\n\nTravel to Hardwrench Hideaway by heading south from Northern Stranglethorn and looking for the town southwest of the Gurubashi Arena.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28705] = { title = "Warchief's Command: Outland!", description = "All able bodied members of the Horde are hereby ordered to report to Lieutenant General Orion at the Stair of Destiny.\n\nYour skills are needed to fight the Burning Legion's presence on the shattered remnants of Outland.\n\nGo to the portal room in Orgrimmar's front gate and talk to the Thrallmar Mage to travel to the Blasted Lands, then walk through the Dark Portal to arrive at the Stair of Destiny.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28706] = { title = "Spray it Forward", description = "My fellow siblings are already further down in the den trying to deal with these bugs, and they're starting to get overwhelmed. I say it's time to gas the place.\n\nTake these fumigators. Don't go setting them off yourself; it takes a highly trained professional, and proper timing. Just find my sisters and pass them out.\n\nRemma should be positioned closest to the entrance. Head down the corridor and  keep to your right once you go down the ramp.", objectives = "" }
WordHunterWoW_QuestEN[28707] = { title = "Spray it Again", description = "I'm gonna start setting this up.\n\nNext one goes to Marcy, further down the den. Head down this corridor here and look for her in the next main chamber.", objectives = "" }
WordHunterWoW_QuestEN[28708] = { title = "Hero's Call: Outland!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Duron in Hellfire Peninsula.\n\nThe expeditionary forces require your help to overcome the demonic armies of the Burning Legion! Talk to the Honor Hold Mage in the tall tower in the Mage District to travel to Blasted Lands, then walk through the Dark Portal to arrive at the Stair of Destiny.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28709] = { title = "Hero's Call: Borean Tundra!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.\n\nThe Valiance Expedition needs your help to keep the forces of the Scourge under control and safeguard civilized lands! Make your way to the Stormwind Docks and take the ship north to Valiance Keep.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28710] = { title = "Spray it One More Time", description = "You'd think Rinno could have sent more than a single {race} down here to give us a hand! That freeloader...\n\nI'm gonna set this up. Head north from this room through the corridor and look for Sana. She's probably gotten herself lost in the last chamber, so check the side passages once you get there.", objectives = "" }
WordHunterWoW_QuestEN[28711] = { title = "Warchief's Command: Borean Tundra!", description = "All able bodied members of the Horde are hereby ordered to report to the Warsong Recruitment Officer at Warsong Hold.\n\nThe Warsong Offensive needs your help to overcome the continued threat from the undead Scourge.\n\nTake the zeppelin to Warsong Hold from Orgrimmar's western zeppelin tower and present yourself to the recruitment officer.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28712] = { title = "Enter the Dragon Queen", description = "Hello, {race}. I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy.\n\nIt saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed.\n\nI have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.", objectives = "" }
WordHunterWoW_QuestEN[28713] = { title = "The Balance of Nature", description = "Greetings, {name}. I am Ilthalaine. My purpose in Shadowglen is to train young {class}s like you and to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled.\n\nJourney forth, young {class}, and thin saber populations so that nature's harmony will be preserved.", objectives = "" }
WordHunterWoW_QuestEN[28714] = { title = "Fel Moss Corruption", description = "You seem to know what you're doing. Perhaps I can task you with something a little more important.\n\nAs you may well know, the corruption in Teldrassil was supposedly wiped away. Yet something lingers. The creatures have not calmed and all manner of problems still plague us.\n\nI need you to deal with the grellkin that have gathered to the west, and while you're there, I want you to search them for fel moss. This will help me determine from where this continuing corruption stems.", objectives = "" }
WordHunterWoW_QuestEN[28715] = { title = "Demonic Thieves", description = "Vicious little grell! They've been stealing from our foodstores again.\n\nIf you wouldn't mind lending a hand, they are sure to have my stolen bags within their camps to the west. I would be glad to reward you if you can bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[28716] = { title = "Hero's Call: Twilight Highlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to the throne room in Stormwind Keep.\n\nKing Wrynn requires a trustworthy and proven hero for a mission of the utmost importance.\n\nStormwind Keep can be found in the eastern portion of Stormwind City.\n\nAnyone willing may report to Grand Admiral Jes-Tereth for briefing. For the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[28717] = { title = "Warchief's Command: Twilight Highlands!", description = "All able-bodied members of the Horde are hereby ordered to report to High Overlord Saurfang in Grommash Hold.\n\nHigh Overlord Saurfang requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight's Hammer.\n\nMeet with him in Grommash Hold at the center of Orgrimmar's Valley of Strength.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28718] = { title = "Where There's Smoke, There's Delicious Meat", description = "Say there, {class}... do you like meat?  Even better, do you like money?\n\nI got a second cousin who's making a killing in the frozen meats business.  He's set up a smoking pit up north, and he's looking for help hunting all the dangerous beasties that always tend to taste so good.\n\nCarnivores pay well, friend.  I'm too heavily invested here in this barrow den - what was I thinking? - so I might as well pass the tip on to a helpful {race} like yourself.\n\nHis name's Jez.  Head northeast, and look for the smoke!", objectives = "" }
WordHunterWoW_QuestEN[28719] = { title = "A Little Gamy", description = "Many find the meat of the Shardtooth bears to be too gamy for their taste. I disagree, though I'm not one to judge the tastes of others.\n\nThe Shardtooth Maulers, however - their brown-furred cousins, to the south - have much more tender flesh, particularly in their paws. And I've heard that the snout is also considered a delicacy.\n\nContinue your hunt, {name}. Let's see if you can bag those maulers for ol' Francis.", objectives = "" }
WordHunterWoW_QuestEN[28721] = { title = "Walk A Mile In Their Shoes", description = "We have sent at least 3 different recon groups to investigate Farson Hold in the last few weeks.  Sadly, not one of them has returned back with any info.\n\nAt this point, all we can hope is that they are being held alive as prisoners.  I need you to infiltrate the keep and help get our soldiers back.  This won't be easy {name}, but if anyone can help us, it's you.", objectives = "" }
WordHunterWoW_QuestEN[28722] = { title = "Yetiphobia", description = "It's all ready, {name}!\n\nNow, I told my friend Legacki that I have a surprise for her. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you'll get the honor of using it to surprise her. She's just on the other side of Everlook, near the inn.\n\nGo up to her and turn the yeti on... I'll be watching from here!", objectives = "" }
WordHunterWoW_QuestEN[28723] = { title = "Priestess of the Moon", description = "Perhaps you'd be willing to aid us in further pursuing the corruption haunting Shadowglen.\n\nDentaria Silverglade, Priestess of the Moon, has offered to aid us. You should find her between the two pools just north of our great tree. Circle around the tree to reach her and offer her any help that you can, young {class}.", objectives = "" }
WordHunterWoW_QuestEN[28724] = { title = "Iverron's Antidote", description = "Our friend Iverron has fallen to poison from the nearby webwood spiders. I can tend to him to keep his state from deteriorating, but I need someone to gather an ingredient to prepare him an antidote.\n\nAll around the ponds you should find Moonpetal Lilies. These flowers have great healing properties, and I can use them with the ingredients I already have to restore Iverron to better health.\n\nWould you gather them for me?  There should be many just in sight of here, near the water's edge.", objectives = "" }
WordHunterWoW_QuestEN[28725] = { title = "The Woodland Protector", description = "I must ask something more dangerous of you. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella, has returned to Shadowglen again.\n\nThe dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella in the Shadowthread cave to the north. It is dangerous, but we will be prepared with this antidote just in case.", objectives = "" }
WordHunterWoW_QuestEN[28726] = { title = "Webwood Corruption", description = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely.  Something foul lingers.\n\nThese spiders suffer much more deeply from the corruption than the other nearby wildlife. They are becoming a danger to your people and a danger to the forest. We must thin their numbers, but more importantly, we need to find the source of the corruption that plagues them.\n\nI will come with you and aid you in this. ", objectives = "" }
WordHunterWoW_QuestEN[28727] = { title = "Vile Touch", description = "If these spiders are born with corruption in their veins, then their broodmother must be at the root of this evil.\n\nLet us make our way to the far north end of the cave and seek out Githyiss the Vile. The answers we seek lie with her.", objectives = "" }
WordHunterWoW_QuestEN[28728] = { title = "Signs of Things to Come", description = "I will pursue the trail of the Gnarlpine and track this corruption to its source. If you ever encounter Athridas Bearmantle in Dolanaar, he knows intimately of the problems that plague this forest, and he can direct you on how to help further.\n\nI'm sure we will meet again with time. Perhaps you can aid me in dealing with the source of this corruption once I locate it. For now, I will take you back to Dentaria so that you may finish your training. Thank you for all that you have done, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28729] = { title = "Teldrassil: Crown of Azeroth", description = "As part of a ritual to complete your training here in Shadowglen, you must learn about our recent history.\n\nThere is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.\n\nWhen you are done there, bring the water back to me, and I will direct you further.", objectives = "" }
WordHunterWoW_QuestEN[28730] = { title = "Precious Waters", description = "Tenaron Stormgrip oversees all that happens in this glade. He presides at the top of Aldrassil.\n\nIf you look to your south, you will see the underside of the ramp that leads up to him. Ascend this ramp and complete your training.\n\nIt was wonderful to have met you, {name}. I swell with pride knowing that among young night elves, there are some so selfless and full of life as you are. You will do great things for our people. You will do great things for this world.\n\nUntil we meet again.", objectives = "" }
WordHunterWoW_QuestEN[28731] = { title = "Teldrassil: Passing Awareness", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, {name}. There are dangerous beasts in the forests of late.", objectives = "" }
WordHunterWoW_QuestEN[28732] = { title = "This Can Only Mean One Thing...", description = "Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns, over in the Eastern Kingdoms.\n\nRaz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.", objectives = "" }
WordHunterWoW_QuestEN[28733] = { title = "Basic Botany", description = "HELP! HELP! Crazed undead are attacking my farm! That psycho warden over at the Sludge Fields is probably responsible for this mess. Help me fight off the zombies!", objectives = "" }
WordHunterWoW_QuestEN[28734] = { title = "A Favor for Melithar", description = "You should speak with Melithar. I believe he had some troubles with the grell already.\n\nI expect he can offer you a well needed place to store more of your goods should you aid him.", objectives = "" }
WordHunterWoW_QuestEN[28735] = { title = "To the Chamber of Incineration!", description = "It was an ambush, {name}! As soon as we walked in a super-fat ogre named Rom'ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the \"Chamber of Incineration.\" I think it's just down the hall across the bridge.\n\nI'm too scared to go any further. Take my all-purpose diving helm and search for Raz. I'll communicate with you through the helm.\n\nAnd if you find that ogre, kill him!", objectives = "" }
WordHunterWoW_QuestEN[28736] = { title = "Fire From the Sky", description = "The remnants of Schnottz's organization persist here on the Maker's Ascent, making the region deadly to any who draw near.\n\nThere's plenty of ammunition, but without a good spotter, I'm just firing blind.\n\nHop in and give me a hand here. Those soldiers won't know what hit them!", objectives = "" }
WordHunterWoW_QuestEN[28737] = { title = "What Is This Place?", description = "<Pip's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!", objectives = "" }
WordHunterWoW_QuestEN[28738] = { title = "The Twilight Forge", description = "<Pip's helm hums with energy.>\n\nDamn it! Raz won't stop! It's as if he were possessed with a burning vengeance for all things Twilight! It looks like if we're going to get past this room and catch up with Raz we'll need to take out the Twilight armorer, Karsh Steelbender. Kill him quick, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28740] = { title = "Do My Eyes Deceive Me?", description = "<Pip's helm explodes with the sound of a loud girlish scream.>\n\nIT CAN'T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren't for my suit and the all-purpose helm I'd have died a fiery death! And look at that, it's had a litter of pups!\n\nY... You gotta stop that thing, {name}! We can't let it or its pups make it out of here alive!", objectives = "" }
WordHunterWoW_QuestEN[28741] = { title = "Ascendant Lord Obsidius", description = "<Pip's helm buzzes.>\n\nGOOD GOLLY! Look at this place! A... Are those Deathwing's claw marks on the ceiling?! And what's that creature in the center of the chamber?\n\nI don't see Raz anywhere. Let's take care of this monster and find Raz!", objectives = "" }
WordHunterWoW_QuestEN[28742] = { title = "Shy-Rotam", description = "Time for the big kill, pal! Shy-Rotam lurks in the north, the largest frostsaber of them all.\n\nYou should feel honored. There's no fiercer game for a hunter to match their skills against... and if you saw the cash I'm being offered by gourmands that want a piece of this fellow, your eyes would pop out!\n\nOnce you've got her, head on back to camp. Don't want to totally exhaust our frostsaber population in one day...", objectives = "" }
WordHunterWoW_QuestEN[28743] = { title = "Tailgunner!", description = "You up for a little hunting, {name}?\n\nHop in! I'll fly, you shoot!", objectives = "" }
WordHunterWoW_QuestEN[28744] = { title = "Ghouls Hate My Grains", description = "You're a pro at this, {name}! A regular junior botanist! Listen, I've got a new seed to try called the rocknut. Use it to block the undead. Just drop it down and they'll stop dead in their tracks. Undead are so stupid!\n\nLet's give it a try!", objectives = "" }
WordHunterWoW_QuestEN[28745] = { title = "Screechy Keen", description = "Them smaller owls are sure tasty, but Goodgrub says there's even bigger ones further south. Screechers, the folk around here call 'em... they make a heck of a noise when you tussle with them!\n\nBut he says they're the best owls he's ever tasted or sold, and I believe him. Why don't you go rustle up some of those for us while I keep arguin' with Francis here?", objectives = "" }
WordHunterWoW_QuestEN[28746] = { title = "Penetrating Their Defenses", description = "Here we go, {name}!\n\nJust beyond that door lies the control room.\n\nI'll just run in, disable the reorigination mechanism, and then we all go home. Nice an' easy.\n\nYe see, lad, it's this level of preparation that separates yer true archaeologist from yer average treasure hunter.\n\nNo sense in stirring up the beasties if ye don't have to. Just makes a mess a' things...", objectives = "" }
WordHunterWoW_QuestEN[28747] = { title = "Someone Setup the Pumpkin Bomb", description = "You ever seen one of these?\n\n<Brazie pulls out a pumpkin.>\n\nThis ain't no ordinary pumpkin, friend. See, once you plant it they'll lay in wait until a zombie shows up and then KABLOOEY! Zombie guts all over the place. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[28748] = { title = "Lawn of the Dead", description = "IT'S STILLWATER! HE'S ALMOST HERE! It's going to take everything that we've got to beat him! Let's do this!", objectives = "" }
WordHunterWoW_QuestEN[28749] = { title = "The Battle for Andorhal", description = "We just received a gryphon from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nThey specifically asked for an Alliance {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", objectives = "" }
WordHunterWoW_QuestEN[28750] = { title = "The Battle for Andorhal", description = "We just received a windrider from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey specifically asked for a Horde {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", objectives = "" }
WordHunterWoW_QuestEN[28751] = { title = "Tending the Garden", description = "Even though we beat Warden Stillwater, his zombies still roam the countryside. Look there, another wave is approaching! Help me fight them off, old buddy! Let's go!", objectives = "" }
WordHunterWoW_QuestEN[28752] = { title = "Unstoppable Onslaught", description = "See how long you can last! Hold off at least 10 waves and I'll give you some coin.", objectives = "" }
WordHunterWoW_QuestEN[28753] = { title = "Doing it the Hard Way", description = "Blast it all!\n\nSomeone's gone and corrupted the entire system! There be no way fer me ta access the main repository from this console.\n\nWe're gunna hafta do this the hard way, lad. I hope you an' yer friends here are up to a fight.\n\nThere be four guardians on the upper level of this place. I won't be able ta utilize these discs 'til they be... uhh, offline, shall we say.", objectives = "" }
WordHunterWoW_QuestEN[28757] = { title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "" }
WordHunterWoW_QuestEN[28758] = { title = "Battle of Life and Death", description = "Alexstrasza and Deathwing have taken into the skies over Grim Batol! Her plan unravels - the Dragon Queen is outside the Circle of Life she prepared earlier. We'll need to support her with everything we've got.\n\nHurry! Climb aboard one of the Vermillion Vanguard behind me.\n\nIf we find any Twilight Drakes aiding Deathwing, we will need to kill them off. Mount up, quickly!", objectives = "" }
WordHunterWoW_QuestEN[28759] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "" }
WordHunterWoW_QuestEN[28760] = { title = "Vengeance for Orsis", description = "The great city of Orsis was attacked by the armies of air.\n\nWe were taken prisoner.  We were the lucky ones.\n\nMost died, trapped beneath the choking desert sands.\n\nAsaad, Al'Akir's caliph, ordered the attack... and he must pay with his life.", objectives = "" }
WordHunterWoW_QuestEN[28762] = { title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "" }
