WordHunterWoW_QuestEN[28768] = { title = "Winterspring!", description = "Donova Snowden, dwarf woman, is friend of the Timbermaw.\n\nWe trade firewater.\n\nShe is at Frostfire Hotsprings, to the east, through our cave.\n\nShe needs help to beat up the Winterfall furbolg.  Maybe you will help her.", objectives = "" }
WordHunterWoW_QuestEN[28769] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "" }
