WordHunterWoW_QuestEN[28775] = { title = "Broken Serpent Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "" }
WordHunterWoW_QuestEN[28776] = { title = "Broken Earthen Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "" }
WordHunterWoW_QuestEN[28777] = { title = "Broken Owl Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "" }
WordHunterWoW_QuestEN[28778] = { title = "Broken Boar Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "" }
WordHunterWoW_QuestEN[28779] = { title = "A Long Way from Home", description = "I've a feeling I was able to escape my captors because, frankly, there is nowhere to go.\n\nStranded on these platforms, they are bound to find me sooner or later.  Unless...\n\nIt is said that the heart of an elemental noble can grant whoever holds it the characteristics of that element.  Which, in the case of air, would be most useful during a downward trip.\n\nBring me Grand Vizier Ertan's heart so I can use its magic to land safely on the shoreline of Uldum.", objectives = "" }
WordHunterWoW_QuestEN[28780] = { title = "Join the Battle!", description = "I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "" }
WordHunterWoW_QuestEN[28781] = { title = "Targets of Opportunity", description = "We were part of a clandestine operation put together by Prince Nadun of Ramkahen.  We lost most of our unit during an ambush and we're now unable to finish our mission.\n\nShould you be up for it, I can arrange for a sizable reward for you.\n\nWe were instructed to take out any targets of opportunity that would damage the enemy's military infrastructure.\n\nWe've spotted General Husam and two of his captains up ahead.  Slaying them for us will be a great favor for Ramkahen.", objectives = "" }
WordHunterWoW_QuestEN[28782] = { title = "A Bird of Legend", description = "Local legend tells of a mighty owl that circles the mountaintops like death on wings.  They named her Deathwing.\n\nSoon afterwards, they were told that that name was already taken.  So they settled on a moniker that evoked a similar sense of horror and dread:\n\nHell-Hoot.\n\nHell-Hoot can be found atop the mountain to the southwest of our smoking pit.  Silence the infernal nocturnal... so we can eat her!", objectives = "" }
WordHunterWoW_QuestEN[28783] = { title = "The Source of Their Power", description = "We managed to do extensive scouting before our crew was ambushed.\n\nWe discovered that Deathwing's envoy, Siamat, is giving the Neferset their newfound power.\n\nThey claim it has restored them to the greatness of old, but something else has happened.  Their very souls have been corrupted.\n\nAs one of the four winds, Siamat is incredibly powerful.  But that power has been drained considerably by this process.\n\nStrike now, while it is possible for you to slay him and bring an end to this madness.", objectives = "" }
WordHunterWoW_QuestEN[28784] = { title = "Join the Battle!", description = "I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "" }
