WordHunterWoW_QuestEN[28798] = { title = "Waters of Elune", description = "You've found an unusual fountain; the water glows like moonlight and hums with soft tones.  With a Highborne Scroll, and your impressive skill in archaeology, you could decipher the fountain's purpose.", objectives = "" }
WordHunterWoW_QuestEN[28799] = { title = "Might of the Earthen", description = "At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.", objectives = "" }
WordHunterWoW_QuestEN[28800] = { title = "Whispers of the Djinn", description = "This brazier is obviously magical, but it seems impervious to your attempts to invoke its power.  If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", objectives = "" }
WordHunterWoW_QuestEN[28801] = { title = "Tol'vir Hieroglyphics", description = "This gravestone marks a strange burial site - possibly from one of the original builders.  If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", objectives = "" }
WordHunterWoW_QuestEN[28802] = { title = "Map of the Architects", description = "This stone obelisk is obviously some sort of layout or map, but it isn't completely readable.  Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", objectives = "" }
WordHunterWoW_QuestEN[28803] = { title = "Vengeance of the Wildhammer", description = "These old bones appear dwarven, possibly from the original builders of Grim Batol.  It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone, and discover more about this find.", objectives = "" }
WordHunterWoW_QuestEN[28804] = { title = "Dark Iron Contingency Plan", description = "These are definitely some sort of plans, but for what you aren't certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.", objectives = "" }
WordHunterWoW_QuestEN[28805] = { title = "The Eye of the Storm", description = "Greetings, {name}.\n\nYes, you are known to the Earthen Ring by name.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A familiar presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the fate of our world.", objectives = "" }
WordHunterWoW_QuestEN[28806] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "" }
WordHunterWoW_QuestEN[28808] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "" }
