WordHunterWoW_QuestEN[28813] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "" }
WordHunterWoW_QuestEN[28814] = { title = "Followers and Leaders", description = "The documents detail the arrival of High Priestess Azil to the depths of the Stonecore.\n\nAzil is described as a high-ranking member of the Twilight Council.  Additionally, her entourage of over a hundred devout followers is preparing for an unholy ritual of unforeseen darkness.\n\nSounds like an event you need to put a stop to.", objectives = "" }
WordHunterWoW_QuestEN[28815] = { title = "Twilight Documents", description = "We've tailed one of the Twilight's Hammer operatives here.  He goes by the name of Millhouse Manastorm.\n\nWe have reason to believe he's carrying important documents.\n\nThis is as far as we can safely go, however, without neglecting our duty to defend the Temple of Earth's inner perimeter.\n\nTrack down Manastorm and retrieve the documents from him.", objectives = "" }
WordHunterWoW_QuestEN[28816] = { title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there. Any information you could gather would be of great value.\n\nThe Horde is sending warships to the region as we speak. To gain passage, speak to Commander Thorak at Bladefist Bay.\n\nMay the spirits guide you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28817] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "" }
WordHunterWoW_QuestEN[28818] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "" }
