WordHunterWoW_QuestEN[28823] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "" }
WordHunterWoW_QuestEN[28824] = { title = "Wayward Child", description = "One of my children is not with me, {name}.\n\nHe stayed behind with the Twilight's Hammer at the Stonecore deep within the Temple of Earth.\n\nI sent my other children to free him from the dark magic that was surely keeping him from returning here, but... no such magic was placed upon him.\n\nGo into the Stonecore and destroy Ozruk.  He must be reclaimed by the earth.", objectives = "" }
WordHunterWoW_QuestEN[28825] = { title = "A Personal Summons", description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.>\n\nHear my words, {name}.\n\nOur world finds itself in the grip of a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am Naraat.\n\nSeek me out at once, and your calling shall be revealed.\n\nI await you at the Eastern Earthshrine in Stormwind City.", objectives = "" }
WordHunterWoW_QuestEN[28826] = { title = "The Eye of the Storm", description = "Greetings, hero of Azeroth.\n\nWe of the Earthen Ring know you by name, {name}.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A powerful presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the dilemma of our world.", objectives = "" }
WordHunterWoW_QuestEN[28827] = { title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there, so any information you could gather would be of great value.\n\nThe Alliance is sending warships to the region as we speak. To gain passage, travel northwest of Stormwind and speak to Recruiter Burns at Stormwind Harbor.\n\nMay the spirits guide you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[28828] = { title = "You Gotta Have Eggs", description = "I don't have a very discerning palate, but even I can't stand the taste of those chimaeras that you'll find around here.  Their eggs, however, are a different story.\n\nChimaera eggs are the richest, most buttery eggs you'll find this side of Orgrimmar.  Way better than boring owl eggs, and not as sulfurous as those weird wildkin eggs.\n\nI'll take as many of them as you can gather.  Head northeast, and look for their nests in the snow.", objectives = "" }
WordHunterWoW_QuestEN[28829] = { title = "Razor Beak and Antlers Pointy", description = "What happened to me, you ask?  Listen, {class}, and listen well, for my tale is one of tragedy...\n\nI was sent here to Owl Wing Thicket to find some relics.  I only made it this far before I was overwhelmed by a flurry of wings and talons.\n\nHow they roared and pecked, {class}!\n\nI now lay here, a broken orc, with nothing but vengeance on my mind. Please, {class}, if you have any sense of honor, you will go into Owl Wing Thicket and help me regain mine.", objectives = "" }
WordHunterWoW_QuestEN[28830] = { title = "Chips off the Old Block", description = "My mysterious benefactors gave me more than one task. The second task took me farther south, to the Frostwhisper Gorge. I was surprised to learn that the gorge's bridge had been broken in two, preventing land travel from one side to the other.\n\nIn addition, the juvenile Frostmaul tumblers were separated from their stronger adult parents. I thought that I could defeat them in battle.\n\nI was incorrect. I was forced to run away in shame.\n\nTeach these tumblers a lesson, {name}. Fight them, and win.", objectives = "" }
WordHunterWoW_QuestEN[28831] = { title = "Damn You, Frostilicus", description = "The Frostmaul giants wouldn't have been a problem if it weren't for that damned Frostilicus. When the ground shook and the bridge broke, he and his fellow water elementals seeped out of the earth and took over the bottom of Frostwhisper Gorge, forcing the giants out.\n\nDamn you, Frostilicus!\n\nYou would do me a great honor if you would send him back into the ground, {class}. You will find him to the south, at the bottom of the gorge.", objectives = "" }
WordHunterWoW_QuestEN[28832] = { title = "Twilight Shores", description = "Right then, just hop in the seaplane behind me and I'll fly yeh to the Highlands.\n\nWe're to report to a feller named \"Lieutenant Fawkes.\" I've promised the King we'd get there lickety-fast, so I took the liberty of ditchin' any excess weight. Like seatbelts. Parachutes. Maps. Stabilizers. Landing gear.\n\nI never actually \"land\" these things anyways.", objectives = "" }
WordHunterWoW_QuestEN[28833] = { title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nFight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. Nothing's making it past me!", objectives = "" }
WordHunterWoW_QuestEN[28834] = { title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nGo now. Fight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. I'll see that nothing makes it past me!", objectives = "" }
WordHunterWoW_QuestEN[28836] = { title = "Sins of the Sea Witch", description = "That vile worm has earned a thousand deaths!\n\nIt won't be easy. She and her minions are firmly entrenched in this place, but she's bound to be exhausted from her fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nRun her through, {name}!", objectives = "" }
WordHunterWoW_QuestEN[28837] = { title = "Altered Beasts", description = "We, the blue dragons, have been forced out of our home, Mazthoril. An impostor by the name of Umbranse has taken advantage of us in our weakest hour, and now occupies the cave.\n\nMazthoril is a place of extremely potent magic, and he does not know how to wield it. Even the wildlife suffers.\n\nThe beasts nearby have been altered. Please, {race}, I must ask you a favor. Gather their brains, so I can see if I can undo this Umbranse's wild magic.", objectives = "" }
WordHunterWoW_QuestEN[28838] = { title = "The Owlbeasts' Defense", description = "What a shame. Whatever Umbranse has done, he has prevented me from undoing his magic.\n\nHe is wiser than I had anticipated.\n\nI do have a backup plan, however. I have seen owlbeasts enter and leave Mazthoril, even after Umbranse took control. Their ancient druidic magic must be capable of disabling Umbranse's. Luckily, I happen to be somewhat of an expert in their methods.\n\nTravel south, to Dun Mandarr. You will find a chest with a dreamcatcher in it.\n\nThat will be your first step.", objectives = "" }
WordHunterWoW_QuestEN[28839] = { title = "Magic Prehistoric", description = "The owlbeasts' sacred caves are located to the east. Within several of these caves, you should find totems. I want you to approach these totems and gather whatever essence you can from them. The dreamcatcher should absorb this essence for use within Mazthoril.", objectives = "" }
WordHunterWoW_QuestEN[28840] = { title = "Winterwater", description = "I don't want our gambit to fail, {name}. Such a failure would only draw attention to our efforts, giving Umbranse an opportunity to hone his defenses. No, we have to do this right the first time.\n\nThe Frostwhisper Gorge, to the south, provides us access to powerful ice elementals. The water within these elementals' hulls should amplify the power of your dreamcatcher, ensuring our efforts.\n\nObtain this water, {name}. Then return to our small camp.", objectives = "" }
WordHunterWoW_QuestEN[28841] = { title = "The Arcane Storm Within", description = "Mazthoril's innate magic can wreak unimaginable havoc if mishandled. Umbranse's wanton casting within the cavern has opened up a number of tesseracts - in other words, portals - connecting to other worlds. If I am to return to Mazthoril, these tesseracts must be closed.\n\nThe dreamcatcher will close the portals, buying you safe entrance into Umbranse's lair. First defeat whatever comes out of the tesseracts, then use the dreamcatcher to quickly close them, before anything else spills into this world.", objectives = "" }
WordHunterWoW_QuestEN[28842] = { title = "Umbranse's Deliverance", description = "Umbranse lurks in the back of Mazthoril. His time has come.\n\nUnfortunately, I am unable to join you on this quest. While I'd love to get my hands on that snake, Mazthoril's magic would rip me apart in its current state. No, I need you to finish this for me.\n\nWhen the deed is done, use this charm. It will return you safely to the egress.", objectives = "" }
WordHunterWoW_QuestEN[28843] = { title = "Sins of the Sea Witch", description = "Naz'jar! She's the one responsible for this mess.\n\nShe's in here somewhere, {name}. She must be exhausted after that fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nI'll handle anything that tries to aid her from this direction.\n\nFind her, {name}, and run her through!", objectives = "" }
WordHunterWoW_QuestEN[28845] = { title = "The Vortex Pinnacle", description = "One of our civilian leaders was taken prisoner by the air elementals.\n\nThey are probably torturing him for information as we speak.\n\nGo to the Vortex Pinnacle, where these foul creatures came from, and look for Itesh.\n\nYou will find the entrance to the Vortex Pinnacle hovering off of the southeastern coast of Uldum.", objectives = "" }
WordHunterWoW_QuestEN[28847] = { title = "The Pursuit of Umbranse", description = "We have isolated Umbranse's position here in Winterspring. It is as I suspected.\n\nUmbranse is at Mazthoril, the cavern that once belonged to the blue dragonflight, in the southwest. My mother, Haleh, will greet you there. She is stationed outside of the cave in a small camp with a few other survivors.\n\nLook for her campfire.", objectives = "" }
WordHunterWoW_QuestEN[28848] = { title = "Trailing the Spiritspeaker", description = "I have heard tales of Umbranse, though I have not ever met him in person. Rumor has it that he's been collecting magical artifacts, though for what purpose, I couldn't say.\n\nBest pass this information on to a trusted ally. Nymn, the high elf, can be found within Everlook, the large goblin town to the northeast. Tell him all that we learned today.", objectives = "" }
WordHunterWoW_QuestEN[28849] = { title = "Twilight Skies", description = "I just got word from Orgrimmar that the Warchief wants us to move out. We wouldn't have been ready if it wasn't for your help!\n\nThe plan is for the air fleet to take off immediately, and for the navy to follow close behind. Hellscream will be accompanying the air fleet and specifically requested that you come along with us.\n\nNo time to delay! Go to the Southern Rocketway Terminus here in Azshara, and check in with Friz Groundspin. I'll bring the zeppelin around to pick you up.", objectives = "" }
WordHunterWoW_QuestEN[28850] = { title = "The Prison Rooftop", description = "I don't understand why the king wants to waste time saving his hide, but if you want to risk your life, then be my guest.\n\nCrowley and his men are holed up upstairs, probably plotting against the king as we speak!", objectives = "" }
WordHunterWoW_QuestEN[28852] = { title = "Soften them Up", description = "At last, reinforcements! I'm so glad you're here. We never imagined just how entrenched the Twilight's Hammer forces are. And there are so many!\n\nSeveral of our drakes have been captured just inside the main hall. Please, break their bonds and free them.\n\nOnce free, together we can scourge these halls clean with flame. Just climb aboard a red drake and call out your targets. You will definitely want to cut down the enemy numbers before delving deeper into the ruins.", objectives = "" }
WordHunterWoW_QuestEN[28853] = { title = "Kill the Courier", description = "Thank you, {class}, for braving the horrors of this dark and terrible place.\n\nThe bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to stop his machinations throughout the Highlands, we must learn all we can from these depths.\n\nSeek out Drahga Shadowburner within. He is Cho'gall's runner, the link between here and the Bastion of Twilight. We must learn the secrets he carries.", objectives = "" }
WordHunterWoW_QuestEN[28854] = { title = "Closing a Dark Chapter", description = "This terrible place was Alexstrasza's nightmare. During what mortals call the second war, she was chained in the depths below, her tormented offspring forced to serve the demon-corrupted Horde.\n\nAlexstrasza may be free, but the beast known as Erudax still corrupts her offspring below.\n\n<Baleflame's body tenses in anger.>\n\nDestroy him, {class}. Crush him that we may end these horrors once and for all!", objectives = "" }
WordHunterWoW_QuestEN[28856] = { title = "The Sands of Silithus", description = "Let's see... oh, here's a good one! Silithus!\n\nSo, apparently the Cenarion Circle needs assistance with an insect infestation of some sort.\n\n<Vizzie shivers.>\n\nUgh! No thanks, not for me. I'm perfectly happy freezing to death here in Everlook if the alternative is bugs.\n\nHmm... it says here that visitors should speak with Windcaller Proudhorn, and the easiest way to get there is via the path up Un'Goro Crater's northwestern cliffs.\n\nYou interested?", objectives = "" }
WordHunterWoW_QuestEN[28857] = { title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one. It says to report to Quartermaster Lungertz at Nethergarde Keep, in the Blasted Lands. That's just about as far as you can get from here!\n\nIt says they're having trouble with Horde attacks. Hmph! I didn't know the Horde even had an outpost in the Blasted Lands! They tend to worry more about demons and less about rivalries down there, as I understand it.\n\nYou'll have to cross the Great Sea, then travel south from the Swamp of Sorrows.\n\nYou interested?", objectives = "" }
WordHunterWoW_QuestEN[28858] = { title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one.  It says that members of the Horde should talk to Okrilla at Dreadmaul Hold.\n\nHmph! I didn't even know that the Horde held Dreadmaul Hold!\n\nI guess this Okrilla requires help fighting some ogres and the Alliance. You'd think she'd already have her hands full with all the demons down there!\n\nThe best way to Dreadmaul Hold is to cross the Great Sea, then to take the road south from the Swamp of Sorrows.\n\nYou interested?", objectives = "" }
WordHunterWoW_QuestEN[28859] = { title = "The Dunes of Silithus", description = "Cenarion Hold, in Silithus, is one of the biggest druid settlements in Kalimdor. Almost as big as Moonglade, mon.\n\nSomeday, maybe Zen'Aliri be headin' on over to Cenarion Hold... fightin' some Twilight's Hammer, healin' the land where the silithid tear it... but Zen'Aliri's master tells him to wait.\n\nSo Zen'Aliri waits.\n\nThe easiest way to get there is that path up Un'Goro Crater's northwestern cliffs.\n\nIf you got no master... there's nothing keepin' you from movin' on.", objectives = "" }
WordHunterWoW_QuestEN[28860] = { title = "Keeping the Dragonmaw at Bay", description = "With your help we've thumped the Dragonmaw pretty hard, but still their daily attacks in the Thundermar outskirts persist. We need to keep up the pressure!\n\nWade back into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear.", objectives = "" }
WordHunterWoW_QuestEN[28861] = { title = "Fight Like a Wildhammer", description = "<Blundy upends his cup.>\n\nI'm all outta ale, {name}!\n\nHead out into the Thundermar Ruins and see if there's any left, before those grungy Dragonmaw get their mouths on it.\n\nFeel free to have a few sips, yerself. A mug of ol' Thundermar's finest will fortify yer fightin' skills.", objectives = "" }
WordHunterWoW_QuestEN[28862] = { title = "Never Leave a Dinner Behind", description = "Refugees are still pouring into Thundermar from the fighting, and I'm hungry! I mean them. The refugees, they're hungry.\n\nGet me some food from the Thundermar Ruins! Scour the ruins to the south, east, and southwest for any stores that still remain. Especially them big hocks of ham. I love those! Er, the refugees do.\n\nAnd see if you can find some of them little cocktail weenies.", objectives = "" }
WordHunterWoW_QuestEN[28863] = { title = "Warlord Halthar is Back", description = "He's at it again, {name}. Warlord Halthar... terror of the shire. He and his drake were spotted causing trouble to the south, among the Thundermar Ruins.\n\nKill Halthar, {name}! We'll send in some warbrands to help out once you engage.", objectives = "" }
WordHunterWoW_QuestEN[28864] = { title = "Beer Run", description = "After my sister's wedding, I developed a taste for that Thunderbrew Lager that Kurdran had imported from Dun Morogh. More is on the way, but our caravan keeps getting jumped by the Dragonmaw!\n\nHead on up to the southeast side of Thunderstrike Mountain and catch up with the caravan. Look for a fellow named Hammelhand at the side of the road, and help him get the booze through the pass.\n\nJust get it as far as Kirthaven, and we'll take it from there.", objectives = "" }
WordHunterWoW_QuestEN[28865] = { title = "Call of the Warmatron", description = "Our venerable warmatron, Okrilla, has sent me to the far reaches of the world in search of suitable heroes that would join our cause. Are you interested in strengthening the Horde's grasp over the Eastern Kingdoms? Then take this portal to the Blasted Lands and report to Okrilla at Dreadmaul Hold!", objectives = "" }
WordHunterWoW_QuestEN[28866] = { title = "Into the Stonecore", description = "You say that this Millhouse Manastorm and High Priestess Azil were to meet inside the Stonecore?\n\nSounds big.  We'd best get on their trail.  We don't want the Twilight's Hammer pulling off something big right under our noses.\n\nSpeak to Earthwarden Yrsa inside the Stonecore.  She's been stationed there to make sure the Twilight's Hammer doesn't try to retake the Temple of Earth.", objectives = "" }
WordHunterWoW_QuestEN[28867] = { title = "Nethergarde Needs You!", description = "Nethergarde needs you, {class}! I have been sent here by Quartermaster Lungertz to head off Okrilla's nefarious lackeys and to recruit able-bodied heroes of the Alliance! Help us fight off the Horde!\n\nIf you are willing, take this portal in front of me to the Blasted Lands and speak with the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[28868] = { title = "The View from Down Here", description = "We need to halt the construction on this Frostmane village. If we let them get too entrenched, it will be more difficult to keep them from settling here permanently.\n\nIt's time to give those brutes a gnome's-eye view of the world! Take this gnomish viewpoint equalizer and use it on the Frostmane builders to bring them down to our level. They won't be able to lift their tools and construction will come to a standstill.", objectives = "" }
WordHunterWoW_QuestEN[28869] = { title = "Pebble", description = "If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him.\n\nYou seem to be quite adept at making friends down here. A good talent to have.", objectives = "" }
WordHunterWoW_QuestEN[28870] = { title = "Return to the Lost City", description = "We might've taken Neferset City, but the Neferset have a new seat of power.\n\nThanks to Siamat, the powerful djinn of the south wind, the Neferset have become considerably more dangerous.\n\nWe just learned that some of Nadun's ambushed reconnaissance party managed to secure the entrance to the Lost City.\n\nGo find Captain Hadan and get whatever information you need to bring down Siamat and the Neferset scum.", objectives = "" }
WordHunterWoW_QuestEN[28871] = { title = "Crushing the Wildhammer", description = "The Wildhammer grow bold with their new Alliance allies. They dare press across the river. Drive them back!\n\nSeek out and crush the Wildhammer warbrands who fight in the riverbed and within the Thundermar Ruins along the north bank. The best among them carry insignias - gather them for me to prove your allegiance to the Dragonmaw cause.", objectives = "" }
WordHunterWoW_QuestEN[28872] = { title = "Total War", description = "Some of the Wildhammer still cling to the hope of reclaiming the Thundermar Ruins to the north, across the river. Burn them out! Smash open kegs of Thundermar ale. That wicked brew is potent enough to explode when set aflame.\n\nDon't ask me why.\n\nAnd don't ask me how they drink the stuff.", objectives = "" }
WordHunterWoW_QuestEN[28873] = { title = "Another Maw to Feed", description = "<Griff's stomach growls.>\n\nStill hungry. It's like ... every day, I'm hungry.\n\nI hear there's more food stashed up in the Thundermar Ruins across the river to the north, where all the fighting is. Bring some to my mouth.", objectives = "" }
WordHunterWoW_QuestEN[28874] = { title = "Hook 'em High", description = "The Wildhammer can train war gryphons faster than we can subvert and control drakes. We can't let them continue to outnumber us!\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Kill the dismounted gryphon riders!", objectives = "" }
WordHunterWoW_QuestEN[28875] = { title = "Bring Down the High Shaman", description = "Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river.\n\nHe's a dangerous one, {name}, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question.\n\nThe question is: will you be the one to earn the glory of the kill?", objectives = "" }
WordHunterWoW_QuestEN[28876] = { title = "To the Mor'shan Rampart", description = "Kadrak at the Mor'shan Rampart to the north is calling for aid.\n\nThe rampart rests on the border between the Northern Barrens and Ashenvale. It is the front line in the fight against the Alliance.\n\nWe're driving the night elves out of the forest. We'll claim its resources for the Horde!\n\nTo get there, take the Gold Road north out of the Crossroads.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[28878] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[28879] = { title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our daddy now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki? ", objectives = "" }
WordHunterWoW_QuestEN[28880] = { title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.", objectives = "" }
WordHunterWoW_QuestEN[28881] = { title = "Prospector Gunstan", description = "Say... you haven't been to Southmoon Ruins yet, have you?  Oh you simply MUST.  They have all sorts of fascinating titan artifacts.  Head west, and look for the Explorers' League tents.", objectives = "" }
WordHunterWoW_QuestEN[28882] = { title = "Victory in Tol Barad", description = "We fought hard to get a foothold on this ugly rock and there is no way we are going to let the Horde get in the way of our plans.  Keeping control of Tol Barad is our first priority and we need your help, {name}.  Fight your way to victory in Tol Barad and return to me word of your triumph.", objectives = "" }
WordHunterWoW_QuestEN[28884] = { title = "Victory in Tol Barad", description = "Maintaining control of Tol Barad is the key to our strategic plans here in the Eastern Kingdoms, {race}.  We must do whatever it takes to keep the Alliance off this island and that means we need your help.  Fight with everything you have to win control of Tol Barad and bring me word of victory.", objectives = "" }
WordHunterWoW_QuestEN[28885] = { title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[28907] = { title = "Daily Normal Random (1st)", description = "", objectives = "" }
WordHunterWoW_QuestEN[28909] = { title = "Sauranok Will Point the Way", description = "I see you haven't yet spoken to the Warchiefs... other... advisor, Sauranok the Mystic. He has been at their side since our campaign together in Northrend.\n\nTo assault the Twilight Highlands, we're going to need a map of the shoreline. I have tasked Sauranok with digging up this information. See if he can use your assistance!", objectives = "" }
