WordHunterWoW_QuestEN[29015] = { title = "Miner's Fortune", description = "Hey {race}, you interested in treasure? I knew that would get your attention.\n\nWord from the river dock here is that one of the miners in the Venture Company's Boulder Lode mine just northeast of here discovered an emerald the size of your fist.\n\nI know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale. You in?", objectives = "" }
WordHunterWoW_QuestEN[29016] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[29017] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[29018] = { title = "Candy Bucket", description = "", objectives = "" }
