WordHunterWoW_QuestEN[29020] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[29021] = { title = "Samophlange", description = "The Venture Company have a small research facility west of here, just past the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", objectives = "" }
WordHunterWoW_QuestEN[29022] = { title = "Samophlange", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", objectives = "" }
WordHunterWoW_QuestEN[29023] = { title = "Samophlange", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", objectives = "" }
WordHunterWoW_QuestEN[29024] = { title = "Samophlange", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", objectives = "" }
WordHunterWoW_QuestEN[29026] = { title = "Wenikee Boltbucket", description = "I think I really put my foot into that one - it looks like I might have knocked one of the load-bearing fluxors into the spokes of the deregulator gear. We can fix this, easy. I know an expert on triple-expansion piston drives who would love to get her hands on a samophlange. Take the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, she'll patch 'er right up.\n\nHey, no need to walk - this gives me the perfect opportunity to test my personal people porter device!", objectives = "" }
WordHunterWoW_QuestEN[29027] = { title = "Nugget Slugs", description = "I want to fix this samophlange, but to do that I'm going to need some supplies. I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nUnfortunately, the closest place to get them is the Burning Blade farm to the southwest. The place will be heavily guarded, so be careful, but the samophlange just might be worth the risk. Search the tool buckets, then return to me when you've gathered enough nugget slugs.", objectives = "" }
WordHunterWoW_QuestEN[29028] = { title = "Into Jaedenar", description = "The Shadow Council corrupts this once beautiful forest from their stronghold, Jaedenar, in the northwest.\n\nNow, one of our own is missing. We sent a lone scout by the name of Andalar Shadevale to Jaedenar, in hopes of thinning the enemy's ranks by stealth. \n\nWe have not heard from him in days, and we fear the worst. There is a small chance he may still be alive. {name}, please go at once and find him!", objectives = "" }
WordHunterWoW_QuestEN[29029] = { title = "Dying Knowledge", description = "<The corrupted water bubbles and froths, as if trying to break free from itself.>\n\nTake this water to our scout in the field. He should be able to purify it for our attack on the Shadow Hold's defenses!", objectives = "" }
WordHunterWoW_QuestEN[29030] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29031] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29032] = { title = "Get Them While They're Young", description = "I can teach you to ride a Winterspring frostsaber, but it takes time and dedication. For this to work, both saber and rider must be highly trained and both must share a bond of deep trust.\n\nThe cubs are only receptive to this training if they're introduced to their riders at a young age. Some of the cubs in the dens surrounding Frostsaber Rock are at the proper age to begin their training. If you help me gather the most promising of those cubs, I'll allow you to begin training with your own cub.", objectives = "" }
WordHunterWoW_QuestEN[29033] = { title = "[PH] Bridle Buy-In", description = "", objectives = "" }
WordHunterWoW_QuestEN[29034] = { title = "They Grow Up So Fast", description = "I think this little fellow will be a good match for you.\n\nThis cub is going to require a lot of attention to ensure that he grows up strong and healthy. You should check up on your cub at least once each day. Feeding and caring for your Winterspring cub is the best way to build a bond of trust with him.\n\nAs your cub grows, he will shed his old whiskers and grow new ones appropriate to his size. Once your cub has shed twenty whiskers, bring him back to me along with some materials for your saddle.", objectives = "" }
WordHunterWoW_QuestEN[29035] = { title = "A Cub's Cravings", description = "Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring.", objectives = "" }
WordHunterWoW_QuestEN[29036] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29037] = { title = "'Borrowing' From the Winterfall", description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat licks its lips. It must be meal time again! As the cub's surrogate father you're responsible for providing meat until it can hunt on its own.\n\nBut what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.", objectives = "" }
WordHunterWoW_QuestEN[29038] = { title = "Hunting Practice", description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring. Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.", objectives = "" }
WordHunterWoW_QuestEN[29040] = { title = "Cub's First Toy", description = "The winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.", objectives = "" }
WordHunterWoW_QuestEN[29054] = { title = "Stink Bombs Away!", description = "Greetings, {class}!  I hope Hallow's End is treating you well.  Bah, enough of the small talk... Let's get down to business.  Undercity.  They have employed Hags and foul magic to launch petty attacks on our town.  Some may say, ignore the childish Horde.  I say, let's show them!\n\nSpeak to my sister, Gertrude, and she will send you on your way to toss some stink bombs in Undercity.", objectives = "" }
WordHunterWoW_QuestEN[29066] = { title = "Good News... and Bad News", description = "<Blackhorn used the power of Thol'embaar's remains to slip his bonds. But at least the inferno seems to be subsiding.>\n\n<Matoclaw will want to know what happened here. She's waiting for you back at the Grove of Aessina.>", objectives = "" }
WordHunterWoW_QuestEN[29071] = { title = "Make Haste to Stormwind!", description = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at The Golden Keg in the Dwarven District.", objectives = "" }
WordHunterWoW_QuestEN[29073] = { title = "Make Haste to Orgrimmar!", description = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at The Golden Keg in the Dwarven District.", objectives = "" }
WordHunterWoW_QuestEN[29074] = { title = "A Season for Celebration", description = "Merry met, {class}!\n\nHallow's End is a time for celebration and reflection, though many of us have forgotten why. Indeed some aspects of the festival, like the Wickerman, had been lost to time... until the Gilneans returned to the Alliance fold.\n\nTravel outside the gates of Stormwind and speak to Celestine of the Harvest. She can tell you more about the Wickerman ceremony.", objectives = "" }
WordHunterWoW_QuestEN[29075] = { title = "A Time to Gain", description = "Greetings, {class}.  The Wickerman you see before you symbolizes self.  The flames that burn it are a cleansing fire.\n\nTradition states that we take our burdens and give them to the fires.  We let go of our burdens as we approach the winter season and we gain clarity and peace.  Join us in our tradition, {class}.\n\nTake a branch from the nearby bonfire and hurl it at the Wickerman.", objectives = "" }
WordHunterWoW_QuestEN[29078] = { title = "Beating Them Back!", description = "Another Alliance recruit, eh? I'm Marshal McBride, commander of this garrison. We don't see many of your kind here, {race}, but we could sure use the help.\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "" }
WordHunterWoW_QuestEN[29079] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "" }
WordHunterWoW_QuestEN[29080] = { title = "Join the Battle!", description = "I have here an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "" }
WordHunterWoW_QuestEN[29081] = { title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[29082] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "" }
WordHunterWoW_QuestEN[29083] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "" }
WordHunterWoW_QuestEN[29086] = { title = "Competition Schmompetition", description = "I'm just a little guy, trying to set up my own independent business. Working hard toward the Azerothian dream, ya know?\n\nWell soon as I set up shop, the Venture Co. next door decided they wanted me out. They've been harrassing me with threatening letters, using words like 'cease' and 'desist.' \n\nWorst of all, the schematics for my newest machine are missing, and I know those corporate pilferers stole them! Go to the Sludge Fen and knock out some of their employees. I know they're hiding my blueprints!", objectives = "" }
WordHunterWoW_QuestEN[29087] = { title = "Sludge Investigation", description = "Hey {name}, do you see this footprint? We found them all over the camp last night! Nothing's missing, but all our belongings have been...examined. The muddy trails lead back toward the Sludge Fen.\n\nSomeone's been sniffing around, and I don't like it one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more tracks just like this one!", objectives = "" }
